INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a2a3638c7aa8b396', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who is the Current Chief Justice of Pakistan (CJP)?', '{"A":"Justice Umar Ata Bandial","B":"Justice Qazi Faez Isa","C":"Justice Yahya Afridi","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The current Chief Justice of Pakistan is Yahya Afridi. Position: 30th Chief Justice of PakistanTook Office: October 26, 2024He replaced Qazi Faez Essa.Retirement: 22 January 2030He will serve as CJP until 2027.Additional information:Born on 23 January 1965 in Kohat.Appointed as an Additional Judge of the Peshawar High Court in 2010.He became the judge in Supreme Court of Pakistan in 2018.Last updated by NS on 06-09-2026​Click here for reference', 0, 0, 0, 1790967393695) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7cbcc71b4f37f7db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'K-2 is also known as?', '{"A":"Godwin Austin","B":"Broad Peak","C":"Roshan Peak","D":"Sia Kingri"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: K2 (Godwin-Austen), Chhogori, Ketu, K2 (Karakoram-2)Range: Karakoram RangeLocation: Pakistan–China borderHeight: 8,611 mRank: 2nd highest in the world.Last verified on 11-06-2026', 0, 0, 0, 1790967393695) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cd3b327043b5a7d2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The first nuclear power plant in Pakistan was established at ____?', '{"A":"Karachi","B":"Lahore","C":"Islamabad","D":"Fasilabad"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first nuclear power plant was established in Karachi, With the help of Canada KANUPP is Pakistan''s first nuclear power plant, Inaugurated on November 28, 1972, Total gross capacity of 137 MW.Additional informationK2 & K3 with the help of China K2 started on 21 May 2021 and has an 1100 MW capacity.K3 is expected to start in 2022.Last updated 18-07-2026 by NA', 0, 0, 0, 1790967393695) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9dbfeba62cb62f85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan conducted nuclear tests on May 28, 1998 at?', '{"A":"Kohe-e-Sufaid","B":"Chaghi Hills","C":"Toba Kakar","D":"Raskoh"}', 'B', NULL, 0, 0, 0, 1790967393695) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fbff1ce10dc7f403', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who became first Nobel Prize Laureate in the history of Pakistan?', '{"A":"Dr Abdul Qadeer Khan","B":"Malala Yousafzai","C":"Dr Abdul Salam","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Nobel laureate in Pakistan: Dr. Abdus Salam — 1979, PhysicsAdditional information:Last/most recent Pakistani Nobel laureate: Malala Yousafzai — 2014, PeaceFirst Nobel laureate from Asia: Rabindranath Tagore — 1913, LiteratureFirst Nobel laureate in the world: Emil von Behring — 1901, Physiology or MedicineLast verified on 07-09-2026', 0, 0, 0, 1790967393695) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0576c6dc74b124ec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Zakat and Ushr Ordinance was promulgated on _____?', '{"A":"29th June 1981","B":"20th June 1980","C":"21st August 1979","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date: 20 June 1980Introduced by: General Muhammad Zia-ul-HaqZakat Rate: 2.5% on savingsUshr: Tax on agricultural producePurpose: Poverty alleviation and welfare distributionLast verified on 12-06-2026', 0, 0, 0, 1790967393695) ON CONFLICT(id) DO NOTHING;
