INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3a7440c36b3ec7cf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The oldest Hydro-electric Project in Pakistan is _____?', '{"A":"Dargai","B":"Rasul","C":"Warsak","D":"Malakand Dargai"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Official Name: Jabban Hydropower Plant (Malakand-I)Location: Swat Canal, Malakand DivisionOpening Date: July 1938Water Source: Upper Swat CanalHistorical Significance: One of Pakistan’s oldest hydropower projectsFire Incident: The powerhouse was badly damaged by fire on 11 December 2006.Last updated: NA on 26-09-2026', 0, 0, 0, 1790967393715) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3176bf7ad81f4b4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Iskander Mirza was died in _____?', '{"A":"13 November 1969","B":"13 November 1968","C":"13 November 1967","D":"13 November 1966"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date: November 13, 1969 (on his 70th birthday)Place: London, EnglandCause: Heart attack (myocardial infarction)Born: 13 November 1899, Murshidabad, India1st President of Pakistan: 23 March 1956Last Governor-General: 1955–1956Political Party: Republican PartyAbrogated: 1956 ConstitutionLast updated by NA ON 16-09-2026', 0, 0, 0, 1790967393715) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_26536b0495bb754d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan`s largest seaport is ?', '{"A":"Port of Karachi","B":"Muhammad Bin Qasim Port","C":"Gwadar port","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Largest & busiest seaport: Port of KarachiLocation: Karachi, Arabian SeaCargo handled: About 60% of Pakistan’s cargoHarbour size: 32 kmOpened: 1857Additional information:Muhammad Bin Qasim Port: Also called Port Qasim; located near Karachi.Gwadar Port: Deep-sea port in Balochistan; developed as part of CPEC.', 0, 0, 0, 1790967393715) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c8ddec9f658f86cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Census in Pakistan held after how many years?', '{"A":"5 years","B":"10 years","C":"15 years","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A national census in Pakistan is legally mandated by the constitution to be held every 10 yearsFirst 1951Second 1961Third 1972Forth 1981Fifth1998 Sixth 2017Seventh 2023', 0, 0, 0, 1790967393715) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b346f1455dede96e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who is called the Founder of Pakistan?', '{"A":"Allama Iqbal","B":"Sir Syed Ahmed Khan","C":"Liaqat Ali Khan","D":"Quaid-e-Azam"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam Muhammad Ali Jinnah is known as the Founder of Pakistan.His real name was Muhammad Ali Jinnah.Pakistan became independent on 14 August 1947.He served as the first Governor-General of Pakistan from 1947 to 1948.He is also known as Quaid-e-Azam, meaning “Great Leader.”Last verified on 14-09-2026', 0, 0, 0, 1790967393715) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b6c6c493d9f759f2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is the name of Muslim Scientist who presented the concept of blood pressure?', '{"A":"Ibn un Nafees","B":"Ibn al-Hashim","C":"Ibn Baitar","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Scientist Name: Ibn al-NafisDate / Year: 1242 CEMajor Work: Commentary on Anatomy in Avicenna''s CanonHe was a pioneering Arab physicianMajor contribution: Pulmonary circulationBlood pressure: Modern measurement/concept developed centuries later.', 0, 0, 0, 1790967393715) ON CONFLICT(id) DO NOTHING;
