INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_749f1ec7cb9e23d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which year Pakistan won the Cricket World Cup?', '{"A":"1990","B":"1980","C":"1970","D":"1992"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan won the Cricket World Cup in 1992Edition: FifthFormat: One Day International (ODI)Venue: Australia & New ZealandFinal held: 25 March 1992Final Venue: MelbourneWinner: Pakistan (First title)Runners-up: EnglandParticipating teams: 09Total Matches: 39Most wickets taken by: Wasim Akram (18 wickets)**** Question updated on 11-02-2026', 0, 0, 0, 1790967394718) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_de3a55b8eb6dfee5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Where was Sir Syed Ahmed Khan born?', '{"A":"Agra","B":"Madras","C":"Delhi","D":"Bengal"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sir Syed Ahmed Khan was born in 1817 in Delhi.He was died in 1898 and buried in Aligarh.He was an Islamic reformer and philosopher.Two nation theory first time introduced by Sir Syed Ahmed.He received his early education from his Maternal Grand Father.Mir Muttaql was the father of Sir Syed Ahmed Khan.Last verified 09-03-2026', 0, 0, 0, 1790967394718) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cf4eb9a7da3bdf38', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Currently largest share in Pakistan’s Electricity generation comes from ______?', '{"A":"Coal Energy","B":"Thermal Energy","C":"Hydel Energy","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Pakistan, the largest share of electricity generation comes from Thermal Energy.Thermal power plants generate electricity using coal, oil, and natural gas.Additional information:One of the largest thermal power plants is Kot Addu Power Company (KAPCO) in Kot Addu, Punjab.Capacity: Approximately 1600 MW, making it one of Pakistan’s major electricity-producing plants.Last verified on 09-03-2026', 0, 0, 0, 1790967394718) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0716bb7389b838e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Lower House of Pakistan is Called?', '{"A":"National Assembly of Pakistan","B":"Senate of Pakistan","C":"Assembly of Pakistan","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation National Assembly Founded in 1947, Karachi.National Assembly is the Lower House of Parliament.Senate is the Upper house of Parliament.Old member 342 now 336.NamePunjabSindhKPKBaluchistanICTTotalGeneral1416145163266Women3214104-60Non-Muslims-----10Total1737555203336Last verified on 08-03-2026', 0, 0, 0, 1790967394718) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d40c66c66ecdff92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Total length of Makran coastal highway that connects Karachi and Gawadar is _______ Km?', '{"A":"553","B":"653","C":"753","D":"853"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Makran Coastal Highway (N10) spans 653 km (406 mi).It connecting Karachi to Gwadar.Construction began in 2002.It was completed in 2004, with the highway operational since 2004.Last verified on 08-03-2026', 0, 0, 0, 1790967394758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9dd8f95265c1822c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Motorway M2 is between which two of the following cities?', '{"A":"Lahore to Islamabad","B":"Multan to Sukkur","C":"Lahore to Karachi","D":"Lahore Peshawar"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The M-2 Motorway connects Lahore and Islamabad.Additional information:Length: 375 kmConstructed: 1992North End: Kashmir Highway Interchange, IslamabadSouth End: Thokar Niaz Baig, LahoreLast verified on 07-03-2026', 0, 0, 0, 1790967394758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6fc36248c450b57b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan won the Olympics gold medal for the last time in which game?', '{"A":"Swimming","B":"Hockey","C":"Javelin Throw","D":"Badminton"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan won an Olympic gold medal most recently at the 2024 Paris OlympicsMost Recent Gold: 2024 (Arshad Nadeem, Javelin Throw)Last Hockey Gold: 1984 (Los Angeles)Previous Hockey Golds: 1968 (Mexico City), 1960 (Rome) Total Official Medals: 10Gold Medals: 3 (all in Men’s Field Hockey)Pakistan won gold in hockey in 1960, 1968, and 1984.Last verified on 07-03-2026', 0, 0, 0, 1790967394758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_40863c1fdc7fb2dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The first rocket launched by Pakistan was ______?', '{"A":"Rehbar","B":"Badar","C":"Sputnic","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first rocket launched by Pakistan was Rahbar-1 (also spelled Rehbar-1).Rehbar-I, a two-stage solid fuel rocket, It was launched on June 7, 1962Launched by SUPARCO SUPARCO stands for Space and Upper Atmosphere Research Commission.Last updated on 06-March-2026', 0, 0, 0, 1790967394758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7b56b97bc2f9d093', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pak China Boundary line was demarcated during the era of _______?', '{"A":"Zulfikar Ali Bhutto","B":"Ayyub Khan","C":"Nawaz Sharif","D":"Ch Muhammad Ali","E":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Pak-China boundary line was demarcated during the era of President Ayub Khan. Signed on 2 March 1963.Signed by Zulfikar Ali Bhutto (Pakistan) and Chen Yi (China)The Pak-China agreement is called the Sino-Pak border Last updated on 06-March-2026', 0, 0, 0, 1790967394758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_dd218cd360895ec4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Dr. Abdul Qadeer Khan obtained his physics degree from___?', '{"A":"Belgium","B":"France","C":"USA","D":"Karachi"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dr. Abdul Qadeer Khan obtained a Bachelor''s (Physics): University of Karachi (1956)Master''s/Engineer''s Degree: Delft University of TechnologyPhD (Metallurgical Engineering): Katholieke Universiteit Leuven, Belgium Born on 1st April 1936 in Bhopal, IndiaTitle: Mohsin-e-PakistanDied on 10 October 2021Died at age of 85 with lung problems.Founded: Tehreek-e-Tahaffuz-e-Pakistan (TTP)Last updated on 06-March-2026', 0, 0, 0, 1790967394758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cb2ec0f8e7f907e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The first constituent assembly of Pakistan was dissolved mainly due to ______?', '{"A":"Governor-General''s intervention","B":"Military intervention","C":"Lack of quorum","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Constituent Assembly of Pakistan (1947–1954) was tasked with framing the constitution.It was dissolved by Governor-General Ghulam Muhammad on 24 October 1954.Additional information:Assembly formed: 10 August 1947First Prime Minister: Liaquat Ali KhanConstitution eventually passed: 1956Last verified on 07-02-2026', 0, 0, 0, 1790967394758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d7caa14125701760', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The mount Godwin Austen is the name of ______?', '{"A":"Mount Everest","B":"K2","C":"Nanga Parbat","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation K2 World 2nd highest mountainK2 Elevation: 8,611 mK2 First ascent: July 31, 1954K2 Mountain range: Karakoram rangeK2 First ascenders: Achille Compagnoni, Lino LacedelliK2 Easiest route: Abruzzi SpurLast verified on 06-03-2026', 0, 0, 0, 1790967394758) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7ad0d0b8b5de748e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which year Urdu Hindi controversy?', '{"A":"1867","B":"1868","C":"1866","D":"1860"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Urdu-Hindi controversy officially began in 1867 in IndiaIt started in the United Provinces of Agra and OudhHindus demanded that Hindi be an official language in place of UrduIn 1881, Hindi replaced Urdu in the Devanagari script in Bihar,The demand grew significantly in 1867 in BanarasQuestion updated 03-March-2026', 0, 0, 0, 1790967394800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9fa8c6b1cac5b4c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Nehru report was preparedic in the chairmanship of', '{"A":"Motilal Nehru","B":"Gandhi","C":"Jawahar lal Nehru","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Nehru Report was prepared under the chairmanship of Motilal Nehru.He was a senior leader of the Indian National Congress and led the committee in 1928.Aimed: propose a constitutional framework for self-government in India.Published on August 28, 1928, at the Lucknow conference.Last updated 18-02-2026', 0, 0, 0, 1790967394800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fd3b6f7a5e74f2bd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Malakhra is a traditional game of _____, Pakistan?', '{"A":"Punjab","B":"Sindh","C":"Baluchistan","D":"KPK","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Malakhra is a traditional game of Sindh, PakistanOrigin: It dates back 5,000 years to the Indus Valley Civilization.Competitors, known as malhooThe match begins with both wrestlers (known as malhoos or mulhs)Last updated question 18-02-2026', 0, 0, 0, 1790967394800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6d0e9e233c5ff4ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Zulfiqar Ali Bhutto introduced land reforms and reduced the landholding limit to 150 acres for irrigated land and 300 acres for barani land in?', '{"A":"1973","B":"1974","C":"1972","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zulfikar Ali Bhutto''s first speech on December 20, 1971, focused on introducing reforms and tackling corruption.The 1972 Land Reforms limited individual holdings to 150 acres of irrigated and 300 acres of un-irrigated land.Excessive land holdings were taken over without compensation.Over 800,000 acres of agricultural land were redistributed.Last verified on 12-02-2026', 0, 0, 0, 1790967394800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b82be94bdaa94b0d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which year West Pakistan become One Unit?', '{"A":"1955","B":"1956","C":"1957","D":"1958"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The One Unit was the reorganization of the provinces of Pakistan Prime Minister Muhammad Ali Bogra led it on 22 November 1954Passed on 30 September 1955This program merged the four provinces of West Pakistan into a single province to parallel the province of East PakistanWest PunjabSindNWFPBaluchistanAdditional information:The One Unit scheme was dissolved on July 1, 1970General Yahya Khan imposed Legal Framework Order No. 1970 to end the programand reinstate the provisional status of the Four Provinces as of August 1947.', 0, 0, 0, 1790967394800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8e22eb687eb6f311', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Kashmir Solidarity Day is celebrated in Pakistan on which date?', '{"A":"February 4","B":"February 7","C":"February 5","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kashmir Solidarity Day or Kashmir Day is a national holiday observed in Pakistan Date: February 5Kashmir Day Event Length: 1 DayKashmir Day Related to the Kashmir ConflictKashmir Day was Started by: Jamaat-e-Islami Pakistan in 1990Kashmir Day was first proposed by Qazi Hussain Ahmad In 1991, the then-Prime Minister of Pakistan Nawaz Sharif called for a "Kashmir Solidarity Day Strike"', 0, 0, 0, 1790967394800) ON CONFLICT(id) DO NOTHING;
