INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1504b300693613ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan last census was held in?', '{"A":"2019","B":"2018","C":"2023","D":"2016"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan''s last census, the 7th Population & Housing Census, was indeed held in 2023 from March to May 2023Recorded Pakistan''s population at 241.5 million (approx.).Pakistan''s Constitution requires a census every 10 years.There are the Total Seven Census held in Pakistan1951 (First census)1961 (Second census)1972 (Third census)1981 (Fourth census)1998 (Fifth census)2017 (Sixth census)2023 (Seventh, first digital census) Next 2033', 0, 0, 0, 1790967394886) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a99f63c931867555', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which is the highest battlefield in the world?', '{"A":"The Siachen Glacier","B":"Tibet","C":"Jafana","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The highest battlefield in the world is the Siachen GlacierA military dispute between India and Pakistan began on April 13, 1984.It has an average altitude of about 6,000 meters (20,000 feet).It is also known as the Siachen Glacier conflict.It is located in the Karakoram range in Kashmir.', 0, 0, 0, 1790967394886) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fcaa332670712c5c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Constantinople fell into the hands of Muslims in which year?', '{"A":"1453 AD","B":"1553 AD","C":"1353 AD","D":"1396 AD"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date of Conquest: 29 May 1453Siege Duration: 55 daysOttoman Sultan: Mehmed II (Mehmed the Conqueror)Significance: End of Byzantine Empire; start of Ottoman dominance in Eastern EuropePopulation of Constantinople at Fall: ~50,000 – 80,000Last verified on 18-01-2026', 0, 0, 0, 1790967394927) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9d4d7c20b1c31ea8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'First underground drainage system was introduced by which civilization?', '{"A":"Harpa civilization","B":"Ghandhara  civilization","C":"Indus valley civilization","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first underground drainage system in history was introduced by the Indus Valley Civilization (IVC).Additional information:Time Period: 3300 BCE – 1300 BCE (entire civilization)Mature Phase: 2600–1900 BCEMajor Cities with Drainage: Mohenjo-daro, Harappa, Dholavira, Lothal, KalibanganNumber of Main Drains in Mohenjo-daro: Over 700 household drains connected to covered sewersPopulation Estimate: Around 1–2 million people in urban centersLast verified on 18-01-2026', 0, 0, 0, 1790967394927) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_19c5b0ece4660b71', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the First Muslim Musician in sub-continent?', '{"A":"Qulli Qutab Shah","B":"Ameer Khusro","C":"Wali Dakni","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ameer Khusro (1253–1325 AD) was a famous Sufi poet, scholar, and musician in the Indian subcontinent.He was served under Sultan Alauddin Khilji and later Ghiyasuddin Tughlaq.Additional information:Birth Year: 1253 ADDeath Year: 1325 ADAlso called as: “Tuti-e-Hind” (Parrot of India)Last verified on 18-01-2026', 0, 0, 0, 1790967394927) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2aca6bbd68f6f921', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'FATF removed Pakistan from grey list after four years on which date?', '{"A":"11 October 2022","B":"21 October 2022","C":"22 October 2022","D":"16 October 2022"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Financial Action Task Force (FATF)Added to Grey List: June 2018Removed from Grey List: 21 October 2022Duration on Grey List: ~4 yearsVotes required to exit Grey List: 12 out of 39Additional related updates (2023):South Africa & Nigeria added to Grey List on 24 February 2023Cambodia & Morocco removed from Grey List on 24 February 2023', 0, 0, 0, 1790967394927) ON CONFLICT(id) DO NOTHING;
