INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b08ab1a6dcd1831f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following mineral deposits are found in Potwar Plateau?', '{"A":"Rock Salt","B":"Gypsum","C":"Oil","D":"All of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Potwar Plateau includes parts of the districts of Jhelum, Chakwal and Rawalpindi.The Pothohar plateau is rich in minerals like gypsum, limestone, coal, oil and rock salt. *************FIA CBT VU PAPER 22-12-2021', 0, 0, 0, 1790967395079) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fd04f785d656a53f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'One Unit was established in West Pakistan in ______?', '{"A":"September 20, 1955","B":"September 10, 1955","C":"September 01, 1955","D":"September 30, 1955"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 30 September, 1955Until 1970Idea of Muhamad Ali Bogra ,named Bogra Formula.Implemented by Ch. Muhammad Aliagm.04.03.23', 0, 0, 0, 1790967395079) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_76b02c005fc0571d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Establishment of Delhi Sultanate begin with the invasion of _____?', '{"A":"Muhammad Ghouri","B":"Muhammad Tuglaq","C":"Allahuddin Khilji","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1192, the Afghan warrior Muhammad Ghori defeated the Rajput Confederacy, led by Prithviraj Chauhan, near Tarain.After Ghori''s death in 1206, his generals divided the Ghurid territories and established the Delhi Sultanate.Qutb ud-Din Aibak, a slave soldier and Ghori''s army commander, became the new sultan of Delhi.', 0, 0, 0, 1790967395079) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5cea8243d4240dc7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'CNIC stands for _______?', '{"A":"Computerized National Identity Card","B":"Complete Nationality Identity Card","C":"Computerized National Information Card","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CNIC Stands for Computerized National Identity CardThe CNIC was introduced in 2000NADRA Founded: March 10, 2000, IslamabadNADRA Headquarters: Islamabad***HistoryPakistan initiated its National Identity Card System in 1973 under Article 30 of the Second Amendment.The first NIC being that of Zulfiqar Ali Bhutto, the Prime Minister of the time', 0, 0, 0, 1790967395079) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d1b6282f05105b42', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Single National Curriculum (SNC) in Pakistan was implemented at the primary level in ______?', '{"A":"2021","B":"2020","C":"2019","D":"2017"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SNC was first applied to primary classes (1–5) in 2021 across Pakistan.The second phase started in March 2022 for classes 6–8, and later for classes 9–12.', 0, 0, 0, 1790967395079) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_69ee6ce9d7bff310', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan lies between the longitudes _______?', '{"A":"63 E to 73.8 E","B":"66 E to 78.8 E","C":"61.3 E to 74.1 E","D":"61 E to 75.5 E"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan lies between latitudes 24°N to 37°N.Pakistan lies between longitudes 61°E to 75.5°E.Pakistan is divided into five physiographical divisions.Islamabad is the capital of Pakistan.The construction of Islamabad was completed in 1966.The total number of longitudes is 360.There are 179 eastern longitudes and 179 western longitudes.The Prime Meridian (0° longitude) is known as the GMT (Greenwich Mean Time) line.GMT line divides the Eastern and Western Hemispheres.', 0, 0, 0, 1790967395115) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_61c4a91cb19890e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the first and the last Chief Executive in the history of Pakistan?', '{"A":"General Parvaiz Musharraf","B":"General Takka Khan","C":"General Yahya Khan","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790967395115) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_902643de56e382be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When sixth Census was held in Pakistan?', '{"A":"1972","B":"1981","C":"1998","D":"2017"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The sixth Census was held in Pakistan in 2017.Total Population of Pakistan in 2017 was 207.7 MillionTotal Males 106.34 MillionTotal Females 101.34 MillionGrowth rates 2.40%Literacy rate 59.13%.**************First Census was held in Pakistan in 1951.The second Census was held in Pakistan in 1961.The third Census was held in Pakistan in 1972.Fourth Census was held in Pakistan in 1981.The fifth Census was held in Pakistan in 1998.Sixth Census was held in Pakistan in 2017.Seventh in 2023', 0, 0, 0, 1790967395115) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_12d1dfeefa41a5ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Rann of Kutch is a dispute area between Pakistani provence?', '{"A":"Sindh-India","B":"KPK-India","C":"Punjab-India","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indo-Pakistani War of 1965 involved skirmishes between April and September 1965.Pakistan claims the 24th Parallel as the boundary in the Rann of Kutch, but India does not recognize it.The "Treaty of Rann of Kutch" was signed on 30 June 1965, resolving the territorial dispute.', 0, 0, 0, 1790967395115) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f0ad4edb31bdc765', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Attock fort was built by _____?', '{"A":"Jehangir","B":"Humayun","C":"Akbar","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Attock Fort, built during the reign of Akbar from 1581 to 1583 at Attock Khurd.It was constructed to protect the River Indus''s passage.It was built under the supervision of Khawaja Shamsuddin Khawafi.The fort features four gates: Delhi Gate, Lahori Gate, Kabuli Gate, and Mori Gate.', 0, 0, 0, 1790967395115) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_15e61cbd565da4f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the head of Awami League in 1970?', '{"A":"Feroz Khan Noon","B":"Mujib ur Rehman","C":"Hussain Suharwardi","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sheikh Mujib-Ur-Rehman served as the first President and later as the Prime Minister of Bangladesh from 17 April 1971 until his assassination on 15 August 1975.', 0, 0, 0, 1790967395115) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bae671eed5e035f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Jahangir Khan is a famous player in which game?', '{"A":"Squash","B":"Hockey","C":"Cricket","D":"Boxing"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jahangir Khan is a former World No. 1 professional squash player from Pakistan.He won the World Open title six times.He won the British Open title ten times, from 1982 to 1991.He was born into a Pashtun family from Neway Kelay Payan, Peshawar.He served as President of the World Squash Federation from 2002 to 2008.Jahangir Khan retired as a player in 1993.', 0, 0, 0, 1790967395115) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d456ba20353e4478', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What was the objective of Cripps Mission?', '{"A":"To reform the constitutional issues","B":"To visit historical places","C":"To fights against muslims","D":"To reform the education system"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Cripps Mission was a failed attempt in late March 1942 The Cripps Mission was sent by the British government to India to obtain Indian cooperation for the British war efforts in the 2nd World War.The mission was headed by a senior minister Sir Stafford Cripps.the objective of Cripps Mission: To reform the constitutional issues**ND13-1-2023', 0, 0, 0, 1790967395115) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6fb5640a58d6ef08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who is the Head of the State of Pakistan?', '{"A":"Prime Minister","B":"Chief Justice","C":"President","D":"Army Chief"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The President of Pakistan is the head of state of the Islamic Republic of Pakistan.The current head of state of Pakistan is Asif Ali Zardari who was elected in 2024.', 0, 0, 0, 1790967395151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9233d06b3cd35942', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who completed the construction of Qutb Minar at Delhi?', '{"A":"Qutb Uddin Aibak","B":"Iltutmish","C":"Babar","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qutub minar constructed by: Qutb Uddin AibakConstruction of Qutub minar started in: 1199Construction of Qutb Minar completed by: Iltutmish', 0, 0, 0, 1790967395151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c73a2dc4676ae488', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which Range is called Roof of the World?', '{"A":"Hindu kush Range","B":"Karakoram","C":"Himalayas Range","D":"Pamir Plateau"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Tibetan Plateau (Pamir Plateau) is known as the Roof of the World.It''s also the thickest crust in the world, between 70 and 90 kilometers.The plateau is the world''s largest and highest.Its average elevation is more than 4,500 meters (14,764 feet).Additional information The Shandur Pass in Pakistan is also sometimes called "the roof of the world".', 0, 0, 0, 1790967395151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_aa4c44e551bc3a9c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following political parties did not boycott the Simon Commission?', '{"A":"All India Muslim League","B":"Indian National Congress","C":"Unionist Party","D":"Hindu Mahasabha"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Simon''s commission was rejected by the Indian National Congress and the Muslim LeagueThe All India Muslim League divided into two groups.Jinnah GroupShafi GroupQuaid Group boycotted the Simon Commission but Shafi Group was against boycotting this commission.Simon Commission was appointed in 1928It comprises 7 members of the BritishIt was opposed by both Jinnah & Gandhi', 0, 0, 0, 1790967395151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ad2f9ff00b9d1e91', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Security Council passed its first Resolution on Kashmir on ____?', '{"A":"January 22, 1977","B":"January 17, 1948","C":"January 22, 1945","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The security council passed its first resolution on Kashmir on January 17, 1948.*** United Nations Security Council Resolution 39, adopted on January 20, 1948.The United Nations Security Council Resolution 47, adopted on 21 April 1948, concerns the resolution of the Kashmir conflict.', 0, 0, 0, 1790967395151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7aa4da3d421aacce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When did Pakistan officially recognize/accept the Government of Bangladesh?', '{"A":"December 970","B":"December 1971","C":"February 1973","D":"February 1974"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan officially recognized the Government of Bangladesh on February 22, 1974During the 2nd OIC meeting in Lahore.Prime Minister Zulfikar Ali Bhutto announced the recognitionPressure from Arab leaders to invite Bangladesh''s Sheikh Mujibur Rehman to the conferenceAdditional information List of countries in order of their recognition of Bangladesh on 22 February 1974Malagasy: 14 April 1972Iraq 18 July 1972Upper Volta: 19 September 1972Pakistan: 22 February 1974****Last updated by NS on 01 MAY 2026', 0, 0, 0, 1790967395151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_02fedfac56a94498', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Kalash Valley is situated in ______?', '{"A":"Swat","B":"Gilgit","C":"Chitral","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Kalash Valleys are located in Chitral District in northern (Khyber Pakhtunkhwa) Pakistan.More specifically, they are surrounded by the Hindu Kush mountain range.It is home to the Kalash people, known for their unique culture, language, and festivals.', 0, 0, 0, 1790967395151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1a97b2a3e2088817', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Khalafat movement was abolished in which year?', '{"A":"1923","B":"1934","C":"1924","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Khilafat movement start in 1919-The Khilafat movement ended in 1924Khalafat movement started in India during world war 1 For the purposes to protect the khalafatThe Ottoman Caliphate, was abolished on 3 March 1924 by decree of the Grand National Assembly of Turkey.The process was one of Atatürk''s Reforms following the replacement of the Ottoman Empire with the Republic of Turkey.', 0, 0, 0, 1790967395151) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3dfcc258241fcec8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The famous Hiran Minar is located at _____?', '{"A":"Ziarat","B":"Bannu","C":"Sheikhupura","D":"Thatta"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hiran Minar is located in SheikhupuraIt was built during the reign of the Mughal Emperor Jahangir.Its construction began in 1607.Its construction was completed in 1620.', 0, 0, 0, 1790967395189) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0b392ae713c838cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Derawar Fort is located in ______?', '{"A":"Kashmore","B":"Chaman","C":"Bahawalpur","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The height of walls of Derawar Fort is 40 meters.It is located in Cholistan Desert, Ahmadpur East Tehsil, Bahawalpur.The walls have a perimeter of 1500 metres and stand up to 30 metres high.', 0, 0, 0, 1790967395189) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4fd604148caec9b9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Masjid Wazir Khan was made in which century?', '{"A":"16th","B":"19th","C":"17th","D":"20th"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Wazir Khan Mosque is a 17th-century mosque located in the city of Lahore.The mosque was commissioned during the reign of the Mughal Emperor Shah Jahan.Opened: 1642***', 0, 0, 0, 1790967395189) ON CONFLICT(id) DO NOTHING;
