INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1aaf74b730be231d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'National Highway Sukkur-Quetta is also known as _____?', '{"A":"N-35","B":"N-45","C":"N-65","D":"N-55"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation N-65 is a 385 km long National Highway in Pakistan.It running from Sukkur in Sindh to Quetta in Balochistan via Shikarpur, Jacobabad, Jaffarabad, and Nasirabad.The Sukkur Barrage, officially named Lloyd Barrage, is located in Sindh Province.It built from 1923 to 1932 during the British Raj.It was rehabilitated in November 2004. The barrage is approximately 2 km (1 mi) long.It is the oldest in Pakistan, with seven canals taking off from it.', 0, 0, 0, 1790967395353) ON CONFLICT(id) DO NOTHING;
