INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b0e456a1a2a88695', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which country observes Kashmir Day on February 5th every year?', '{"A":"Nepal","B":"India","C":"Bangladesh","D":"Pakistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kashmir Solidarity Day or Kashmir Day is a national holiday observed in Pakistan Date: February 5Kashmir Day Event Length: 1 DayKashmir Day Related to the Kashmir ConflictKashmir Day was Started by: Jamaat-e-Islami Pakistan in 1990Kashmir Day was first proposed by Qazi Hussain Ahmad In 1991, the then-Prime Minister of Pakistan Nawaz Sharif called for a "Kashmir Solidarity Day Strike"', 0, 0, 0, 1790967395392) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9f1baf8d82a7bc46', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The appointment of Chief Justice of Pakistan (CJP) is made by?', '{"A":"Prime Minister","B":"President","C":"Army Chief","D":"Governors"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Chief Justice and Supreme Court judges are appointed by the President of Pakistan.Appointments are made under Article 175A.Article 175A was introduced through the 18th and 19th Constitutional Amendments.', 0, 0, 0, 1790967395392) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_93b2804b86ea3fa5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In how many natural regions Pakistan can be divided?', '{"A":"Seven","B":"Eight","C":"Six","D":"Twelve"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan is divided into six natural regions:Northern mountain regionMountain of Western frontierPlato photo war and salt rangeThe plate of BalochistanUpper Indus plainLow Indus plainقدرتی خطوں کے لحاظ سے پاکستان کو چھ حصوں میں تقسیم کیا گیا ہے: پہاڑی علاقہ، بالائی سندھ، بلوچستان، تھل، تھر اور میدان۔There are 3 Geographical regions of Pakistan:Northern highlandsThe Balochistan plateauThe Indus River plain', 0, 0, 0, 1790967395392) ON CONFLICT(id) DO NOTHING;
