INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_243abce0d82868d9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who started Jihad Movement?', '{"A":"Shah Walli Ullah","B":"Haji Shariat Ullah","C":"Syed Ahmad Shaheed","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Syed Ahmad Shaheed (1786-1831) was a Muslim leader and reformer who founded the Jihad movement in India.He led a rebellion against the Sikh Empire in the early 19th century.The Jihad movement, also known as the Tariqah-i-Muhammadiyah.It aimed to reform Islamic practices, promote religious purification, and resist British colonial rule.', 0, 0, 0, 1790967395640) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8a19969909759e26', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Shaikh Ahmad Sirhindi (Mujaddid Alif Sani) was born on ______?', '{"A":"971 AH","B":"987 AH","C":"569 AH","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ahmad al-Fārūqī al-Sirhindī was an Indian Islamic scholar, Hanafi jurist, and member of the Naqshbandī Sufi.Ahmad Sirhindi was born on 26 May 1564 in the village of Sirhind, PunjabDied: December 10, 1624, Sirhind, IndiaPlace of burial: Hazrat Seyfeddin Farooqi, Rauza Sharif, Fatehgarh Sahib, IndiaBooks: The Juristic Sufism of Ahmad Sirhindi, Beweis Des ProphetentumsND15-10-2023', 0, 0, 0, 1790967395640) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_db28b5fcbc6b7366', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'By whose order did the massacre take place in Jallianwala Bagh?', '{"A":"Gen. Dyer","B":"Gen. Sherman","C":"Gen. Ulysses","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jallianwala Bagh Massacre took place on 13 April 1919In Jallianwala Bagh massacre killing at least 379 people and injuring over 1,200 other people.Jallianwala Bagh is a historic garden close to the Golden Temple complex in Amritsar, Punjab, IndiaBy General Reginald Dyer order did the massacre take place in Jallianwala Bagh It is managed by the Jallianwala Bagh National Memorial Trust and was renovated between 2019 and 2021****nd9-2-2023', 0, 0, 0, 1790967395640) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b42831fffc04af75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The new total length of LOC (Line of Control) between India and Pakistan according to the Survey of Pakistan 2020 is _________?', '{"A":"595 km","B":"861 km","C":"740 km","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The total length of the Line of Control (LoC) is 861 km.Separates Pakistan- and India-administered Kashmir.Established under the Simla Agreement, 1972.Previously called the Ceasefire Line.Established 2 July 1972', 0, 0, 0, 1790967395640) ON CONFLICT(id) DO NOTHING;
