INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_60bc996cc303aa03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is the percentage of total population of Pakistan lives in rural areas?', '{"A":"60%","B":"65%","C":"63%","D":"63.66%"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to World Bank and the Pakistan Institute of Development Economics (PIDE)Approximately 61.3% to 64% of Pakistan''s total population lives in rural areas"Urban area" can refer to towns, cities, and suburbs. Rural areas, often called "the country," have low population density and large amounts of undeveloped land.', 0, 0, 0, 1790967395985) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5a1bba58e1ec17ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Ibn Battuta was born in which country?', '{"A":"Portugal","B":"Saudi Arabia","C":"Morocco","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Abu Abdullah Muhammad ibn Battutah, commonly known as Ibn BattutaBorn: February 24, 1304, Tangier, MoroccoDied: 1369, Marrakesh, MoroccoPlace of burial: Tomb of Ibn Battuta, Tangier, MoroccoIbn Battuta visited India during the reign of Muhammad bin TughlaqIbn Battuta was: a travelerIbn Battuta belonged: MoroccoOver a period of thirty years, Ibn Battuta visited most of the: North Africa, the Middle East, Central Asia,South Asia, Southeast Asia, China, and the Iberian Peninsula', 0, 0, 0, 1790967395985) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b06267f4d74e401d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Police Martyrs Day is observed on which date in Pakistan?', '{"A":"August 6","B":"August 4","C":"August 2","D":"August 1","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Police Martyrs Day is observed on August 4th across Pakistan to honor the services of the police department.It marks the death anniversary of Shaheed Safwat Ghayur.He was martyred in a suicide attack on August 4th, 2010.', 0, 0, 0, 1790967395985) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_65d1cb015087830b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which country won Cricket Champions Trophy 2017?', '{"A":"Iran","B":"UAE","C":"Malaysia","D":"Pakistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 2017 ICC Champions Trophy was the eighth ICC Champions Trophy, It was held in England and Wales from 1 to 18 June 2017. List of Champions Trophy Winners & Host YEARHOSTWINNERRUNNER1998Dhaka, BangladeshSouth AfricaWest Indies2000Nairobi, KenyaNew ZealandIndia2002Sri LankaIndia and Sri Lanka (final was washed out)2004EnglandWest IndiesEngland2006IndiaAustraliaWest Indies2009South AfricaAustraliaNew Zealand2013EnglandIndiaEngland2017EnglandPakistanIndia2025Pakistan2029India*******VU CBT FIA PAPER 23-12-2021***', 0, 0, 0, 1790967396016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_992f4b76681084dd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What was the original name of Hazrat Lal Shahbaz Qalandar?', '{"A":"Hazrat  Shah Walliullah","B":"Syed Usman Marwandi","C":"Hazrat Ahmad Sirhindi","D":"Hazrat Zubair Kaki"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The full name of Hazrat Lal Shahbaz Qalandar: Syed Shah Hussain MarwandiLal Shahbaz Qalandar wrote several books in Persian and ArabicLal Shahbaz Qalandar was a Sufi saint and poet of present-day Pakistan and AfghanistanBorn: 1177, Marand, IranDied: February 19, 1274, SehwānPlace of burial: Darbar Hazrat Usman Marvandi Lal Shahbaz Qalandar, SehwānTitle: QalandarThe shrine of Hazrat Laal Shahbaz Qalandar is situated in Sehwan Sindh', 0, 0, 0, 1790967396016) ON CONFLICT(id) DO NOTHING;
