INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a025927d704818f1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Largest Island of Pakistan is ________?', '{"A":"Astola Island","B":"Manora Island","C":"Charna Island","D":"None of above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Astola is Pakistan''s largest offshore island at approximately 6.7 km (4.2 mi) long)It is also known as Jezira Haft Talar, Satadip, or ''Island of the Seven HillsLocation: Balochistan, Gwadar District Astola is famous for its rich marine biodiversity.AGM 02.05.2023', 0, 0, 0, 1790967396016) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6325619ef79b087f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Where is Shalimar Garden located?', '{"A":"Karachi","B":"Lahore","C":"Islamabad","D":"Rawalpindi"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mughal Emperor Shah Jahan built Shalimar Gardens in Lahore.It was built in the year 1641-42.It is included in World Heritage Site: 1981Sr#Built byName of Places1Jahangir​Shalimar Bagh, Kashmir2Shah Jahan1. Shalimar Garden, Pakistan, 2. Taj Mahal,3. the Jama Masjid,4. the Red Fort3Akbar1. Buland Darwaza,2. Fatehpur Sikri4AurangzebMoti Masjid, Delhi', 0, 0, 0, 1790967396016) ON CONFLICT(id) DO NOTHING;
