INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ee4716fa1bb5c204', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What does SIFC stand for?', '{"A":"Special Investment Facilitation Council","B":"Strategic Investment Facilitation Council","C":"State Infrastructure Funding Commission","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SIFC: Special Investment Facilitation CouncilFormation: 17th June, 2023Founded by: Shahbaz SharifHeadquarter: IslamabadPurpose: Economic revival of Pakistan, attract Foreign Direct Investment', 0, 0, 0, 1790967396054) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ac35800a8a25bc8c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'One unit was dissolved on?', '{"A":"1st July 1970","B":"1st July 1971","C":"1st July 1972","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The One Unit scheme was dissolved on July 1, 1970.General Yahya Khan imposed Legal Framework Order No. 1970 to end the programand reinstate the provisional status of the Four Provinces as of August 1947.Additional information:The One Unit was the reorganization of the provinces of Pakistan Prime Minister Muhammad Ali Bogra led it on 22 November 1954 and passed on 30 September 1955This program merged the four provinces of West Pakistan into a single province to parallel the province of East PakistanWest PunjabSind NWFP Baluchistan', 0, 0, 0, 1790967396054) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9c7ced31bac1c24c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Kabul, Swat, Kunhar, Panjkora, Bara, Kurram and Gomal are the rivers of ________?', '{"A":"Punjab","B":"Khyber Pakhtunkhwa","C":"Sindh","D":"GB"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khyber Pakhtunkhwa often abbreviated as KPK.It was formerly known as the North-West Frontier Province, is one of the four provinces of Pakistan. It is located in the northwestern region of the country, along the Afghanistan–Pakistan border.', 0, 0, 0, 1790967396054) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_efcd7a2467527cfc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Construction of Taj Mahal was completed in ______?', '{"A":"1647","B":"1645","C":"1648","D":"1649"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Taj Mahal Construction started 1632 Construction completed 1647 Built by Mughal Emperor Shah Jehan Built in the memory of Mumtaz Mahal Height 73 M Taj Mahal Most visited monument of India as of July 2022 Architecture Ustad Ahmed Lahori', 0, 0, 0, 1790967396054) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_995a1aa2f2aecbe9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What was the title of the pamphlet in which Chaudhry Rahmat Ali proposed the name "Pakistan"?', '{"A":"Now or Never","B":"Freedom for Muslims","C":"Pakistan Zindabad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word was first introduced now or never in 1933 by Chaudhry Rahmat Ali.The "Pakistan Declaration" titled Now or Never means Are We to Live or Perish Forever?In this pamphlet, the word Pakistan was used for the first time This pamphlet was derived from the two-nation theory of Muslim reformer Syed Ahmed Khanit was a pamphlet, referring to the names of the five northern regions of British India: PunjabAfghanistanKashmirSindhBaluchistan. (Pakistan)***', 0, 0, 0, 1790967396054) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f8f6e47201f9ea63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When did Arfa Karim die?', '{"A":"January 14, 2012","B":"January 14, 2010","C":"January 14, 2008","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Arfa Karim (1995-2012) was a Pakistani student and computer prodigy.She became the youngest Microsoft Certified Professional (MCP) at the age of 9 in 2004.She was invited to visit Microsoft headquarters in Redmond, Washington, and met with Bill Gates.', 0, 0, 0, 1790967396054) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_680d23c34d23cc23', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Largest Radio Station found in Pakistan is _____?', '{"A":"Islamabad","B":"Karachi","C":"Lahore","D":"Multan"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Largest Radio Station Found In Pakistan Is Islamabad.******The following three radio stations existed at the time of independence of Pakistan on 14 August 1947.1. Peshawar Radio Station was established in 19352. Lahore radio station established in 19373. Dhaka radio station established in 1939****', 0, 0, 0, 1790967396087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b27ddf636dd20597', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The name of the father of Shah Abdul Latif Bhittai is ______?', '{"A":"Shah Habib","B":"Shah Kareem","C":"Shah Hussain","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shah Abdul Latif Bhittai''s father was Shah Habib.The shrine of Shah Abdul Latif Bhitai is located in Bhit Shah.Bhit Shah is a small town located in Matiari District, Sindh.Shah Abdul Latif Bhittai was the greatest Muslim poet of the Sindhi language.He is also known as the poet of Sindh.Born on 18 November 1689.Died on 1 January 1752.Main Ghulam Shah Kalhoro built the tomb of Shah Abdul Latif Bhittai.', 0, 0, 0, 1790967396087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_14b1acdefbccf739', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who delivered the Presidential address at Allahabad in 1930?', '{"A":"Liaqat Ali Khan","B":"Quaid-e-Azam","C":"Moulvi Fazal-ul-haq","D":"Allama Iqbal","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allama Iqbal Join Muslim League in 1908 in London and in subcontinent in 1922Sir Muhammad Iqbal''s 1930 Presidential Address to the 25th Session of the All-India Muslim League Allahabad, 29 December 1930.Allama Iqbal is a National Poet of PakistanAllama Iqbal Born: November 9, 1877, SialkotAllama Iqbal Died: April 21, 1938, in LahoreAllama Iqbal Place of burial: Tomb of Allama Iqbal, Lahore***ND28-1-2023ND21-2-2023', 0, 0, 0, 1790967396087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fb99ebc55f476343', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The real name of Hazrat Sachal Sarmast is _____?', '{"A":"Abdul Haq","B":"Abdul Wahab","C":"Abdul Khalique","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The real name of Hazrat Sachal Sarmast was Abdul Wahab.Hazrat Sachal Sarmast born 1152 Hijri (1739 CE).Hazrat Sachal Sarmast died 1242 Hijri (1827 CE).Hazrat Sachal Sarmast is known as: a poet of seven languages (شاعر ہفت زبان)', 0, 0, 0, 1790967396087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e150ed70062d2a90', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Mohenjo Daro means __________?', '{"A":"Civilized City","B":"Beautiful Gardens","C":"Beautiful City","D":"Mound of the Dead"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mohenjo-Daro means Mound of the DeadThis is because after it had declined, the remains started to have layers over them.it was first recognized in 1922It was discovered by R. D. BanerjiIt is located in Larkana upper Sindh it was the largest settlement of the ancient Indus Valley Civilisation', 0, 0, 0, 1790967396087) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7471192198ccacce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Kirthar Range is near to _____?', '{"A":"Jamshoro","B":"Dadu","C":"Mithonkot","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The elevation of the Kirthar Mountains is 2,260 meters (7,410 feet).The highest peak in the Kirthar Range is Zardak Peak.It stands at 7,430 feet (2,260 meters).The Kirthar Range is situated along the border of Balochistan and Sindh provinces.The hill station of Gorakh, located in the Kirthar Mountains, is situated off Dadu in Sindh.', 0, 0, 0, 1790967396087) ON CONFLICT(id) DO NOTHING;
