INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_72669e09d029ddcc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Dr. Umar bin Daudpoto was born at _____?', '{"A":"Johi","B":"Talti","C":"Bhiria","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dr. Umar bin Muhammad Daudpota was born on 25 March 1896 (or 1 June 1897) in the village of Talti.It is located in Sehwan Sharif, Dadu District (now District Jamshoro), British India (present‑day Sindh, Pakistan).', 0, 0, 0, 1790967396129) ON CONFLICT(id) DO NOTHING;
