INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_edb900e861f31b62', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Second Constituent Assembly of Pakistan was formed in?', '{"A":"1955","B":"1956","C":"1954","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The second Constituent Assembly of Pakistan was created on 28th May 1955 under Governor General''s Order No. 12 of 1955.The strength of this Assembly was 80 Members, half each from East Pakistan and West Pakistan.First assembly consisted of 69 members while second assembly consisted of 80 members.On 26th July 1947 in which the first Constituent Assembly of Pakistan was given shape with 69 Members (later increased to 79), including one female Member.', 0, 0, 0, 1790967396130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f3600437923fa23c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who was the founder of Arya Samaj?', '{"A":"Pandit Dayanand","B":"Mahatma Gandhi","C":"Sachindanand","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dayanand Saraswati was an Indian philosopher, social leader and founder of the Arya Samaj.Arya Samaj founded in 1875', 0, 0, 0, 1790967396130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_352a2649049c34d1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Dharmanrajaikastupa in taxila was built in the era of _____?', '{"A":"Mughals","B":"Kushans","C":"Khilji","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Dharmarajika Stupa, also referred to as the Great Stupa of Taxila.It is a Buddhist stupa near Taxila, Pakistan.It dates from the 2nd century CE.It was built by the Kushans to house small bone fragments of the Buddha.', 0, 0, 0, 1790967396130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a75e980d6bfc94ef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which Pakistani Cricket player has breaks Kohli’s record and becomes fastest player to reach 1,000 runs in T20 International?', '{"A":"Babr Azam","B":"Muhammad Rizwan","C":"Shoaib Malik","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The fastest Pakistani player to score 1000 T20 runs is Babar Azam.He reached the milestone in 26 innings. He is also the fastest to 1000 runs in T20 Internationals. Born: October 15, 1994', 0, 0, 0, 1790967396130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8a6ff82677d910ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The youngest Nobel Prize laureate, Malala Yousafzai won Nobel Peace Prize for the year?', '{"A":"2013","B":"2014","C":"2015","D":"2016"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In October 2014, Malala, along with Indian children''s rights activist Kailash Satyarthi At age 17, she became the youngest person to receive this prize.About Malala YousafzaiBorn: 1997Belongs: Mingora, SwatReceived Noble Prize in 2014She is the world''s youngest Nobel Prize laureateInternational Malala Day is observed every year on July 12 ND-21-5-2023', 0, 0, 0, 1790967396130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_53b7d7b52afd6bb7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan Day is celebrated throughout Pakistan each year on ____?', '{"A":"23 March","B":"14 August","C":"15 August","D":"25 December"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan Day, یوم پاکستان or Pakistan Resolution Day, commemorating the Lahore Resolution passed on 23 March 1940.', 0, 0, 0, 1790967396130) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_91b1001845c23e2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The National Accountability Bureau (NAB) was established to combat _____?', '{"A":"Cybercrime","B":"Drug trafficking","C":"Political corruption","D":"Tax evasion"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The National Accountability Bureau (NAB) is Pakistan''s lead anti-corruption agency.It established by Pervez Musharraf on November 16, 1999.Its headquarters are in Islamabad.It focuses on combating political corruption and ensuring accountability.', 0, 0, 0, 1790967396174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2918e18c80e1b877', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The narrow strip of land that connects Pakistan with central Asia is ______?', '{"A":"Wakhan","B":"Gibraltar","C":"Hurmoz","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Wakhan Corridor is a narrow strip of territory in Afghanistan, extending to China and separating Tajikistan from Pakistan and Kashmir. The corridor was formed by an 1893 and creating the Durand Line.The Wakhan Corridor is about 350 km long.', 0, 0, 0, 1790967396174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ce86a5d86de0ba15', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is the name of Pakistan Space Agency?', '{"A":"ISRO","B":"SUPARCO","C":"ESA","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan''s National Space Agency SUPARCO.SUPARCO stands for Space and Upper Atmosphere Research Commission.SUPARCO was set up in 1961.', 0, 0, 0, 1790967396174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8912fd9f5f9c7304', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Economist Intelligence Unit 2020 Democracy Index ranked the Democracy in Pakistan in which category?', '{"A":"Hybrid regimes","B":"Full democracies","C":"Flawed democracies","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan has taken 105th position out of 167 countries.In the 2020 released Economist Intelligence Unit''s (EIU) Democracy Index report, top five countries:1. Norway2. Iceland3. Sweden4. New Zealand5. Canada', 0, 0, 0, 1790967396174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4483b4fb6511c094', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Textbook Boards were established in the provinces of Pakistan in?', '{"A":"1960","B":"1964","C":"1962","D":"1966"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The West Pakistan Textbook Board was officially established on 6th June 1962 under the West Pakistan Textbook Board Ordinance XLI of 1962.The Board was tasked with preparing, publishing, and distributing textbooks to ensure standardized education across West Pakistan.', 0, 0, 0, 1790967396174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_aff3294a30f1d859', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Wakhan Corridor, a narrow strip of Afghanistan separates Pakistan from which country?', '{"A":"Afghanistan","B":"Tajikistan","C":"China","D":"India"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Wakhan Corridor is a narrow strip of territory in Afghanistan, extending to China and separating Tajikistan from Pakistan and Kashmir. The corridor was formed in 1893 and created the Durand Line.The Wakhan Corridor is about 350 km long.', 0, 0, 0, 1790967396174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_db846be57d09e4ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Khawaja Nazim-ud-Din constituted the basic principles committee in 1949 for the purpose of _____?', '{"A":"To make recommendations to provinces","B":"To make the preparation for the budget","C":"To prepare assembly regulations","D":"To expedite the work of the Constitution making"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The resolution proclaimed that the future constitution of Pakistan would not be modeled entirely on a European pattern but on the ideology and democratic faith of Islam.The resolution, in its entirety, has been made part of the Constitution of Pakistan under Article 2(A).The Basic Principles Committee was established on 12th March 1949 by Khawaja Nazimuddin on the instruction of Prime Minister Liaquat Ali Khan.', 0, 0, 0, 1790967396174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b7dbcaf92dce1733', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Simon commission was introduced in 1919 and decided that to send a commission to India after every _____ years.', '{"A":"10","B":"5","C":"3","D":"7"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Simon Commission was a result of the Government of India Act 1919, Proposed sending a commission every 10 years.It was actually sent in 1927, two years earlier than scheduled.The Indian Statutory Commission, also known as the Simon Commission,It was a group of seven members of the British Parliament, Chaired by John Simon.', 0, 0, 0, 1790967396174) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6b828faffb0fffc1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Swadeshi movement was launched to reverse the _____?', '{"A":"Partition of Bengal","B":"Partition of India","C":"Separation of Sindh from Bombay","D":"Annexation of Kashmir"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After the British Government''s decision for the partition of Bengal 1903, the Swadeshi movement was formally started from Calcutta in 1905 to curb foreign goods by relying on domestic production.', 0, 0, 0, 1790967396214) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_791c60522edda470', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Makli Necropolis was inscribed as a UNESCO World Heritage Site in ______?', '{"A":"1976","B":"1979","C":"1981","D":"1985"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Makli Necropolis was inscribed as a UNESCO World Heritage Site in 1981.Makli Necropolis, located in Thatta, Pakistan.It is one of the largest funerary sites in the world.It is the final resting place of some 125,000 local rulers, Sufi saints, and other eminent persons from the 14th to the 18th century.', 0, 0, 0, 1790967396214) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2e696e7e2821e904', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Molvi Tameez-ud-Deen was elected ______ of first constituent assembly of Pakistan?', '{"A":"Chairman","B":"Vice President","C":"President","D":"Vice Chairman"}', 'B', NULL, 0, 0, 0, 1790967396214) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_07e98a8ab8151339', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who overthrew Nawaz Sharif''s government in 1999?', '{"A":"General Ayub Khan","B":"General Yahya Khan","C":"General Zia-ul-Haq","D":"General Pervez Musharraf"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In October 1999, General Pervez Musharraf led a military coup to overthrow Prime Minister Nawaz Sharif. The military seized control of the government on October 12, And by October 14, Musharraf was acting as Chief Executive.', 0, 0, 0, 1790967396214) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5388ee18205f431f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Muhammadan Anglo-Oriental (MAO) College was established by ______?', '{"A":"Allama Iqbal","B":"Sir Syed Ahmed","C":"Ch. Rehmat Ali","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sir Syed Ahmad Khan established the Muhammadan Anglo-Oriental (MAO) CollegeFoundation Date: May 24, 1875 (as a school).Location: Aligarh, Uttar Pradesh.Additional informationBecame a college two years later (1877)Known initially as Madarsatul UloomInspired by the Cambridge education system,Began operations on Queen Victoria''s 56th birthdayIntermediate classes were introduced in 1878.B.A. degree classes in 1881Aligarh Muslim University in 1920Last updated question by NA 22-April-2026', 0, 0, 0, 1790967396214) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_99bdf1a8c6757729', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Where is Sardar Nishtar buried?', '{"A":"In the vicinity of Mazar-e-Quaid, Karachi","B":"Lahore Fort","C":"Islamabad Monument","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sardar Abdur Rab Nishtar was born on June 13, 1899, in Peshawar, British India.He was died on February 14, 1958, in Karachi, Pakistan.', 0, 0, 0, 1790967396214) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4d8abf7ba9827589', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'How many persons with Pakistani origin have been awarded the Nobel Prize till to date?', '{"A":"2","B":"3","C":"5","D":"4"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Two persons of Pakistani origin have received the Nobel Prize: Abdus Salam (Physics, 1979) and Malala Yousafzai (Peace, 2014).Abdus Salam was recognized for his work in theoretical physics, while Malala was honored for her activism in girls'' education.', 0, 0, 0, 1790967396214) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2fc6a455f08f5fe5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan is located in the ____ part of South Asia.', '{"A":"Western","B":"Southern","C":"Northern","D":"Eastern"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan is located in the western part of South Asia.It shares borders with India to the east, Afghanistan and Iran to the west, and China to the north.', 0, 0, 0, 1790967396214) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c1509a4212ef615c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'ASF is a _____ department.', '{"A":"Federal","B":"Corporation","C":"Autonomous body","D":"Provincial"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ASF (Airport Security Force) is a Federal department.It established under the ASF Act of 1975.It operates under the Secretary of Aviation.It is responsible for airport security, including protecting facilities and aircraft in Pakistan.', 0, 0, 0, 1790967396260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d169c6f3ddbcb78c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'On February 11th, 2021 Pakistan conducted a successful training launch of ____ cruise missile.', '{"A":"Babur","B":"Nasar","C":"Abdali","D":"Ghazani"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 11 February 2021, Pakistan conducted a successful launch of the Babur-1A cruise missile with a range of 450 kilometers.while Pakistan successfully conducted a flight test of air-launched cruise missile Ra’ad-II on 18th February 2020.Pakistan test-fired its first submarine-launched cruise missile Babur-III on 9 January 2017.', 0, 0, 0, 1790967396260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e18933b2f0dfa113', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Sovereignty belongs to which one of the following?', '{"A":"Prophet","B":"Allah","C":"President","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In Islamic belief, sovereignty belongs to Allah alone.Allah is the supreme authority over all creation. Human governance must align with divine laws from the Quran and Hadith.', 0, 0, 0, 1790967396260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fd350e33fe040e8a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When first case of Omicron sub-variant detected in Pakistan?', '{"A":"April 9th 2022","B":"January 4th 2022","C":"February 21th 2022","D":"May 9th 2022"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation National Institute of Health on 9th May 2022 said that the first case of the subvariant of COVID-19''s Omicron variant has been confirmed in Pakistan.', 0, 0, 0, 1790967396260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3b9996c7c21c7a90', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which is the first private Airport in Pakistan?', '{"A":"Multan","B":"SialKot","C":"Gawadar","D":"All of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sialkot International Airport is the first privately owned public airport in Pakistan. It was built by the business community of Sialkot by their own efforts.', 0, 0, 0, 1790967396260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_69be7861c6abab3f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The first international organization joined by Pakistan was the ______?', '{"A":"UNO","B":"RCD","C":"British CommonWealth","D":"IMF"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation British Commonwealth Pakistan emerged as an independent state on 14th August 1947. Pakistan joined FAO on 7 September 1947. Pakistan joined UNESCO on 14 September 1949.Pakistan joined World Bank in 1950. Pakistan joined IMF on 11 July 1950.Pakistan joined SEATO in 1954.', 0, 0, 0, 1790967396260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b24fe9e36fefd9cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Kulbushan Jadev, an Indian spy, was arrested from ______?', '{"A":"Sindh","B":"Balochistan","C":"KPK","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kulbhushan Sudhir Jadhav is an Indian national. It is alleged by the Pakistani government that he was arrested in the Pakistani province of Balochistan was arrested on charges of terrorism and spying for India''s intelligence agency, the Research and Analysis Wing.', 0, 0, 0, 1790967396260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5852136b19dad78c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', '16th August, 1946 was declared as direct action day by?', '{"A":"Congress","B":"Muslim League","C":"British Government","D":"Hindus of subcontinent"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Direct Action Day, also known as the 1946 Calcutta Killings, was a day of nationwide communal riots by the Indian Muslim community announced by Muhammad Ali Jinnah.It led to large-scale violence between Muslims and Hindus in the city of Calcutta (now known as Kolkata) in the Bengal province of British.', 0, 0, 0, 1790967396260) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ef6dfdc1c0cb0565', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who is the real founder of Muslim rule in northern India?', '{"A":"Mehmood of Ghazni","B":"Shahab-ud-Din Muhammad Ghori","C":"Muhammad bin Qasim","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shahabuddin Ghori is the founder of the Islamic State in India.***Sultan Muhammad Ghori was born in 1162.Shahabuddin Ghori was a warrior of Turkish origin who traveled from Ghor, Afghanistan, and conquered Delhi in 1192. He was the true founder of Muslim rule in India.***Muhammad Ghori was the ruler of the Ghori dynasty, invaded India in the year 1206 C.E and their rule extended until 1526 C.E', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6e36d0624e793843', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Most of the plain areas of Balochistan are irrigated by two canals dug out from _____?', '{"A":"Sukkur barrage","B":"Guddu barrage","C":"Chashma barrage","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Patfeeder Canal and Kirthar canal dug out from Guddu Barrage.Guddu is a barrage on the Indus River near Kashmore. Iskander Mirza laid the foundation-stone of Guddu Barrage in 1957, inaugurated by Ayub Khan in 1962.', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cb57fbb502d8628b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following receives rains more than all the other valleys?', '{"A":"Chitral valley","B":"Kashmir valley","C":"Swat valley","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kashmir Valley receives the highest rainfall due to its location in the western Himalayas.It experiences heavy precipitation from monsoon and western disturbances.', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7f76dd4e5f297013', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which were the main parties in the elections of 1970?', '{"A":"Pakistan People’s Party","B":"Awami League","C":"Both A and B","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first-ever general elections were held on 7th December 1970.Yahya Khan issued a Legal Framework Order for the first general elections.300 of the 313 seats in the National Assemblyof which 162 were in East Pakistan and 138 in West Pakistan.A further thirteen seats were reserved for women (seven of which were in East Pakistan and six of which were in West Pakistan)LeaderSheikh Mujibur RehmanZulfikar Ali BhuttoPartyALPPPSeats won167 86Popular vote12, 937, 1626, 148, 923Percentage39.20%18.63%', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_177f24f957a34ccb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'According to 1941 Census ______ of the population of Kashmir state was Muslim.', '{"A":"75%","B":"77%","C":"88%","D":"93%"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the last census of British India in 1941, the total population of Kashmir and Jammu was 3,945,000. 1. The total Muslim population was 2,997,000 (75.97%), 2. The Hindu population was 808,000 (20.48%), 3. The Sikh 55,000 (1.39%)', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cd9f5a56e7f9e8c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following opposed the Pakistan membership in United Nation?', '{"A":"Iran","B":"Egypt","C":"Afghanistan","D":"Malaysia"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Afghanistan opposed Pakistan’s membership in the United Nations at the time of Independence:****Afghanistan was the only country to vote against Pakistan''s accession to the United Nations after its independencePakistan officially joined the United Nations (UN) on 30 September 1947Pakistan has been elected seven times (tied with Colombia and India) into the UN Security Council, with the most recent term in 2013.', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bd607aaa42ec4ace', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Artificial Forests being maintained in ______?', '{"A":"Changa Manga","B":"Multan","C":"DG Khan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Changa Manga is one of the largest man-made forests in Pakistan, located in Punjab.It was originally planted during the British colonial era to provide timber for railway networks.', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_abb9e0cbf50246df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Chandka Medical college is located at ______?', '{"A":"Larkana","B":"Hyderabad","C":"Nawab Shah","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chandka is the old name of Larkana.Larakana is also called city of Guavas.Larkana is a city located in Sindh.', 0, 0, 0, 1790967396297) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a1c5963443f4218f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Bala Hisar fort built by _________?', '{"A":"Akbar","B":"Babur","C":"Shah Jahan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Babur first built a fort here in 1526 after capturing Peshawar.First mentioned by 7th-century explorer Xuanzang, the fort was used as a royal residence for the Durrani Empire since December 1747.The Maratha Empire captured it after the Battle of Peshawar in 1758.The Sikhs reconstructed the fort after capturing Peshawar in March 1823.', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7405dcb483c89eb6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Silver Fibre of Pakistan is ________?', '{"A":"Cotton","B":"Wheat","C":"Rice","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cotton is known as the "Silver Fibre" of Pakistan due to its economic importance and export value.It plays a key role in Pakistan’s textile industry, the backbone of the country''s economy.', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1fe7fef8f506185f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In 1859 Sir Syed Ahmed Khan established/set up a first school where Persian and English were taught?', '{"A":"Muradabad","B":"Lucknow","C":"Bijnaur","D":"Aligarh"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1859, Sir Syed Ahmed Khan established a school in Muradabad, where Persian and English were taught. Later, he founded the Mohammedan Anglo-Oriental College in Aligarh in 1875, which became Aligarh Muslim University.', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_20622ef37ad3a690', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Faisal Mosque and International Islamic University were built with the financial support of ______?', '{"A":"Kingdom of Saudi Arabia","B":"Turkey","C":"Libya","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The mosque was built by a Saudi King named King Faisal who gifted it in recognition of friendship between Pakistan and Saudi Arabia.Faisal Mosque of Pakistan was opened to the public in 1986 OR 1987**On 18th June 1988 the first prayer was held in the Faisal mosque**The Faisal Mosque is the largest mosque in Pakistan,located in the national capital city of Islamabad.Completed in 1986,it was designed by Turkish architect Vedat Dalokay', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d6ce5aa8ee79dfa3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Against whom did Syed Ahmad Shaheed lead his Jihad movement?', '{"A":"Peshawar Ruler","B":"British Rule","C":"Sikh Ruler","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Syed Ahmad Shaheed (1786-1831) was a Muslim leader and reformer who founded the Jihad movement in India.He led a rebellion against the Sikh Empire in the early 19th century.The Jihad movement, also known as the Tariqah-i-Muhammadiyah.It aimed to reform Islamic practices, promote religious purification, and resist British colonial rule.', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ac511b5f2942c74e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following is the Oldest Language of Pakistan?', '{"A":"Sindhi","B":"Urdu","C":"English","D":"Arabic"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sindh is one of the world''s oldest languages, written in right-handed Perso-Arabic script***30 languages are spoken in PakistanwhileFive languages have more than 10 million speakers each – Punjabi PashtoSindhiSaraikiUrdu.whileThe most widely spoken language in Pakistan is Punjabi (48 % speak), followed by the Punjabi variant Siraiki (10 percent),2nd Sindhi 12%Pashto 8%Balochi 3%Hindko 2%ND18-2-2023RY5022023', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5b15baec9b4c25b4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Sulimani and Makrani are the two dialects of which language?', '{"A":"Balochi","B":"Sindhi","C":"Pushto","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sulaimani and Makrani are two of the primary dialects of the Balochi language.Balochi is a Northwestern Iranian language,Makrani is the second-most spoken Balochi dialect Additional informationBalochistanProvince status: 1 July 1970Capital: QuettaArea: 347,190 km²Share of Pakistan''s area: About 42%Largest province by: AreaLast updated 18-07-2026 by NA', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b3aa0ba5c86fa160', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'RCD became dissolve/dis-functional after Iranian Revolution in which year?', '{"A":"1964","B":"1965","C":"1969","D":"1979"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation RCD was established on: 21 July, 1964RCD was dissolved in: 1979RCD stand for Regional Cooperation for DevelopmentRCD: Established by Iran, Pakistan and TurkeyRCD headquarters: Iran', 0, 0, 0, 1790967396334) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ddbfae01bd2f5500', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which team was the runner-up of Pakistan Super League (PSL) 2020?', '{"A":"Islamabad United","B":"Karachi Kings","C":"Quetta Gladiators","D":"Lahore Qalandars","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan Super League (PSL) 2020Edition: FifthDates: 20 Feb – 17 Nov 2020Administrator: PCBFormat: Twenty20Venue: PakistanWinner: Karachi Kings (1st title)Karachi Kings won by: 5 wicketsRunner-up: Lahore QalandarsParticipants: 6Matches:34Player of the series: Babar Azam (Karachi Kings)Babar Azam made: 473 runsMost runs: Babar AzamMost wickets: Shaheen Afridi (Lahore Qalandars)Shahid Afridi took: 17 wickets', 0, 0, 0, 1790967396381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4b3b19e085bb6789', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which mineral is found in Saindak (Balochistan)?', '{"A":"Copper","B":"Limestone","C":"Petroleum","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Copper mineral is found in Saindak (Baluchistan)**Saindak project is operated with the collaboration of ChinaProject Location: Chaghi, Balochistan**The discovery of gold, copper & silver deposits at Saindak was made in the 1970sTrial production at the Saindak Copper-Gold project started in 1995.', 0, 0, 0, 1790967396381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6448bc91bb9ecc94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who is known as the founder of Tahrik-e-Raishmi Romal (The Silk Letter Movement)?', '{"A":"Maulana Mahmood ul Hassan","B":"Maulana Qasim Nanotvi","C":"Allama Iqbal","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maulana Mahmood ul Hassan was an Indian Muslim scholar and an independence activist The Silk Letter Movement, also known as Tehreek-e-Reshmi RumalIt was initiated by Deobandi leaders, particularly Maulana Mahmood Hasan DeobandiThis movement, active between 1913 and 1920,Its headquarters were in Kabul,They aimed to achieve Indian independence from British rule by allying with the"Ottoman EmpireAfghanistanGermanyThe letters, written on silk cloth, were intercepted by the Punjab CID, revealing the plot.', 0, 0, 0, 1790967396381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c732d67ca87f1152', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan Steel Mills is located in?', '{"A":"Gwadar","B":"Lahore","C":"Islamabad","D":"Karachi","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan Steel Mill is headquartered in Karachi, Sindhit was founded on 30 Dec 1973 it was Founded with the support of Russia.Zulfikar Ali Bhutto leads the foundation stone of Pakistan Steel Mills Corporation on the 15th of January 1985', 0, 0, 0, 1790967396381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_880a7aa911619078', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The shrine of Abdullah Shah Ghazi is located in?', '{"A":"Karachi","B":"Nawab Shah","C":"Thatta","D":"Hala"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Abdullah Shah Ghazi Mazar is located in Karachi.Location: Shahrah-e-Firdousi, Block 4/Block 3, Clifton, Karachi.It is a renowned 8th-century Sufi shrine originally built by Murshid Nadir Ali Shah of Sehwan SharifBorn/: 98 Hijri Or 109 Hijri.Died: 151 AH ≈ 773 (aged 52–53)CEKnown for: Sufi mysticism****Last updated by NS on 01 MAY 2026', 0, 0, 0, 1790967396381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_636e7607b03977ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'How many Pakistanis won Noble Prize So far?', '{"A":"3","B":"1","C":"2","D":"4"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1. Dr. Abdul Salam (1979)2. Malala Yousafzai (2014)', 0, 0, 0, 1790967396381) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a22b147f1bc744f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Where are the Chaukhandi graves located?', '{"A":"29 km east of Karachi","B":"29 km east of Lahore","C":"29 km east of Hyderabad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Chaukhandi graves are located 29 km east of Karachi, Sindh province of Pakistan.They are famous for their delicate stone carvings with intricate geometric patterns.', 0, 0, 0, 1790967396381) ON CONFLICT(id) DO NOTHING;
