INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f747d73186ff005a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following is the longest Motorway?', '{"A":"M2","B":"M5","C":"M8","D":"M9"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The M8 Motorway, the longest in Pakistan.It spans 892 km from Ratodero to Gwadar.It is partially operational, with ongoing construction on remaining sections.The motorway will have 4 lanes.The M8 is being constructed by Pakistan''s National Highway Authority, with construction starting on 15 October 2004.', 0, 0, 0, 1790967396421) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b7a18759aae09a0a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'All Parties Conference was held in ______?', '{"A":"1927","B":"1929","C":"1928","D":"1930"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The All Parties Conference was a group of Indian political parties known for organizing a committee in May 1928 to author the Constitution of India after independence was actualized. It was chaired by Dr. M. A. Ansari.', 0, 0, 0, 1790967396421) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b4555babfef68e1a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'According to Labour Force Survey 2020-21, total labour force in Pakistan is ____?', '{"A":"67.25 million","B":"84.69 million","C":"71.76 million","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to the Labour Force Survey 2020-21, the total labour force in Pakistan was 71.76 million.This figure represents the number of people who are either employed or actively seeking employment during that period.', 0, 0, 0, 1790967396421) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c6fff52a4411c2df', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Wafaqi Mohtasib (Federal Ombudsman) was established on _____?', '{"A":"23rd January 1983","B":"23rd January 1984","C":"23rd January 1985","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Office of Wafaqi Mohtasib was established on 24 January 1983 under President''s Order No. 1 of 1983.It was formed by President Zia-ul-Haq to address public complaints against government maladministration.', 0, 0, 0, 1790967396421) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ad486da422e34b7a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Where is Kalabagh located?', '{"A":"Mianwali","B":"Sibbi","C":"Skardoo","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kalabagh is located in the Mianwali District of Punjab, Pakistan.It is well-known for the proposed Kalabagh Dam project.Kalabagh is famous for the mineral of Iron.369 million tons iron deposit.', 0, 0, 0, 1790967396421) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_900280bb0154900d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who founded the Sikh Empire and the first independent Sikh State in the Indian subcontinent?', '{"A":"Guru Daleep Singh","B":"Maharaja Ranjit Singh","C":"Guru Govind Singh","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maharaja Ranjit Singh founded the Sikh Empire in 1799 in the Indian subcontinent.The empire lasted until 1849, when it was annexed by the British East India Company.He was the founder of the first independent Sikh State.The Sikh Empire was centered in Punjab and extended across northwestern India.', 0, 0, 0, 1790967396421) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_23939bf47fe46a64', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The largest Railway workshop Mughalpura is situated in _____?', '{"A":"Multan","B":"Gujranwala","C":"Lahore","D":"Karachi","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Moghalpura Railway Workshops are situated in Lahore, Pakistan. Railway Workshops were established in 1897 since the British Rule Railway Workshops is the largest workshop in Pakistan', 0, 0, 0, 1790967396482) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8ae1fe2b2204266d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The first nuclear power plant in Pakistan was set up at Karachi in ____?', '{"A":"1971","B":"1972","C":"1973","D":"1974"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 28 November 1972, President Zulfiqar Ali Bhutto inaugurated the Karachi Nuclear Plant **Karachi Nuclear Power Plant (KANUPP) Unit 1. KANUPP is Pakistan’s first nuclear power plant, With a total gross capacity of 137 MW.K2 & K3 with the help of China K2 started on 21 May 2021 and has a 1100 MW capacity.K3 is expected to start in 2022.**ND13-1-2023', 0, 0, 0, 1790967396482) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0d2cbc52d3397583', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Who enforced the Basic Democracies System in 1959 to introduce a new Political System in the country?', '{"A":"Iskandar Mirza","B":"Mohammad Ali Bogra","C":"Khwaja Nazim Uddin","D":"Ayub Khan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation EBDO was promulgated by Ayub Khan in 1959. EBDO stand for Electoral bodies dissolution order.', 0, 0, 0, 1790967396482) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_29451b4e358cf5bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Hindu society divided into four different castes, with regard to their ______?', '{"A":"Religion","B":"Professions","C":"Tribe","D":"Qualification"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Brahmins – Priests, scholars, and teachers (highest caste).Kshatriyas – Warriors and rulers.Vaishyas – Traders and merchants.Shudras – Laborers and service providers.', 0, 0, 0, 1790967396482) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8830080f48d2bf81', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan’s renowned TV, Radio host, film actor, and politician Tariq Aziz passed away on which date?', '{"A":"17 August 2020","B":"17 June 2020","C":"17 April 2020","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tariq Aziz, Pakistan’s renowned TV and radio host, film actor, and politician, passed away on 17 June 2020 in Lahore at the age of 84. He was best known for hosting PTV’s iconic quiz show Nilaam Ghar (The Tariq Aziz Show and Bazm-e-Tariq Aziz)He was also the first person to appear on Pakistan Television (PTV) when it launched in 1964.​', 0, 0, 0, 1790967396482) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ce0ad2f8acbb016d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', '_________ belt of Afghanistan separate Tajikistan from Pakistan?', '{"A":"Durand line","B":"Wakhan","C":"Control line","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Wakhan Corridor is a narrow strip of territory in northeastern Afghanistan that extends to China. It separates Tajikistan from Pakistan.It is lies between Pakistan’s Gilgit-Baltistan region and China’s Xinjiang province.', 0, 0, 0, 1790967396482) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f403a233775e39d5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Deoband was a small town of _____?', '{"A":"Saharanpur","B":"Ferozpur","C":"Ali garh","D":"Merut"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation About Deoband MadrasahFounded: 31 May 1866Founder: Muhammad Qasim NanautaviFirst Principal: Maulana Muhammad QasimLocation: Saharanpur, Uttar Pardesh', 0, 0, 0, 1790967396482) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_59597519aba079e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Agra fort constructed by ______?', '{"A":"Akbar","B":"Shah Jahan","C":"Babar","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Akbar made it his capital and arrived in Agra in 1558. His historian, Abul Fazl, recorded that this was a brick fort known as ''Badalgarh''. It was in a ruined condition and Akbar had it rebuilt with red sandstone from Barauli area Dhaulpur district, in Rajasthan.', 0, 0, 0, 1790967396482) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_71e2cf7f4717ec96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which year Syed Jamal uddin Afhani died?', '{"A":"1895","B":"1896","C":"1897","D":"1898"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Syed Jamal Uddin Afghani was a Thinker.Syed Jamal-u-din Afghani Born: 1838, Asadabad, Afghanistan. Syed Jamal-u-din Afghani Died: March 9, 1897, İstanbul, Turkey. Syed Jamal-u-din Afghani Cause of death: Cancer of the jaw.', 0, 0, 0, 1790967396517) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1a983b51169e0ba0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan is located in which continent?', '{"A":"Africa","B":"Europe","C":"Asia","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan, officially the Islamic Republic of Pakistan, is a country in South Asia.Pakistan is the world''s fifth-most populous country.Pakistan is the world''s second-largest Muslim population.Pakistan is the 33rd-largest country by area.The capital of Pakistan is: Islamabadthe Currency of Pakistan is: the Pakistani rupee', 0, 0, 0, 1790967396517) ON CONFLICT(id) DO NOTHING;
