INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6668add2d54c8258', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of these is the largest forest of Pakistan?', '{"A":"Cholistan","B":"Thar","C":"Changa Manga","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Changa Manga Forest is the largest forest in Pakistan.It covering an area of approximately 12,510 acres (20.5 square miles).It is located in the Kasur district of Punjab, Pakistan.Changa Manga is a man-made (artificial) forest, established in 1866.', 0, 0, 0, 1790967396680) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7b8b2b3d82853038', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Montagu-Chelmsford Reforms were in ______?', '{"A":"1919","B":"1917","C":"1918","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Montagu-Chelmsford Report was published on July 8, 1918.The report was the result of discussions between Edwin Montagu, secretary of state for India from 1917 to 1922, and Lord Chelmsford, the viceroy of India between 1916 and 1921.The report was used as the basis for the Government of India Act of 1919.', 0, 0, 0, 1790967396680) ON CONFLICT(id) DO NOTHING;
