INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d835f50a8447327e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Sami Ullah Khan is famous player of _____?', '{"A":"Cricket","B":"Hockey","C":"Badminton","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Samiullah Khan born September 6, 1951, in Bahawalpur.He is a former field hockey player from Pakistan.He was nicknamed The Flying Horse because of his great speed.He is a former and veteran player of the Olympic Games.National Game of Pakistan: Field Hockey.', 0, 0, 0, 1790967396680) ON CONFLICT(id) DO NOTHING;
