INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2370ebbbf90017e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In which year PIA was established?', '{"A":"1955","B":"1957","C":"1958","D":"1959"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1955, Orient Airways merged with a newly formed state-owned entity.This resulting in the establishment of Pakistan International Airlines (PIA) on March 11, 1955.PIA serves as Pakistan''s national flag carrier.', 0, 0, 0, 1790967396751) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_eda20722b6f3755a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Where is the National Museum of Pakistan located?', '{"A":"Karachi","B":"Jamshoro","C":"Larkana","D":"Hyderabad","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The National Museum of Pakistan is located in Karachi, Pakistan. Situated in Burns Garden on Dr. Zia-ud-Din Ahmed RoadEstablished on 17 April 1950.There are approximately 16 museums in Pakistan.', 0, 0, 0, 1790967396785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3f2772dc8c5d02e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In Pakistan, which organization is responsible for regulation of stock exchange?', '{"A":"NADRA","B":"SBP","C":"NBP","D":"SECP","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation SECP stands for Securities and Exchange Commission of Pakistan.SECP headquarters located in Karachi, Sindh.', 0, 0, 0, 1790967396785) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1a3478ba95845064', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'When Pakistan introduced National Identity cards (NIC)?', '{"A":"1962","B":"1948","C":"1957","D":"1963","E":"1973"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan introduced National Identity cards (NIC) in 1973Pakistan initiated its National Identity Card System in 1973 under Article 30The card was first issued manually on hand-written paper in 1973the computerized card was issued in 2000IN 2012 the smart card was issuedThe first national identity card was issued by the authority to Zulfiqar Ali Bhutto.ND2023-2-12', 0, 0, 0, 1790967396785) ON CONFLICT(id) DO NOTHING;
