INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_213ee698f09b2301', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Molasses is by product of ______?', '{"A":"Sugar","B":"Salt","C":"Protein","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Molasses, from the Latin word melaceres, meaning honey-like, is a thick dark syrup that is a byproduct of sugar refining.It results when sugar is crystallized out of sugar cane or sugar beet juice.', 0, 0, 0, 1790967397159) ON CONFLICT(id) DO NOTHING;
