INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e3c5e0bb490b2b4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'In 1954, Pakistan joined ____?', '{"A":"SEATO","B":"CENTO","C":"OIC","D":"Commonwealth"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1954 Pakistan become a member of SEATO**SEATO is an abbreviation of: South East Asia Treaty Organization**SEATO was founded on 8th September 1954 and dissolved on 30th June 1977In September of 1954, the United States, France, Great Britain, New Zealand, Australia, the Philippines, Thailand and Pakistan formed the Southeast Asia Treaty Organization, or SEATO.MUG 05-12-2022', 0, 0, 0, 1790967397791) ON CONFLICT(id) DO NOTHING;
