INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0be58f9e9fc7dfbb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Sadqain is famous for ______?', '{"A":"Calligrapher","B":"Painter","C":"Athlete","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sadqain is also known as Syed Sadequain Ahmed Naqvi.He is renowned for being both a calligrapher and a painter.He is considered one of Pakistan''s finest artists in Islamic calligraphy and modern painting.He is also recognized as the only artist in Pakistan to have received all four civilian awards such as"Nishan-i-ImtiazSitara-i-Imtiaz Tamgha-i-Imtiaz Pride of Performance', 0, 0, 0, 1790967397866) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6ed004910172691c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan is ______ km wide from east to west.', '{"A":"875","B":"885","C":"865","D":"895"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation North to South Length:Pakistan stretches about 1,600 kilometers (1,000 miles) from north to south.East to West Width:The width of Pakistan from east to west is approximately 885 kilometers (550 miles). Total Area:The total area of Pakistan is around 796,700 square kilometers (307,374 square miles). Coastline:Pakistan has a coastline of about 1,000 kilometers (620 miles) along the Arabian Sea.Exclusive Economic Zone (EEZ):The country’s Exclusive Economic Zone extends over 270,000 square kilometers', 0, 0, 0, 1790967397866) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_577c906407868bbd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Peacock Throne was made for ____?', '{"A":"Shah Jahan","B":"Aurangzeb","C":"Jahangir","D":"Akbar"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shah Jahan, born on January 5, 1592, in Lahore.He was the fifth emperor of the Mughal Empire.He reigning from January 1628 until July 1658.He was the first Mughal Emperor to sit on the Peacock Throne.Shah Jahan died on January 22, 1666, at Agra Fort, Agra, India.He is buried at the Taj Mahal, Agra, India.His full name was A''la Azad Abul Muzaffar Shahab ud-Din Mohammad Shah Jahan.', 0, 0, 0, 1790967397866) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a50911a026129ee0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Baluchistan plateau lies in _____?', '{"A":"East of Koh Kirthar and Sulaiman range","B":"West of Koh Kirthar and Sulaiman range","C":"South of Koh Kirthar and Sulaiman range","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Balochistan plateau is located on west side of the Sulaiman and Kirthar ranges.Balochistan plateau temperatures rising as high as 120 degrees F (50 degrees C).The desert climate is characterized by hot and very arid conditions.Thar desert is a hot desert.It is also called the Great Indian Desert.The mean average temperature varies from a minimum of 24 degrees C to 26 degrees C in summer to 4 degrees C to 10 degrees C in winter.', 0, 0, 0, 1790967397866) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4a98911708a78c05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Gadani Beach is located in ____?', '{"A":"Sindh","B":"Khyber PakhtoonKhawa","C":"Punjab","D":"Balochistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gadani Beach is situated on the Arabian Sea near the Hub River and Cape Monze in Gadani, Lasbela District, Balochistan, Pakistan.It is known for its ship-breaking yard.It is one of the largest in the world.It is scenic coastal views.', 0, 0, 0, 1790967397866) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1cdfe6b3826c73a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Al-Biruni came to India with ______?', '{"A":"Alexander the Great","B":"Mehmud Ghaznavi","C":"Muhammad Ghori","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Al-Biruni was taken to Ghazni, the capital of the Ghaznavid dynasty, where he served as court astrologer and accompanied Mahmud on his invasions into India.He lived in India for several years.He was forty-four years old during his journeys with Mahmud of Ghazni.Al-Biruni passed away in Ghazni.', 0, 0, 0, 1790967397866) ON CONFLICT(id) DO NOTHING;
