INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_728fdbaa551d9390', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Pakistan has borders with ____and _____?', '{"A":"Saudi Arabia/Iraq","B":"China/Iran","C":"Yemen/Qatar","D":"Canada/USA","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan is bounded by Iran to the west, Afghanistan to the northwest and north, and China to the northeast.Pakistan''s total land border is 6,774KM longPakistan''s total land border with four countries and sea.Pakistan borders India 2,912 KM long in the east,Afghanistan border is 2,430 KM long in the west (northwest)Iran border is 909 KM long also in the westChina 523 KM long border is situated in the northeast.The beach of the Arabian Sea 1042 forms its southern border.', 0, 0, 0, 1790967398115) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_413ef578fe1968cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is Current Share of Pakistan in World Population?', '{"A":"2.20%","B":"2.30%","C":"2.40%","D":"3.12%"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan accounts for approximately 3.12% to 3.14% of the total global population. This means roughly 1 in every 32 people on the planet resides in Pakistan.', 0, 0, 0, 1790967398115) ON CONFLICT(id) DO NOTHING;
