INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e9e5f2fbf4233e1b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Which of the following was founded in 1885?', '{"A":"Anjuman Himayat-e-Islam","B":"Indian National Congress","C":"Muslim League","D":"Muslim Students Federation","E":"United Nations Organization"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indian National Congress (INC) was formed on 28 December 1885 in Bombay (now Mumbai), British India.The first session was held at Gokuldas Tejpal Sanskrit College.Headquarters: New Delhi, IndiaFounder: Allan Octavian Hume (with support from Indian leaders)First President: Womesh Chunder BonnerjeePurpose: To represent Indian political interests and later lead the Indian independence movement.Last updated 26-07-2026 by NA', 0, 0, 0, 1790967398153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ad6a09230d0a34dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'Lakhra town is famous for its ___________.', '{"A":"Coal","B":"Apple","C":"Copper Mines","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lakhra Coal field was dedicated in 1990 to coal-fired power generationLakhra Coal field is located in Sindh the North of HyderabadThe Lakhra coalmine is spread over an area of 1,309sq kmThe Lakhra coal field is located on the west side of the Indus River Valley Lakhra town is famous for its CoalThe mine has coal reserves amounting to 1.33 billion tonnes of coking coalLakhra Coal field one of the largest coal reserves in Pakistan****nd9-2-2023', 0, 0, 0, 1790967398153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cb5fe3655f186473', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'How many people were killed in Quetta in the earth quake?', '{"A":"34,000 to 50,000","B":"35,000 to 60,000","C":"36,000 to 70,000","D":"30,000 to 60,000"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 1935 Quetta earthquake occurred on 31 May between 2:33 am and 3:40 am at Quetta, Balochistan. The earthquake had a magnitude of 7.7 Mw 30,000 to 60,000 people were killed in Quetta during the earthquake.', 0, 0, 0, 1790967398153) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6771b57156d53c7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'What is the old name of Attock?', '{"A":"Campbellpur","B":"Shalkot","C":"NeroonKot","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Attock fort was built by the Mughal Emperor Akbar in 1581 to support his own wars in Afghanistan.Mughal Emperor Akbar built the Lahore Fort, as well as the city walls which had 12 gates.Campbellpur is the old name of Attock.', 0, 0, 0, 1790967398153) ON CONFLICT(id) DO NOTHING;
