INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cf6211b4352ce321', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_general', 'The Mongols defeated?', '{"A":"The Abbasids","B":"Salahuddin Ayyubi","C":"Ummayed","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Mongol Empire of the 13th and 14th centuries It was the largest contiguous land empire in history.Founded: 1206Date dissolved: 1368', 0, 0, 0, 1790967398918) ON CONFLICT(id) DO NOTHING;
