INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8303b833f086face', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Where is the cold desert known as the Katpana Desert located?', '{"A":"Chitral, Khyber Pakhtunkhwa, Pakistan","B":"Skardu, Gilgit-Baltistan, Pakistan","C":"Hunza, Gilgit-Baltistan, Pakistan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Katpana Desert is a cold desert Located in Skardu, Gilgit-Baltistan, Pakistan.Altitude: 2,226 meters above sea levelGlobal ranking: 16th largest desert in the worldApproximate area: ~50 km²Average winter temperature: -10°C to 5°CLast updated 07-09-2026 by NA', 0, 0, 0, 1790967398975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_aca77c51bee83573', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the world’s most polluted city, as per the US Air Quality Index?', '{"A":"Karachi","B":"Delhi","C":"Lahore","D":"New York"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Top three polluted city in the World:1. Lahore, Pakistan2. Delhi, India 3. Mexico City, MexicoSource Click hereLast verified on 06-03-2026', 0, 0, 0, 1790967398975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a0a4958a5659974f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the first/old Capital of Pakistan?', '{"A":"Karachi","B":"Rawalpindi","C":"Lahore","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Karachi was the first and old capital of Pakistan.It was chosen by Muhammad Ali Jinnah in 1947.It remained the capital until 1959.From 1959–1967, Rawalpindi served as the interim capital.Islamabad became the official capital on 14 August 1967.Karachi is in Sindh province.It was the political center at independence.Last verified on 02-03-2026', 0, 0, 0, 1790967398975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_01ab24446533aed9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The largest province of Pakistan by area is _____?', '{"A":"Baluchistan","B":"Punjab","C":"Sindh","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Baluchistan is the biggest province of Pakistan by area.It covers 43% of the area of PakistanCapital City: QuettaEstablished: 1 July 1970Additional information:Punjab is the biggest province of Pakistan by population.Last verified on 26-05-2026', 0, 0, 0, 1790967398975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_41375443077250c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'What is the capital of Pakistan?', '{"A":"Lahore","B":"Islamabad","C":"Karachi","D":"Sialkot"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Capital: IslamabadConstruction began: 1960Officially became the capital: 14 August 1967President at the time: Ayub KhanPrevious capital: KarachiAdditional informationCurrency is the Pakistani Rupee.Official language is Urdu; English.Located in Continent Asia.Primary Religion is Islam.Head of Govt. is Prime Minister –Shehbaz Sharif.Pakistan Parliament is called the National Assembly & Senate.Tricks for RememberRUPEEMind Tricks : PICS of MN***PICS***P - PakistanI - IndiaC - CeylonS - Srilanka**MN**M - MaritiusN - Nepal', 0, 0, 0, 1790967398975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5100e3686f8282ef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Sindh separated from Bombay in which year?', '{"A":"1935","B":"1936","C":"1938","D":"1939"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Became separate province: 1 April 1936, capital KarachiAnnexed to Bombay Presidency: 1843Part of Pakistan: 14 August 1947 – 14 October 1955, capital HyderabadSeparation demanded by: Muhammad Ali Jinnah in 1929 under Government of India Act 1935First Muslim League Government in Sindh: 1943Last verified on 15-01-2026', 0, 0, 0, 1790967398975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bdae4b254dc0a241', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Mohammed Bin Qasim conquered Sindh in the year?', '{"A":"812 AD","B":"712 AD","C":"912 AD","D":"1012 AD"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Conquest of Sindh: 712 ADBattle: Aror (near Rohri)Opponent: Raja Dahir (killed in battle)He attacked Sindh on orders of the Umayyad Caliph through Hajjaj bin Yusuf.Death: 18 July 715 ADMajor cities captured:NirunDebal (Sikka fortress)BrahmanabadAlor (Aror)MultanLast verified on 01-04-2026', 0, 0, 0, 1790967398975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0705165ba9f587de', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The Largest Desert of Pakistan is?', '{"A":"Thall Desert","B":"Thar Desert","C":"Cholistan Desert","D":"Kharan Desert"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Thar Desert is the largest desert in Pakistan.It is the only subtropical desert in Asia.It is the 3rd largest in Asia.It spans an area of 175,000 square kilometers.It covers large areas of Pakistan and India.Pakistan hosts five major deserts which were historic forests:Cholistan (Bahawalpur, Punjab)Thal (Bakhar district of Punjab)Katpana desert (Sakardu)Kharan desert (Balochistan)Thar desert (Sindh)Last verified on 02-04-2026', 0, 0, 0, 1790967398975) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_30cc455501774d0e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the largest river in Balochistan?', '{"A":"Dasht river","B":"Porali river","C":"Hub river","D":"Hungol river"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hingol River is the longest river in Balochistan.Location: Makran region, Gwadar District, southeastern Balochistan.Length: About 560 km (350 miles).The Hanna River is the smallest river in Balochistan.Additional information:Punjab: Sutlej RiverSindh: Indus RiverKhyber Pakhtunkhwa: Kabul RiverLast verified on 28-09-2026', 0, 0, 0, 1790967399003) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_04a8894ccf67e7e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'What is the height of K2 (Godwin Austin), second highest mountain of world?', '{"A":"8,511 meters (27,923 feet)","B":"8,611 meters (28,251 feet)","C":"8,848 meters (29,029 feet)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation K-2 (Godwin Austin) has a total height of 8,611 meters (28,251 feet).It is the second-highest mountain in the world after Mount Everest.K2 is part of the Karakoram Range.It is located on the Pakistan–China border in the Gilgit-Baltistan region of Pakistan.The letter "K" stands for Karakoram.Last verified on 12-03-2026', 0, 0, 0, 1790967399003) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c9dad5c5f52e93c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The city is known as the "City of Lights" in Pakistan is?', '{"A":"Karachi","B":"Quetta","C":"Lahore","D":"Multan"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Karachi is known as the "City of Lights" in Pakistan.This nickname in the 1960s and 1970s for its vibrant nightlifeIt is the largest city in PakistanKnown as the ''Economic Hub of Pakistan''.Last updated on 11-02-2026', 0, 0, 0, 1790967399003) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_65fd6ea83e32a5ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Nanga Parbat is located in which range?', '{"A":"Karakorum","B":"Hamalayas","C":"Kirthar","D":"Hindu Kush"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nanga Parbat is part of the Western Himalayas in Gilgit-Baltistan.It is also locally known as Diamer.The peak, meaning "Naked Mountain".Stands at 8,126 m (26,660 ft).9th-highest mountain globally.Also called the "Killer Mountain."It was first ascended on July 3, 1953.Shehroze Kashif recently became the youngest Pakistani to summit it.Last verified by on 16-05-2026', 0, 0, 0, 1790967399003) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2fc1044834b48349', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'How many canals take off from Sukkur Barrage?', '{"A":"9","B":"7","C":"10","D":"5"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 7 CanalsLeft Bank: Khairpur West, Rohri, Khairpur East, Eastern NaraRight Bank: North West, Rice, DaduAdditional information:Sukkur BarrageLocation: Sindh, PakistanOfficial Name: Lloyd BarrageBuilt: 1923Completed: 1932Length: About 2 kmOldest: Oldest barrage in PakistanLast updated by NA ON 16-09-2026', 0, 0, 0, 1790967399003) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c5473b4df93c7a73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'How many districts are there in Khyber Pakhtunkhwa (KPK)?', '{"A":"38","B":"40","C":"42","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khyber Pakhtunkhwa currently has 40 districts.In 2025, Swat was divided into Swat and Upper Swat, increasing the total from 38 to 40.Additional information:Punjab: 42 districtsSindh: 30 districtsBalochistan: 41 districtsIslamabad Capital Territory (ICT): 1 districtGilgit-Baltistan (GB): 14 districtsAzad Jammu & Kashmir (AJK): 10 districtsLast verified on 14-07-2026', 0, 0, 0, 1790967399003) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_eed8f71668c4e410', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Rawal lake is situated in which city of Pakistan?', '{"A":"Lahore","B":"Islamabad","C":"Karachi","D":"Chitral"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rawal Lake is an artificial reservoir located in Islamabad, Pakistan.It was constructed in 1962 to supply water to Islamabad and Rawalpindi.The lake is surrounded by the Margalla Hills.Rawal Lake Park (Lake View Park) is a popular recreational area nearby.It is an important source of water for the twin cities.Last verified on 14-09-2026', 0, 0, 0, 1790967399003) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a6199ac40c3d33d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'K2 (Godwin Austin), the second-highest mountain in the world, is located in which mountain range?', '{"A":"Himalayas","B":"Hindu Kush","C":"Karakoram Range","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation K2 is part of the Karakoram Range.It is located on the border between Baltistan, in the Gilgit–Baltistan region of Pakistan.Additional information:K-2 is also known as Godwin Austin.''K'' standing for Karakoram.Mount K2 is the second-highest mountain on Earth.Mount K2 is located on the border of Pakistan and China.The height of K2 is 8,611 meters.Last verified on 12-03-2026', 0, 0, 0, 1790967399003) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_853cbc154721e514', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Where is Satpara Lake situated?', '{"A":"Sindh","B":"Punjab","C":"Khyber Pakhtunkhwa","D":"Gilgit Baltistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Satpara Lake is a natural lake near Skardu, Gilgit-Baltistan, Pakistan.It is fed by the Satpara Stream.It is located at an elevation of about 2,636 meters (8,648 feet) above sea level.The lake covers an area of approximately 2.5 km².Additional information:Attabad Lake — Gilgit-BaltistanSaiful Muluk Lake — Khyber PakhtunkhwaKeenjhar and Manchar Lake — SindhLast verified on 14-09-2026', 0, 0, 0, 1790967399032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a840cf7ae2f38444', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'What is the border between Pakistan and Afghanistan called?', '{"A":"Durand Line","B":"Line of control","C":"Free Line","D":"Dukhtar Line"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The border between Pakistan and Afghanistan is called the Durand Line.It was drawn in 1893.It was established as the official border between British India and Afghanistan.British representative: Sir Mortimer DurandAfghan ruler: Amir Abdur Rahman KhanLength: Around 2,640 km (2,611 km)اچھی تیاری کرنا چاہتے تو یہ سوالات ضرور پڑھیںClick hereLast verified on 09-06-2026', 0, 0, 0, 1790967399032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_15bd4bcca7713611', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Tarbela Dam is build on which river?', '{"A":"Indus","B":"Ravi","C":"Satluj","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tarbela Dam was built on the Indus River.It is located mainly in the Swabi District Tehsil Topi of KPK.It is the largest earth-filled dam in the world.The Construction began in 1968. They were Opened in 1976.Height: 470 feet (143 m)Last verified on 30-03-2026', 0, 0, 0, 1790967399032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f815c12ef0c1f624', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The longest (largest) river in Pakistan is ____?', '{"A":"Ravi","B":"Indus","C":"Chenab","D":"Jhelum"}', 'B', NULL, 0, 0, 0, 1790967399032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_77f0fbb73c1fe326', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which rivers were given to India under Indus Waters Treaty 1960?', '{"A":"Jhelum, Sutlej, Ravi","B":"Chenab, Beas, Ravi","C":"Sutlej, Beas, Ravi","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation India got the Eastern Rivers:RaviBeasSutlejPakistan got the Western Rivers:IndusJhelumChenabSigned date: 19 September 1960Brokered by: World BankPlace of signing: KarachiEffective from: 1 April 1960 (implementation period)Signatories:Field Marshal Ayub Khan (Pakistan)Jawaharlal Nehru (India)Last updated NA on 10-09-2026', 0, 0, 0, 1790967399032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7066222bc9b08c33', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which River is known as the ''Lifeline of Pakistan''?', '{"A":"Chenab","B":"Indus","C":"Ravi","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indus River is widely known as the lifeline of Pakistan.It is the longest river in Pakistan.The Indus River is essential for agriculture, irrigation, drinking water, and hydropower.Additional information:Length: Approximately 3,180 kmOrigin: Tibetan Plateau, near Lake ManasarovarMouth: Arabian Sea, near the Indus Delta.Last verified on 07-09-2026', 0, 0, 0, 1790967399032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9ce4e33a5653157b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Under Indus Water Treaty which of the following rivers were given to Pakistan?', '{"A":"Indus, Jhelum and Chenab","B":"Ravi and Indus","C":"Indus and Jhelum","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Treaty allocates the Western Rivers (Indus, Jhelum, Chenab) to PakistanThe Eastern Rivers (Ravi, Beas, Sutlej) to IndiaIndus Waters Treaty signed on September 19, 1960, Between India and PakistanTreaty was brokered by the World BankSigned at Karachi by Field Marshal Mohammad Ayub Khan,The then President of Pakistan, Jawaharlal Nehru The then Indian Prime Minister, and Mr. W.A.B. Illif The Treaty is effective from 1st April 1960 Last updated by NS on 26 JULY 2026', 0, 0, 0, 1790967399032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_23a92a7a22134cbb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Goldsmid Line is the border between ______?', '{"A":"China & Taiwan","B":"Pakistan & Iran","C":"China & Bhutan","D":"China & India"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Goldsmid Line marks the border between present-day Pakistan and Iran.It was established through the Goldsmid Commission in 1871–1872.The boundary was surveyed under Major-General Frederick John Goldsmid.It forms part of the Pakistan–Iran international border.Last verified on 05-09-2026', 0, 0, 0, 1790967399032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_40730fa7befeee2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'What is the total length of Indus River?', '{"A":"2514 km","B":"3180 km","C":"2900 km","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790967399059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_240a7e83b747fb61', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Balochistan province is located in ______ of Pakistan.', '{"A":"North West","B":"South West","C":"West","D":"South"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Balochistan is located in the south-western part of Pakistan.It is the largest province of Pakistan by area.It shares borders with Iran and Afghanistan.It also has a coastline along the Arabian Sea.Its capital is Quetta.Additional information:Punjab → EastSindh → South-EastKP → North-WestLast verified on 04-09-2026', 0, 0, 0, 1790967399059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_dc202488cbae1d40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Pakistan’s largest oil fields are located in District ______?', '{"A":"Badin","B":"Tando Muhammad Khan","C":"Hyderabad","D":"Attock"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan’s largest oil fields are located in District Attock.Khaur Oil Field is located in Attock District.Khaur was discovered in 1915 by the Attock Oil Company.It is considered the oldest oil field in Pakistan.Joya Mair Oil Field was discovered in 1944.Balkassar Oil Field is located in Jhelum District.Last verified on 04-09-2026', 0, 0, 0, 1790967399059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_09c34c3b3fefd640', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'What is the total area of the Islamabad Capital Territory (ICT)?', '{"A":"796 km²","B":"806 km²","C":"906 km²","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Total Area: 906 km² (350 sq mi)Construction Began: 1960Capital Status: 14 August 1967Population: Over 1.2 millionPostcode: 44000Additional information:Balochistan: 347,190 sq. km — largest province by area.Punjab: 205,344 sq. kmSindh: 140,914 sq. kmKhyber Pakhtunkhwa (KP): 74,521 sq. kmGilgit-Baltistan (GB): 64,817 sq. kmAzad Jammu & Kashmir (AJK): 13,297 sq. kmLast verified on 19-07-2026', 0, 0, 0, 1790967399059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d84c5e41bb82e80a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'What is the length of the border between Pakistan and Afghanistan?', '{"A":"2611 km","B":"2350 km","C":"2282 km","D":"2430 km"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Current/Survey of Pakistan 2021 figure: 2,611 kmOlder figure: 2,430 kmName of border: Durand LineYear of agreement: 1893British representative: Sir Mortimer DurandAfghan ruler: Amir Abdur Rahman KhanLast verified on 03-09-2026', 0, 0, 0, 1790967399059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_926f880ead87aaba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Islamabad was officially made the capital of Pakistan in _____?', '{"A":"July 14, 1967","B":"August 14, 1967","C":"June 14, 1967","D":"September 14, 1967"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Islamabad officially became the capital of Pakistan on 14 August 1967, under President Ayub Khan.The city was constructed starting in 1960.It is now the country''s ninth-most populous city, with a population of over 1.2 million.Its postcode is 44000.Before being named the capital, the area was known as Raj Shahi.Last verified on 30-03-2026', 0, 0, 0, 1790967399059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_342b057eac407a14', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Pak-Afghan border ''Durand Line'' was drawn in ______?', '{"A":"1892","B":"1890","C":"1893","D":"1957"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Durand Line was drawn in 1893.It was established as the official border between British India and Afghanistan.British representative: Sir Mortimer DurandAfghan ruler: Amir Abdur Rahman KhanIt later became the international border between Pakistan and Afghanistan.Length: Around 2,640 kmLast verified on 09-06-2026', 0, 0, 0, 1790967399059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_aba1e75505f7103c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the capital of Azad Jammu and Kashmir?', '{"A":"Bagh","B":"Skardu","C":"Mirpur","D":"Muzaffarabad"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muzaffarabad is the capital and largest city of Azad Jammu and KashmirEstablished 1646Founded by Sultan Muzaffar KhanSituated at the Jhelum and Neelum riversAdditional informationAJK was established on October 24, 1947.The region covers an area of 13,297 km² (5,134 sq mi).Last updated by NA on 06-March-2026', 0, 0, 0, 1790967399059) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_76ca022d7c4d76e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'What is the length of border between Pakistan and China?', '{"A":"595 km","B":"900 km","C":"599 km (596)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Pakistan-China border (Northeast) is 599 km (596) long.Additional information:Pakistan’s borders with neighbors:India: 2,100 km (East)Afghanistan: 2,611 km (West/Northwest)Iran: 909 km (West)Other borders:Arabian Sea coast: 1,058 km (South)Total land border: 6,219 kmLand + Sea border: 7,277 kmLand + Sea + LOC & Working Boundary: 8,340 kmLast verified on 16-01-2026', 0, 0, 0, 1790967399090) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a1d9547afee9c997', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Kharan desert is located in which province?', '{"A":"Sindh","B":"Punjab","C":"Balochistan","D":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Province: BalochistanDistrict: KharanLocation: Southwestern PakistanNearby country: IranType: Sandy and mountainous desertLast verified on 01-09-2026', 0, 0, 0, 1790967399090) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3c39e4dc1af462a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'What is the height of Nanga Parbat?', '{"A":"8226m","B":"8126m","C":"8326m","D":"8026m"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The height of Nanga Parbat is 8,126 metres (26,660 feet).It is located in Gilgit-Baltistan.It is part of the Western Himalayas.It is locally known as Diamer.It is the 9th-highest mountain in the world.It is famously called the "Killer Mountain."First Ascent: 3 July 1953Shehroze Kashif became the youngest Pakistani to successfully summit Nanga Parbat.Last verified by on 16-05-2026', 0, 0, 0, 1790967399090) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1fbe681dd6c85e50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Pakistan is having its longest border with ______?', '{"A":"India","B":"Afghanistan","C":"Iran","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Pakistan-Afghanistan border (West/Northwest) is 2,611 km long.Additional information:Pakistan’s borders with neighbors:India: 2,100 km (East)China: is 599 km (Northeast)Iran: 909 km (West)Other borders:Arabian Sea coast: 1,058 km (South)Total land border: 6,219 kmLand + Sea border: 7,277 kmLand + Sea + LOC & Working Boundary: 8,340 kmLast verified on 16-01-2026', 0, 0, 0, 1790967399090) ON CONFLICT(id) DO NOTHING;
