INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6891a3ffb8738f85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Reko Diq reserves of copper and gold are situated in ______ district of Baluchistan.', '{"A":"Lasbela","B":"Chagai","C":"Quetta","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Location: Chagai District, BalochistanMain Minerals: Copper and GoldRegion: Tethyan Metallogenic BeltDiscovery: 1993Significance: One of the world''s largest undeveloped copper-gold depositsLast verified on 20-07-2026', 0, 0, 0, 1790967399192) ON CONFLICT(id) DO NOTHING;
