INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_243d92ba851e9817', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the highest peak of Koh-e-Suleiman range?', '{"A":"Kirther","B":"Makran","C":"Takht-e-Suleiman","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Takht-e-Sulaiman is a peak of the Sulaiman Mountains.It is close to Dera Ismail Khan Subdivision''s borders with both South Waziristan and Zhob, Balochistan.Elevation: 3,487 mLocation: PakistanMountain range: Sulaiman MountainsFirst ascender: George WhiteLast verified on 25-05-2026', 0, 0, 0, 1790967399424) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a4c981c9a2978396', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which one is the highest peak (mountain) of the Hindu Kush range in Pakistan?', '{"A":"Tirich Mir","B":"Nanga Parbat","C":"K-2","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The highest peak of the Hindu Kush range in Pakistan is Tirich Mir.It is located in the Chitral District of Khyber Pakhtunkhwa. Elevation: (7,708) meters (25,289) ft.Additional information:Highest peak of the Himalaya range: Nanga ParbatHighest peak of the Karakoram range: K-2Highest peak of the Kirthar range: Zardak PeakHighest peak of the Koh-e-Suleman range: Takht-e-SulaimanHighest peak of the Salt range: SakesarLast verified on 16-05-2026', 0, 0, 0, 1790967399424) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b2acd1e335b99c03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', '“Dasht-e-Lut” desert is located in _____?', '{"A":"Iran","B":"Iraq","C":"Libya","D":"China"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dasht-e Lut is located in southeastern Iran.It lies mainly in the provinces of Kerman and Sistan & Balochistan (Iran).Area: 51,800 km²Length: 480 km (approx.)Rank: 33rd largest desert in the worldUNESCO listing: 17 July 2016Last verified on 02-05-2026', 0, 0, 0, 1790967399424) ON CONFLICT(id) DO NOTHING;
