INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0aa11871be160cd8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The Biafo Glacier is located on which of the following range?', '{"A":"Pir Panjal","B":"Karakorum","C":"Himalaya","D":"Hindukush"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Baltoro Glacier is located in the Karakoram range of Pakistan.The Baltoro Glacier, at 62 km in length.It is located in the Shigar district Gilgit-Baltistan region of Pakistan.Last verified on 16-05-2026', 0, 0, 0, 1790967399460) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e125ff45a5b5fd05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The highest peak of Karakorum range is _____?', '{"A":"K2","B":"Nanga Parbat","C":"Broad Peak","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation K2 is part of the Karakoram Range.It is located on the border between Baltistan, in the Gilgit–Baltistan region of Pakistan.Additional information:K-2 is also known as Godwin Austin.''K'' standing for Karakoram.Mount K2 is the second-highest mountain on Earth.Mount K2 is located on the border of Pakistan and China.The height of K2 is 8,611 meters.Last verified on 12-03-2026', 0, 0, 0, 1790967399460) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b00d12ad5dbfec82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which of the following pass connects Abbotabad and Gilgit?', '{"A":"Dargai Pass","B":"Bolan Pass","C":"Tochi Pass","D":"Babusar Pass"}', 'D', NULL, 0, 0, 0, 1790967399460) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ddbbf80006740199', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The historical Ranikot Fort is situated in which District of Sindh?', '{"A":"Jacobabad","B":"Shikarpur","C":"Kashmore","D":"Jamshoro"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ranikot Fort is a Talpur fort near Sann, Jamshoro District, Sindh.It is also known as The Great Wall of Sindh.The length of Ranikot Fort is 32 km.It is believed to be the world''s largest fort.Ranikot fort''s ramparts have been compared to the Great Wall of China.It constructed during the administration of Nawab Wali Muhammed Leghari, the Prime Minister of Sindh during the Talpur dynasty.Last verified on 16-05-2026', 0, 0, 0, 1790967399460) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2afec130f0a423f6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the highest peak of Himalayas range in Pakistan?', '{"A":"K-2","B":"Nanga Parbat","C":"Sakasar","D":"Tirichmir"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Nanga Parbat is the highest peak of the Himalayan range located in Pakistan.It is the 9th highest mountain in the world.It is known as the “Killer Mountain” due to its difficult climbing conditions.It is part of the western Himalayas in Gilgit-Baltistan.Height: 8,126 meters (26,660 ft)Last verified on 13-05-2026', 0, 0, 0, 1790967399460) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f66e243d6805242e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the highest mountain peak of Pakistan?', '{"A":"Tirich Mir","B":"Nanga Parbat","C":"K2","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation K2 is part of the Karakoram Range.It is located on the border between Baltistan, in the Gilgit–Baltistan region of Pakistan.Additional information:K-2 is also known as Godwin Austin.''K'' standing for Karakoram.Mount K2 is the second-highest mountain on Earth.Mount K2 is located on the border of Pakistan and China.The height of K2 is 8,611 meters.Last verified on 12-03-2026اچھی تیاری کرنی ہے تو یہ سوالات ضرور پڑھیںClick here', 0, 0, 0, 1790967399460) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6de6ad0c326eba86', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The Second Highest mountain of the world K-2 is located in _______?', '{"A":"Balochistan","B":"KPK","C":"Kashmir","D":"Gilgit Baltistan"}', 'D', NULL, 0, 0, 0, 1790967399460) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_54a89e7c6e6a1ecf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The only fertile desert in the world is__________?', '{"A":"Sahara Desert","B":"Dasht -e Lut Desert","C":"Great Thar Desert","D":"Chihuahuan Desert"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The only fertile desert in the world is the Tharparkar Desert, Located in Sindh, Pakistan. Known as the world''s 18th-largest desert, It is deemed "fertile" because, unlike typical arid deserts,Around 85% of the desert is in India, while the remaining part is in SindhLast updated question by NS on 11 May 2026', 0, 0, 0, 1790967399497) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_23d0457d0e895c38', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'What is the highest Peak in Pakistan?', '{"A":"Rakaposhi","B":"Tirich Mir","C":"K2","D":"Nanga Parbat"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation K2 is the highest pointin Pakistan.K2, at 8,611 meters above sea levelSecond-highest mountain in the world.It is located on the China–Pakistan border Between Baltistan in the Gilgit-Baltistan region of northern Pakistan.It was first measured by Godwin Austen in 1856.Additional information:Mount Everest is the Highest peak in the world. It is located in NepalMount Everest at 8,848 meters.Last updated by NA on 26 April 2026', 0, 0, 0, 1790967399497) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_eb011c334a72936d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The largest dam of Pakistan is _____?', '{"A":"Tarbela Dam","B":"Mangla dam","C":"Warsak dam","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The largest dam in Pakistan is the Tarbela Dam.Located in the Haripur district of Khyber Pakhtunkhwa.Built over the River Indus.485 feet (148 m) high above the Indus riverbed.The largest earth-filled dam in the world.Construction began in 1968.Completed in 1976.Last verified on 10-05-2026', 0, 0, 0, 1790967399497) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_13c563724be2bc0d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'CPEC connected Gwadar to city of China ______?', '{"A":"Beijing","B":"Wakhan","C":"Kashgar","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CPEC connects Gwadar Port in Pakistan with Kashgar in China’s Xinjiang region.The project was initiated in 2013.It was formally launched in April 2015.CPEC is part of China’s Belt and Road Initiative (BRI).Initial estimated investment was about $46 billion.Last verified on 09-05-2026', 0, 0, 0, 1790967399497) ON CONFLICT(id) DO NOTHING;
