INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d91833f653e2d345', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'What is the Height of Tirich Mir peak?', '{"A":"7350 meters","B":"7708 meters","C":"7140 meters","D":"7870 meters"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tirich Mir is the highest mountain in the Hindu Kush rangeIt’s the 33rd-highest peak in the world.It is the highest mountain in the worldTirich Mir is located in the Chitral District of Khyber PakhtunkhwaTirich Mir height: 7708 meters Its first recorded climber on 21 July 1950 by a NorwegianAdditional Information:Pakistan Highest Peaks List:Himalayas range: Nanga ParbatK-2: Krakarm rangeKirthar: Zardak peakKoh e Suleman: Takhat e SulaimaniSalt range: Sakesar*****Reference Click here', 0, 0, 0, 1790967399859) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ad2ecbbbe46f34b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Astola and Manora islands are located in which sea?', '{"A":"Arabian Sea","B":"South China Sea","C":"Atlantic Ocean","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Astola and Manora are coastal islands of Pakistan, both located in the Arabian Sea.Astola is Pakistan’s largest offshore island, while Manora is near Karachi.', 0, 0, 0, 1790967399859) ON CONFLICT(id) DO NOTHING;
