INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ad36fe8dbbfbdcef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The Sindh Provincial Museum is located in ____?', '{"A":"Karachi","B":"Jamshoro","C":"Hyderabad","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Sindh Museum was establish in 1971 to collect, preserve, study, and exhibit the records of the cultural history of Sindh and Indus Valley Civilization.', 0, 0, 0, 1790967399881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6e5d58c5b4eefc13', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Chashma Barrage has been built on the which river?', '{"A":"Jhelum","B":"Chenab","C":"Indus","D":"Ravi","E":"Kabul"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Chashma Barrage has been built on the Indus riverIt is located in Mianwali District, Punjab. Chashma Barrage Construction began1967Chashma Barrage Opening date 1971Chashma Barrage Length is 1,084 m (3,556 ft)***ND4-12-2022', 0, 0, 0, 1790967399881) ON CONFLICT(id) DO NOTHING;
