INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b96aaa1300ce93b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Indus water treaty was signed between _____?', '{"A":"India and Pakistan","B":"Bangladesh and India","C":"UAE and India","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indus Waters Treaty, signed on September 19, 1960, between India and Pakistan and brokered by the World Bank.It allocates the Western Rivers (Indus, Jhelum, Chenab) to Pakistan and the Eastern Rivers (Ravi, Beas, Sutlej) to India.It was signed in Karachi by Pakistan President Ayub Khan, Indian Prime Minister Jawaharlal Nehru, and Mr. W.A.B. Illif. The Treaty became effective on April 1, 1960.', 0, 0, 0, 1790967399881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_161640ab12514bf4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Tarbela dam is situated in?', '{"A":"KPK","B":"AJK","C":"Gilgit Baltistan","D":"FATA","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tarbela Dam is an earth-filled dam along the Indus River in swabi Khyber Pakhtunkhwa province. Tarbela Dam is the largest earth-filled dam in the world, and also the largest dam by structural volume Tarbela Dam Construction began in 1968 and Opening date 1976', 0, 0, 0, 1790967399881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5b83771402e0b338', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which Dam was the first build in Pakistan?', '{"A":"Tarbella","B":"Mangla","C":"Warsak","D":"None"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Warsak Dam is the oldest dam of Pakistan.Warsak dam is situated on river Kabul.Warsak Dam Construction began in 1949.Warsak Dam Opening date 1960.=====Others dams infoThe other was the Tarbela dam on the river Indus.Mangla was the first of 2 dams.The Mangla Dam is situated on the Jhelum River in the Mirpur District of AJK,It is the seventh-largest dam in the world.Construction began in 1961 Opening date 1965The Mangla Dam components include 5 tunnels and a power station.', 0, 0, 0, 1790967399881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_edb08e8c1ac19c29', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the oldest city of Pakistan ?', '{"A":"Lahore","B":"Mirpur","C":"Hunza","D":"Peshawar"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The most ancient city of South Asia is PeshawarPeshawar is the capital of the Pakistani province of Khyber Pakhtunkhwa. It is the sixth-largest city in Pakistan, largest Pashtun-majority city.Peshawar''s recorded history dates back to at least 539 BCE, making it the oldest city in Pakistan and one of the oldest cities in South Asia.', 0, 0, 0, 1790967399881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_674d4fec7a185ba5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Everest is the world''s highest mountain, what is the name of these second highest?', '{"A":"Tirich Mir","B":"Nanga Parbat","C":"K2","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation K-2 is Also Known As Godwin Austin''K'' standing for Karakoram.Mount K2 is the second-highest mountain on Earth. after the world''s highest peak Mount Everest.Mount K2 is part of the Karakorum Range located on the border of Pakistan and China.K2 height 8,611 meters******ND1-1-2023', 0, 0, 0, 1790967399881) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_64981169ce74e854', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'India constructed the Kishanganga Dam on which river?', '{"A":"Indus","B":"Sutlej","C":"Jhelum","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Kishanganga dam diverts water from the Kishanganga River to a power plant in the Jhelum River basinThe Kishanganga Hydroelectric Project is a run-of-the-river hydroelectric scheme in Jammu and Kashmir, India. The Kishanganga dam Opened: May 19, 2018Installed capacity: 330 MWThe Kishanganga dam Height: 37 mOwner: NHPCNA21-8-2023', 0, 0, 0, 1790967399897) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a02cd1cd5cd3d88a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the first city of Pakistan to receive artificial rain?', '{"A":"Karachi","B":"Quetta","C":"Lahore","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Punjab government on 16 December 2023 conducted first-ever successful experiment of artificial rain in Lahore.Collaboration: United Arab Emirates (UAE).Date of artificial rain: 16 December 2023 ****', 0, 0, 0, 1790967399897) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3f89ebba7224c80f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Pakistan and China decided which city as an industrial hub for joint venture?', '{"A":"Faisalabad / Gwadar","B":"Karachi","C":"Sialkot","D":"Islamabad"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation China and Pakistan broke ground on the Allama Iqbal Industrial City (AIIC) in Faisalabad on January 3, 2020The AIIC is a Special Economic Zone (SEZ) that is being developed as part of the China-Pakistan Economic Corridor (CPEC)', 0, 0, 0, 1790967399897) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7a14cbd83f974102', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The current motto of Punjab Police is _______?', '{"A":"Stand With People","B":"To Serve and Protect","C":"Our Punjab Always","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The motto of the Punjab Police in Pakistan is "To Serve and Protect Our Punjab Always Stand With People". The Punjab Police was formed on March 22, 1861.It has 350,000 employees.The Punjab Police has several mobile apps, including: Crime Prevention App, Personnel Mobile App, Tourist Facilitation App, and Zindagi App.', 0, 0, 0, 1790967399897) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_953d3c78c295223e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Gilgit Baltistan is a _____?', '{"A":"Province","B":"Autonomous Region","C":"Administrative territory of Pakistan","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gilgit is a city of: Gilgit-Baltistan PakistanGilgit Baltistan is located on the North side of PakistanGilgit-Baltistan, formerly known as the Northern Areas, is a region administered by Pakistan as an administrative territory.Gilgit-Baltistan was Established on 1 November 1948Capital of Gilgit-Baltistan is GilgitLargest city of Gilgit-Baltistan is Skarduagm19.3.23ND19-3-2023', 0, 0, 0, 1790967399897) ON CONFLICT(id) DO NOTHING;
