INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_57632ad87e0b5a4c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Mohmand dam is proposed to be constructed on _______ River?', '{"A":"Swat River","B":"Ravi River","C":"Indus River","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mohmand DamInaugurated by: Prime Minister Imran Khan on May 2, 2019Expected Completion: November 2024Type: Multi-purpose concrete-faced rock-filled damLocation: Swat River, Mohmand District, Khyber Pakhtunkhwa, PakistanConstruction Cost: ₨340 billion (US$1.2 billion)', 0, 0, 0, 1790967400057) ON CONFLICT(id) DO NOTHING;
