INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3c200e6a1b0f27dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The most important _____ area of Pakistan in the Indus valley.', '{"A":"Picnic","B":"Beautiful","C":"Agriculture","D":"Hilly"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indus Valley is the most important agriculture area of Pakistan.It has fertile soil and access to river water, making it ideal for farming.', 0, 0, 0, 1790967400088) ON CONFLICT(id) DO NOTHING;
