INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5fb555d182659676', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'First Educational Conference held in which city of Pakistan?', '{"A":"Karachi","B":"Lahore","C":"Islamabad","D":"None of them"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Educational Conference in Pakistan was held in Karachi.The conference was held from 27th November 1947 to 1st December 1947,Quaid-e-Azam Muhammad Ali Jinnah headed this conference.He provided the basic guidelines for future education development.', 0, 0, 0, 1790967400088) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_73a2c6560a0fce8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Desert of Thar lies in the province of ______?', '{"A":"Balochistan","B":"Punjab","C":"KPK","D":"Sindh"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation About Thar Desert15% located in Pakistan85% located in IndiaAlso called Friendly DesertLocated near Badin, Sindh Famous for: Sand Coal also found in Thar also known as Great Indian Desert7th largest desert on the planet.3rd largest in Asia.Area: 77,000 Miles****************', 0, 0, 0, 1790967400088) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_81704015d1110ee8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Dasht River is located in the province of ______?', '{"A":"Baluchistan","B":"Punjab","C":"Sindh","D":"KPK"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There are many rivers in Balochistan but 7 are the mainThe important rivers in Balochistan are:ZhobNariBolanPishinLoraMulaHubPoraliHingol is the largest river in the BalochistanRakshanDasht.', 0, 0, 0, 1790967400088) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_180277118d94f8a2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Indus Valley Civilization is also known as _______?', '{"A":"Harrapan Civilization","B":"Kot Diji Civilization","C":"Taxila Civilization","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indus River Valley Civilization, 3300-1300 BCE.It is also known as the Harappan Civilization.It extended from modern-day northeast Afghanistan to Pakistan and northwest India.', 0, 0, 0, 1790967400088) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_21d03b44ddb4a5ae', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Ganda Singh Wala Border was connected ____?', '{"A":"Kasur and Ferozpur","B":"Lahore and Amritsar","C":"Sialkot and Ferozpur","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Pakistani village of Ganda Singh Wala served as the main border crossing between India and Pakistan in the 1960s & 70s. It was closed to trade & transit in 1986 and the main border crossing was shifted north to Wagah.******RY 15-01-2023', 0, 0, 0, 1790967400088) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3db2688ca1c0d7ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the highest peak of salt range?', '{"A":"Nanga parbat","B":"K-2","C":"Soan Sakaser","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The highest peak of salt range is Soan Sakaser.The Salt Range is a mountain range in the north of the Punjab province of Pakistan.The range extends along the south of the Potohar Plateau and the north of the Jhelum River.The salt range is situated between rivers Soan and River JhelumSakesar (Khushab District) is the highest mountain in the salt region.675 meters is the average height of the salt range.The Upper Indus plain area is located in the South of the Salt Range and east of Sulemania.******', 0, 0, 0, 1790967400120) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a553dfb846f3bd3a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the highest peak of the Koh-e-Sufaid Range?', '{"A":"Zardak","B":"Tirich Mir","C":"Nanga Parbat","D":"Sikeram","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Koh e Sufaid, is the mountain range located exactly on the Pak-Afghan Border At Parachinar, Kurram Agency, FATA, PAKISTANSikeram, the highest peak in Koh-e-Safaid Ranges rises to 4,760 m.', 0, 0, 0, 1790967400120) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3c70bf17b1d4d9b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Karez is the irrigation system of which province of Pakistan?', '{"A":"Punjab","B":"Sindh","C":"KPK","D":"Balochistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Karez is the irrigation system of Balochistan.This ancient method involves underground channels that transport water from aquifers to the surface.It providing a sustainable water supply in arid regions.', 0, 0, 0, 1790967400120) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1f16cd28912e03f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which of the following is the cold desert?', '{"A":"Kharan","B":"Thal","C":"Thar","D":"Katpana"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Kapana is a cold desert.Katpana is 2226 meters above altitude. Katpana is the 16th largest desert of the world.Katpana is in Skardu.', 0, 0, 0, 1790967400120) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_742029b988ac0d70', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the youngest mountain range on the earth?', '{"A":"Karakoram","B":"Hindu kush","C":"Alps","D":"Himalayas"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Himalayas are the youngest mountain range on Earth.It is a new fold mountain formed by the collision of two (Indian and Eurasian tectonic plates) tectonic plates.They began rising around 40 to 50 million years ago.', 0, 0, 0, 1790967400120) ON CONFLICT(id) DO NOTHING;
