INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_58b328b1155e4db4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Ajrak is the cultural dress of which province?', '{"A":"Punjab","B":"KPK","C":"Sindh","D":"Balochistan"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ajrak is a traditional block-printed shawl and symbol of Sindhi culture.It is commonly worn during cultural events and gifted as a sign of respect in Sindh province.There are 22 processes in Ajrak printing and is very tedious and time consuming.', 0, 0, 0, 1790967400120) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_76d079c14be080ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which province of Pakistan has no Desert?', '{"A":"Punjab","B":"Sindh","C":"KPK","D":"Balochistan"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khyber Pakhtunkhwa is a province in Pakistan with no desert. Total deserts in Pakistan: 1. Thar Desert (in Sindh) 2. Kharan Desert (in Balochistan) 3. Katpana Desert in Skardu (Gilgit Baltistan) 4. Thal Desert in Bhakkar (Punjab) 5. Cholistan in Bahawalpur (Punjab)Last updated question by NA on 07 May 2026', 0, 0, 0, 1790967400154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_47a738bf34febab5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Gomal Zam Dam was inaugurated in 2013 at ______?', '{"A":"North Waziristan","B":"South Waziristan","C":"Skardu","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gomal Zam Dam is a gravity dam in South Waziristan Tribal District of Khyber Pakhtunkhwa.The dam impounds the Gomal River.Gomal Zam Dam was inaugurated in 2013.', 0, 0, 0, 1790967400154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_96fa353ccbdea6af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The famous Lake “Hamoon Mashkel” is present in Baluchistan Plateau. It is the lake of _____?', '{"A":"Fresh water","B":"Salt water","C":"Hard water","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lake Hamoon Mashkel is a saltwater lake.It is located in the Washuk District of Balochistan, Pakistan.It is part of the Balochistan Plateau.It is known for its saline water.', 0, 0, 0, 1790967400154) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6c3e85d69bdef1ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'In which desert is the Derawar fort is located?', '{"A":"Thal","B":"Cholistan","C":"Thar","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The height of walls of Derawar Fort is 40 meters.It is located in Cholistan Desert, Ahmadpur East Tehsil, Bahawalpur.The walls have a perimeter of 1500 metres and stand up to 30 metres high.', 0, 0, 0, 1790967400154) ON CONFLICT(id) DO NOTHING;
