INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b32635fcaf45594d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'All India Muslim students federation was founded in which city :', '{"A":"Calcutta","B":"Karachi","C":"Lahore","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The All-India Muslim Students Federation (AIMSF) was founded in Calcutta, India on September 1, 1937. Headquarters located in Chennai.Mother party is the Indian Union Muslim League.The AIMSF was a student union that was affiliated with the All-India Muslim League.It was organized by Fatima Jinnah under the patronage of Muhammad Ali Jinnah in 1941.', 0, 0, 0, 1790967400394) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9c27c61e001548ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Kunar river is also called ___ river in Pakistan.', '{"A":"Chitral","B":"Swat","C":"Kunhar","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Kūnaṛ River, also known in its upper reaches as the Mastuj, Chitral, or Kama River, The Kūnaṛ River is located in Afghanistan and the KPKThe town lies along the Kunar River (also known as the Chitral River)Kunar River gives its name to Kunar Province.Length:480 km (300 mi)ND27-9-2023', 0, 0, 0, 1790967400394) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e30c90abca02ee1d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which city is considering the engineering Hub of Pakistan?', '{"A":"Lahore","B":"Gujranwala","C":"Sialkot","D":"Karachi"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lahore is considered the engineering hub of Pakistan due to its high concentration of engineering universities, colleges, and industries.The city is home to several top-ranked engineering universities, including the University of Engineering and Technology (UET) Lahore.Lahore is also a major industrial center, with a large number of textile, automotive, and manufacturing industries, which provides a strong link between industry and academia.', 0, 0, 0, 1790967400394) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_60134f0bee4eb975', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Wall of knowledge is located in which city?', '{"A":"Islamabad","B":"karachi","C":"Lahore","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Wall of Knowledge, also known as the "Walls of Knowledge" or "Knowledge Park".It is a public art installation located in Lahore, Pakistan.It is a series of walls displaying inscriptions of famous quotes, poems, and excerpts from notable literary and intellectual figures, including Allama Iqbal, Bulleh Shah, and Faiz Ahmad Faiz, among others.', 0, 0, 0, 1790967400394) ON CONFLICT(id) DO NOTHING;
