INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_98ea5899ddf72a84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Chaj Doab lies between which two river?', '{"A":"Chenab and Indus","B":"Chenab and Jhelum","C":"Indus and Ravi","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Five Important Doabs of Pakistan Sindh Sagar Doab is b/w: Indus & Jhelum rivers Jech Doab is b/w: Jhelum & Chenab rivers Bari Doab is b/w: Ravi & Sutlej riversRachna Doab is b/w: Ravi & Chenab rivers Bias Doab is b/w: Bias & Sutlej rivers Doab Chaj is b/w: Chenab and Jhelum.', 0, 0, 0, 1790967400456) ON CONFLICT(id) DO NOTHING;
