INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_41c276807371f318', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Heer Ranjha is a famous folk story of Punjab. What was the real name of Heer?', '{"A":"Izzat Bibi","B":"Sehti","C":"Nadra Bibi","D":"Bag Bhari"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Heer Ranjha is a famous folk tale from Punjab, and according to the story, Heer''s real name was Izzat Bibi.Heer Ranjha was written by Waris Shah.Heer Ranjha was written in 1766.It tells the story of the love of Heer Sial and her lover Dheedo Ranjha.', 0, 0, 0, 1790967400490) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7c628b7b34a4c1c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'A glacier ______?', '{"A":"Is a river of ice sliding down a mountain carrying along material","B":"Is a vast sheet of ice","C":"Both","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A glacier is a river of ice sliding down a mountain carrying along with morainic material. Glaciers usually deform and get down their weight. On earth, 99% of glacial ice is there in vast ice sheets in the polar regions and the mountain ranges.', 0, 0, 0, 1790967400490) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_26b7df417be72e4f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'In Punjab Radcliffe gave an unjust award, including the following tehsils on the Indian side?', '{"A":"Sheikhupura, Kasur","B":"Gurdaspur, Pathankot","C":"Feroxpur, Hoshiarpur","D":"Shakargarh, Pakpattan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Punjab Boundary Commission Award (known as the Radcliffe. Award)In addition to Gurdaspur''s Muslim majority tehsils, Radcliffe also gave the Muslim majority tehsils of:Ajnala (Amritsar District), Zira, Firozpur (in Firozpur District), Nakodar Jullander (in Jullander District) to India instead of PakistanND26-2-2023', 0, 0, 0, 1790967400490) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_888b34fd59e19b92', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The Second largest city in Pakistan is _____?', '{"A":"Lahore","B":"Karachi","C":"Faisalabad","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790967400490) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_96d65420ee8c72ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Pakistan protested against construction of Baglihar Dam because _____?', '{"A":"It was violation of Indus Treaty Water","B":"It was violation of LOC","C":"It was violation of Simla Agreement","D":"It was violation of the UN Charter"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan protested against the construction of the Baghlihar Dam by India, claiming it violated the Indus Waters Treaty.This treaty regulates the use of river waters in the Indus Basin, and Pakistan argued that the dam would adversely affect its water supply.', 0, 0, 0, 1790967400490) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d64906ab8b168996', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Sajji is a famous dish of which province of Pakistan?', '{"A":"Kpk","B":"Balochistan","C":"Punjab","D":"Sindh"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Balochistan is known for the famous dish Sajji.It is traditionally made with whole lamb or chicken.It marinated and slow-cooked over an open fire.', 0, 0, 0, 1790967400490) ON CONFLICT(id) DO NOTHING;
