INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_083fdd80b9354b4f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which dam in Pakistan built with the help of world bank?', '{"A":"Tarbela Dam","B":"Warsak Dam","C":"Mangla Dam","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Tarbela Dam in Pakistan was built with the assistance of the World Bank.Tarbela Dam is one of the largest earth-filled dams in the world.Tarbela Dam is an earth-filled dam along the Indus River in KPK.Installed capacity: 4,888 MWHeight: 143 mCompleted: 1976', 0, 0, 0, 1790967400520) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_450a0274a74e4ee1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Karakorum highway in Pakistan starts from ______?', '{"A":"Islamabad","B":"Taxila","C":"Hassan Abdal","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Karakoram Highway (KKH) is also known as the Friendship Highway in China and N-35 in Pakistan.It was built by the governments of Pakistan and China and completed in 1979.Starting from Hassan Abdal, it spans 1,300 (810 miles) km in Pakistan.The Silk Route is also referred to as the Karakoram Highway.The Karakoram Range, located between China and Pakistan.It is traversed by the Karakoram Highway.It connects the two countries via the Khunjerab Pass.', 0, 0, 0, 1790967400520) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_219af280cb7a8474', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'How many deserts are in Punjab Province?', '{"A":"1","B":"2","C":"3","D":"4"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Punjab Province has two deserts: The Thal Desert (Bhakkar) and the Cholistan (Bahawalpur) Desert.Sindh has one desert: The Thar Desert.Balochistan has one desert: The Kharan Desert.KPK has no deserts.Gilgit-Baltistan has one desert: Katpana (Skardu) Desert.', 0, 0, 0, 1790967400562) ON CONFLICT(id) DO NOTHING;
