INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_23996853a806b8b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The world largest dam made of mud is ______?', '{"A":"Mangla","B":"Warsak","C":"Tarbela","D":"Barotha"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Tarbela Dam is located in Pakistan. Tarbela Dam is the world''s largest fill-type dam. It is built over the River Indus near the small town of Tarbela in the Haripur District of the country.', 0, 0, 0, 1790967400650) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_18181dd6184f598f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Mirani Dam is located on which river?', '{"A":"Bolan","B":"Jhelum","C":"Dashat","D":"Hub","E":"None of the above"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mirani Dam is located in the Dashat river***Mirani Dam was completed in July 2006 Began impounding the Dasht River in August 2006.The feasibility report of the Mirani dam project was first completed in 1956. Mirani Dam was commissioned by WAPDA in 2001 to provide water for Gwadar city. The Length of Mirani Dam is 3,350 ft (1,020 m)Mirani Dam is in Kech District in the Balochistan province of Pakistan.', 0, 0, 0, 1790967400650) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5aea5136a57f31fd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Darawat Dam is in--------?', '{"A":"Tando Adam Khan","B":"Tando Allah Yar","C":"Thano Bola Khan","D":"Sukkur","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Darawat dam is located in Thano Bola Khan-Jamshoro District Sindh***Darawat Dam across the Nai Baran River near the Village of Jhangri in the Jamshoro district of SindhConstruction of the dam started in March 2010 completion was inaugurated by the Former President of Pakistan Asif Ali Zardari on 9 March 2013. the estimated cost was PKR 9.3 BillionOpened: August 2014Height: 46 m***Thano Bula Khan is a town and Taluka headquarter in Jamshoro District, Sindh, Pakistan. **', 0, 0, 0, 1790967400650) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4ae0dc1aa4d161ba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which is the highest peak of Sindh?', '{"A":"Skesar","B":"Sulaiman","C":"Zardak","D":"Loi Naikan","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The highest peak of the Sindh mountains is Zardak Peak at 7,430 ft (2,260 m).', 0, 0, 0, 1790967400650) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9d8f855ed63ccc30', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which mountain range separates Pakistan and Afghanistan?', '{"A":"Pamirs Range","B":"Karakoram range","C":"Kirthar Range","D":"Hindu Kush Range","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hindu Kush is an 800-kilometre-long (500 mi) mountain range that stretches through Afghanistan Hindu Kush Range Highest point Peak Tirich Mir (Pakistan).', 0, 0, 0, 1790967400680) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4f37e8ad2ef1aba9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which chain of hills is located in Sindh', '{"A":"Kirthar Mountain Range","B":"Koh-e-Safaid","C":"Swalikh Range","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Kirthar Mountains are a mountain range that marks the boundary between the Pakistani provinces of Balochistan and SindhKirthar Mountains, a mountainous region in southern Pakistan.It stretches about 300 km south from the Murat River in central-eastern Balochistan to Cape Muari (Monze), west of Karachi in the Arabian Sea. The mountains form the boundary between the lower Indus River basin (east) The highest peak of the mountains is Zardak Peak at 7,430 ft (2,260 m).', 0, 0, 0, 1790967400680) ON CONFLICT(id) DO NOTHING;
