INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_adc5a6beec6d32f8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Faiz Mahal is located in which district?', '{"A":"Bahawalpur","B":"Rajanpur","C":"Thatta","D":"Khairpur","E":"Taxila"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Faiz Mahal is located in Khairpur district of Sindh.Built by: Mir Sohrab KhanBuilt in: 1798Aim: as the principal building serving as the sovereign’s court for the royal palace complex of Talpur monarchs of the Khairpur dynasty.', 0, 0, 0, 1790967400709) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0e88e67823070329', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Which city is called the thermal pole of Pakistan?', '{"A":"Turbat","B":"Sui","C":"Kashmore","D":"Jacobabad","E":"Badin"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jacobabad is called the thermal pole of Pakistan.Jacobabad is one of the biggest cities of Pakistan.Jacobabad is located in Sindh.', 0, 0, 0, 1790967400709) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f3a4a2e4915e3bd8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'CPEC circumvent which sea?', '{"A":"Arabian Sea","B":"Baltic Sea","C":"Caspian Sea","D":"Red Sea"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The derelict port of Gwadar, located on the Arabian Sea at the mouth of the Strait of Hormuz, emerged as CPEC’s jewel.China Pakistan Economic Corridor is a framework for regional connectivity. CPEC not only benefits China and Pakistan, but also has a positive impact on Iran, Afghanistan, the Central Asian Republic, and the region.CEPAC Established in 22 May 2013 (9 years ago)Budget China Development BankAsian Infrastructure Investment BankSilk Road Fund', 0, 0, 0, 1790967400709) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0f65bfba606989fc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'If population of Gilgit and Azad Kashmir is also taken in account then by population Pakistan is world''s __________ largest country.', '{"A":"Seventh","B":"Fifth","C":"Eighth","D":"Sixth","E":"Fourth"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan is the world''s fifth-most populous countryThe population density in Pakistan is 287 per Km2 (742 people per mi2).Pakistan world''s second-largest Muslim population.the top 10 most populous countries in the worldChinaIndiathe United StatesIndonesiaPakistanBrazilNigeriaBangladeshRussiaand Mexico', 0, 0, 0, 1790967400709) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b2ceb60e06b11db1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Blind Dolphins are found in the river of:', '{"A":"Ganges River","B":"Nile River","C":"Yellow River","D":"Yangtze River","E":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Blind Dolphins are found in Indus river in Pakistan and Ganges river in India and Bangladesh.***********The Indus River dolphin, also known as the “bhulan,” is one of the world''s most endangered cetaceans. It is endemic to the Indus River Basin of Pakistan and northwestern India. Blind Dolphins are found in the lower parts of the Indus River in Pakistan and in River Beas, a tributary of the Indus River in Punjab, India.ND20-6-2023', 0, 0, 0, 1790967400709) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ef03609ce3388d49', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'Peshawar district and major parts of Mardan consist of__?', '{"A":"Hilly areas","B":"Plain areas","C":"Plateaus","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Peshawar district and major parts of Mardan consist of plain areas.Peshawar and Mardan are located in KPK.Peshawar is the largest city and capital of KPK.Plain areas means میدانی علاقے', 0, 0, 0, 1790967400709) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_607af6a11431dcc5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_geo', 'The desert in the Bahawalpur district in Punjab is known as ________ desert.', '{"A":"Thar","B":"Thal","C":"Cholistan","D":"Katpana","E":"Kharan"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cholistan Desert is located 30 kilometers from Bahawalpur, Punjab.Locally this desert is known as Rohi.Jeep Rally is also held in Cholistan Desert. Cholistan lies on the southern part of the Punjab. *******', 0, 0, 0, 1790967400739) ON CONFLICT(id) DO NOTHING;
