INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_89c403be6c43e044', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'GT Road was constructed by _____?', '{"A":"Feroz Tughluk","B":"Tipu Sultan","C":"Sher Shah Suri","D":"Ameer Kror"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation GT Road: Grand Trunk RoadConstructed/Developed by: Sher Shah SuriPurpose: Connected major cities and improved trade and travel.Original Name: Known as Sadak-e-Azam or Badshahi Sarak.Length: 3,655 km (2,271 mi)East end: Teknaf, BangladeshWest end: Kabul, Afghanistan', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8e062f55e0187b4d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was the Indian National Congress (INC) formed?', '{"A":"December 28, 1888","B":"December 28, 1885","C":"December 28, 1886","D":"December 28, 1880"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indian National Congress (INC) was formed on 28 December 1885 in Bombay (now Mumbai), British India.The first session was held at Gokuldas Tejpal Sanskrit College.Headquarters: New Delhi, IndiaFounder: Allan Octavian Hume (with support from Indian leaders)First President: Womesh Chunder BonnerjeePurpose: To represent Indian political interests and later lead the Indian independence movement.Last verified on 11-07-2026', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a54fc90ad122b47b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Simla agreement was signed between Indira Gandhi and ________?', '{"A":"Ayoub Khan","B":"Zulfiqar Ali Bhutto","C":"Yahiya Khan","D":"General Zia"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Simla Agreement was signed between Zulfikar Ali Bhutto and Indira Gandhi.It was signed on 2 July 1972.It took place in Shimla, India.It aimed to resolve issues after the 1971 war.Both countries agreed to settle disputes through bilateral talks.Last verified on 29-04-2026', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6ef8d95c7c194659', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who Presented Lahore Resolution (Pakistan Resolution) on 23rd March, 1940 at Minto Park?', '{"A":"Allama Iqbal","B":"A.K Fazlul-Haq","C":"Quaid-e-Azam Muhammad Ali Jinnah","D":"Liaquat Ali Khan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Lahore Resolution was passed on 23 March 1940 at Minto Park, Lahore.Presented by A. K. Fazlul HuqPrepared text by Muhammad Zafarullah KhanIt demanded separate states for Muslims of the subcontinent.It is also called the Pakistan Resolution.Additional information:Key Participants (by region)Punjab → Zafar Ali KhanSindh → Sir Abdullah HaroonBengal → A.K. Fazlul HuqKPK → Sardar Aurangzeb KhanUnited Provinces → Khalid ZamanLast verified 04-05-2026', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7bc909ae5f97e712', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The main demand of simla Muslim Deputation accepted in Minto Morley Reforms of 1906 was about?', '{"A":"Separate electorates","B":"Separate muslim state","C":"Separation of Sindh from Bombay","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Main Demand: Separate electorates for MuslimsPlace: Simla (Shimla)Date: 1 October 1906Leader: Sir Aga Khan IIIMet: Lord MintoThe Simla Deputation consisted of 35 members.Last verified on 08-08-2026', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_025b95ac928d7895', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was the Lucknow Pact made between the Muslim League and Congress?', '{"A":"November 1915","B":"December 1917","C":"November 1914","D":"December 1916"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lucknow Pact (December 1916) was an agreement between:Indian National Congress – headed by Bal Gangadhar TilakAll-India Muslim League – led by Muhammad Ali JinnahAdditional information:Congress adopted the pact at Lucknow session on 29 December 1916.Muslim League approved it on 31 December 1916.Last verified on 19-01-2026', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ac39b4d60a954c49', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When did the Simla Deputation took place?', '{"A":"1st October 1906","B":"14th August 1905","C":"30th December 1907","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Simla Deputation took place on October 1, 1906Location: Viceregal Lodge, Simla (now Shimla, India)Leader: Sir Aga Khan IIIParticipants: 35 prominent Muslim leadersMet With: Lord Minto, the Viceroy of India.Main Demand: Separate electorates for MuslimsAdditional informationThe Simla Agreement was signed on July 2, 1972.Last updated by NS on 5-09-2026', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ae8925c0408dfc69', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'What was the reaction of Congress in response to the failure of Cripps Plan?', '{"A":"Passed a resolution for freedom","B":"Quit India resolution","C":"Agitation","D":"Accepted Crips Plans"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After the failure of the Cripps Mission, Congress reacted strongly.It launched the Quit India Movement in 1942.This was led by Mahatma Gandhi.The demand was for immediate British withdrawal from India.It became a major mass movement against British rule.Last verified on 29-04-2026', 0, 0, 0, 1790967400885) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9fb89c57bbe2ccdb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was All India Muslim League founded?', '{"A":"30 December 1906","B":"30 November 1906","C":"30 August 1947","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The All India Muslim League was founded on 30 December 1906.Location: Dhaka (Dacca), BangladeshFounder: Nawab Khwaja SalimullahFirst President: Sir Agha KhanHeadquarters: LucknowThe party was dissolved on 14 August 1947.When the Muslim League ended in 1947, it split into three parties:Muslim League in PakistanAwami League in BangladeshIndian Union Muslim League in IndiaLast verified on 10-07-2026', 0, 0, 0, 1790967400918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_588beddb14b94d56', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was the Lahore Resolution (Pakistan Resolution) passed?', '{"A":"14 March 1945","B":"23 March 1940","C":"12 March 1948","D":"28 March 1947"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Lahore Resolution was passed on 23 March 1940 at Minto Park, Lahore.It demanded separate states for Muslims of the subcontinent.It is also called the Pakistan Resolution.Additional information:Presented by A. K. Fazlul HuqPrepared text by Muhammad Zafarullah KhanKey Participants (by region)Punjab → Zafar Ali KhanSindh → Sir Abdullah HaroonBengal → A.K. Fazlul HuqKPK → Sardar Aurangzeb KhanUnited Provinces → Khalid ZamanLast verified on 04-05-2026', 0, 0, 0, 1790967400918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b4b6a648eca778eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Lahore Resolution was passed in the ________ annual session of All India Muslim League.', '{"A":"27th","B":"21th","C":"37th","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lahore Resolution was passed in the 27th annual session of the All India Muslim League.It was presented by A. K. Fazlul Huq.Adopted by the All-India Muslim League on the occasion of its three-day general session in Lahore on 22–24 March 1940.The session was held at Minto Park, Lahore.Muhammad Ali Jinnah presided over the historic session.Last verified on 01-09-2026', 0, 0, 0, 1790967400918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ce390b8f05cdb657', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The period of 1947 to 1953 of Pakistan is known as era of _______?', '{"A":"Neutrality","B":"Alliances","C":"Bilateralism","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1947–1953: NeutralityAdditional information:1954–1962: Alliances1963–1978: Bilateralism1979–1989: Alliances1990–present: Post-Cold WarLast verified on 01-09-2026', 0, 0, 0, 1790967400918) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c5e5230f0948bd1f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The first war fought between India and Pakistan after Partition (1947–48) was fought over which issue?', '{"A":"Kashmir","B":"Ladakh","C":"Sir Creek","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first war fought between India and Pakistan after Partition (1947–48) was fought over the Kashmir issue.The First Indo-Pakistani War began in 1947 and continued until 1948.The main dispute was over the princely state of Jammu and Kashmir.The conflict ended with a UN-mediated ceasefire that took effect on 1 January 1949.Last verified on 10-08-2026', 0, 0, 0, 1790967400919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d3b466395761b171', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'What was the number of Sugar mills in Pakistan in 1947?', '{"A":"2","B":"6","C":"9","D":"15"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sugar Mills in 1947: 2Current Sugar Mills (Approx.): About 88 according to Pakistan Sugar Mills Association (PSMA)Punjab: About 45 millsSindh: About 38 millsBalochistan: About 5 millsMain Raw Material: SugarcaneLast verified on 26-07-2026', 0, 0, 0, 1790967400919) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cb774f1317c4e8ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Quaid''s daughter Dina Wadia died in which city?', '{"A":"Karachi","B":"Lahore","C":"New York City","D":"London"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dina Wadia, the daughter of Quaid-e-Azam Muhammad Ali Jinnah,Date of Death: November 2, 2017, from pneumonia Location: New York City, USAAge: 98 years oldBorn: 15 August 1919, London, EnglandParents Muhammad Ali Jinnah (father)Rattanbai Petit Jinnah (mother)****Last updated by NS on 01 MAY 2026', 0, 0, 0, 1790967400919) ON CONFLICT(id) DO NOTHING;
