INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b86ce0cb67773fa8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'First head of state to visit Pakistan in 1947 was _______?', '{"A":"Ameer of Saudi Arabia","B":"Ameer of Kuwait","C":"Ameer of Iran","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iran was the first country to recognize Pakistan after independence The first head of state to visit Pak: in 1947 was Ameer of Kuwait Ahmad Al-Jaber Al-Sabah. Founder of Kuwait Public Security Force The first president to visit was of Indonesia. The first opposition party of Pak: Jinnah Awami league it was founded by Abdul Hameed Bhashwani in 1950.', 0, 0, 0, 1790967401294) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_71ddcecc7376978d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'What is Father name of Allama Iqbal?', '{"A":"Noor Ali","B":"Sheikh Noor Muhammad","C":"Muhammad Noor","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allama Iqbal Father was Sheikh Noor MuhammadHe was a tailorAllama Iqbal Mother name is Imam Bibi Additional InformationAllama Iqbal Born: November 9, 1877 (Sialkot)He was Died: 21 April 1938His Burial: Badshahi Mosque in LahoreThey Received PhD: in GermanyHis Title: Poet of the EastPunjab was a political area of Allama IqbalHe was elected to the Punjab Legislative Council in 1927', 0, 0, 0, 1790967401294) ON CONFLICT(id) DO NOTHING;
