INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5cc0fe47b8f3894e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Quaid-e-Azam left the Indian National Congress in ______?', '{"A":"1906","B":"1913","C":"1920","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jinnah joined the Indian National Congress in 1906.Left congress 1920.Join All India Muslim League in 1913.Remain a member of both parties for 7 years.', 0, 0, 0, 1790967401351) ON CONFLICT(id) DO NOTHING;
