INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3ab9ef7ac6d2d69c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When Quaid-e-Azam addressed the first Constituent Assembly of Pakistan?', '{"A":"1 September 1947","B":"11 August 1947","C":"14 October 1947","D":"29 August 1947"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid e Azam M A Jinnah, the first president of Constituent Assembly of Pakistan addressed the first constituent Assembly on 11 August 1947.This speech is also known as Eleventh August Speech. Quaid e Azam M A Jinnah is also the founder of Pakistan. ***', 0, 0, 0, 1790967401410) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_24b8486fb4e6b0ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Mohtarma Fatima Jinnah had which of the following Occupation (Profession)?', '{"A":"Political leader","B":"Skin specialist","C":"Lecturer","D":"Dentist"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fatima Jinnah: younger sister of Quaid-e-Azam Muhammad Ali JinnahFatima Jinnah born: 30th July 1893Fatima Jinnah is referred as: Madr-e-Millat (Mother of Nation)Fatima Jinnah died: 9 July 1967Fatima Jinnah died at age: 71Fatima Jinnah died: KarachiFatima Jinnah profession: Dental Surgeon', 0, 0, 0, 1790967401410) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8c5b70bbdcc37877', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'After the defeat of Turkey, the Khilafat system was in danger in India. A Khilafat Committee was set up for the help of Khilafat. Who was appointed the 1st Secretary of All India Khilafat Committee?', '{"A":"Maulana Muhammad Ali Johar","B":"Maulana Shaukat Ali","C":"Seth Jan Muhammad Chottani","D":"Nawab Liaqat Ali Khan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1919, the Khilafat Committee was established to launch the Khilafat Movement. Maulana Shaukat Ali was decided as the General Secretary of the Khilafat MovementMahatma Gandhi was elected as President (23rd November 1919)Khilafat Committee and the congress participated in the election under Act of 1919.The Muslims of the Sub continent launched the Khilafat Movement in the year 1919 until 1924', 0, 0, 0, 1790967401440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1d5758cab7b7c2d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Allama Iqbal received the title of Sir in?', '{"A":"1920","B":"1921","C":"1922","D":"1923"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allama Iqbal received the title of Sir in 1922 in Lahore.He was knighted by King George V for his contributions to literature.Note: According to SPSC, 1923 is the correct answer.', 0, 0, 0, 1790967401440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_73cc4e611b71f973', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The reaction of Indian National Congress and All India Muslim League towards the Cripps Mission proposals was _____?', '{"A":"Congress accepted while Muslim League rejected","B":"Muslim accepted while Congress rejected","C":"Both Rejected","D":"Both Accepted"}', 'C', NULL, 0, 0, 0, 1790967401440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a3402c4a914bf03c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Gandhi – Jinnah talks of 1944 failed due to ______?', '{"A":"Opposition by the Khaksars","B":"Red Shirts","C":"The Ahrar","D":"Two – Nation Theory"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jinnah Gandhi talks were made in 1944.Jinnah Gandhi talks were held in Bombay.Talk failed because Gandhi simply refused to accept the Lahore Resolution as interpreted by Jinnah.', 0, 0, 0, 1790967401440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_38b294472fc27fa7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Partition of India Plan was announced on?', '{"A":"3 June 1944","B":"3 June 1949","C":"3 June 1948","D":"3 June 1947"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 3 June 1947 Lord Mountbatten announced the partition plan.**The 3rd June 1947 Plan was also known as the Mountbatten Plan.The 3rd June Plan announced the partition of British India into 2 states:IndiaPakistanPunjab and Bengal were divided in the 3rd June Plan.The third June Plan was worked out by Lord Mountbatten.****', 0, 0, 0, 1790967401440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c5853a3a5621b5c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The Lahore session of Muslim League held in 1940 was presided over by_____?', '{"A":"Quaid-e-Azam","B":"Liaqat Ali Khan","C":"Khaliq uz Zaman","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Leader: Quaid-e-Azam Muhammad Ali JinnahLocation: Lahore, PunjabDates: March 22–24, 1940Core Idea: Proposed the Two-Nation Theory.Resolution Presenter: A. K. Fazlul Huq.Major Outcome: Adopted the Lahore Resolution.Additional information The All India Muslim League was founded on 30 December 1906.Location: Dhaka (Dacca), BangladeshFounder: Nawab Khwaja SalimullahLast updated 26-07-2026 by NA', 0, 0, 0, 1790967401440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fa76312c07a3b4e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Simla Deputation (October 1906) comprised how many Muslim leaders?', '{"A":"18","B":"35","C":"40","D":"50"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Simla Deputation of 1906 was made up of 35 Muslim leaders: DetailsWho led the deputation? Aga Khan IIIWhen did it take place? October 1, 1906Where did it take place? Viceregal Lodge in SimlaWho met with the deputation? Lord Minto, the Viceroy of the BritishWhat was the purpose? To demand separate electorates and secure Muslim interests', 0, 0, 0, 1790967401440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_344908766f71e9e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Khilafat Movement was launched in the subcontinent in ______?', '{"A":"1915","B":"1919","C":"1925","D":"1947"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The movement lasted from 1919 to 1924 ADEnded after the abolition of the Caliphate.It was a Religio-Political movement.It aimed to protect the Ottoman Caliphate after World War I.It was mainly led by the Ali Brothers.Major leaders were Maulana Muhammad Ali Jauhar and Shaukat Ali.Last question by NA on 26 April 2026', 0, 0, 0, 1790967401440) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_73fd986cb7ebd090', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Jalal ud Din Mohammad Akbar was born in ______?', '{"A":"Bengal","B":"Sindh","C":"Punjab","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jalal uddin Muhammad Akbar was a Mughal emperor.He was born in Umarkot (Sindh) in 1542.He became Emperor in 1556.He was died in 1605.', 0, 0, 0, 1790967401473) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_85472d1aa44459d0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The shortest tenure of Viceroy is _________?', '{"A":"Lord Mountbatten","B":"Harding","C":"Ripon","D":"Linlithgow"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lord Mountbatten had the shortest duration, from March 22 to August 15, 1947.He was the last viceroyLord Mountbatten through "The Indian Independence Act of 1947"This plan is known as the 3 June Plan or Mountbatten Plan.This plan was the last plan for independence.Additional informationLord Linlithgow was longest reign as Viceroy of India.Lord Canning was the first viceroy of British India.Warren Hastings was the first governor-general of india.', 0, 0, 0, 1790967401473) ON CONFLICT(id) DO NOTHING;
