INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d3d90104d3f163e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Muslim League was established on the 30th of December 1906. Which city was decided to be its headquarters?', '{"A":"Lucknow","B":"Aligarh","C":"Delhi","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Important Note: According to STS IBA Aligarh is right answer because the Muslim League''s headquarters were initially located in Aligarh from 1906 until 1910, then moved to Lucknow.Founded: 30 December 1906, DhakaFounder: Nawab Khwaja Salimullah1st President: Sir Aga Khan IIIInitial HQ: Aligarh (1906–1910)Later HQ: LucknowDissolved: 14 August 1947', 0, 0, 0, 1790967401473) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cf693e44b6bf7e6c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'In which year Muslim league was established in Balochistan?', '{"A":"1935","B":"1937","C":"1939","D":"1940"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1939 a local lawyer, Qazi Muhammad Isa, created the Balochistan Muslim League.In Pishin at a mosque meeting.', 0, 0, 0, 1790967401473) ON CONFLICT(id) DO NOTHING;
