INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_66e030231152de71', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was Quaid-e-Azam first appointed as Third Presidency Magistrate in Bombay?', '{"A":"1899","B":"1900","C":"1947","D":"1930"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1900, P. H. Dastoor, a Bombay presidency magistrate, left the post temporarily and Jinnah succeeded in getting the interim position.After his six-month appointment period, Jinnah was offered a permanent position on a 1,500 rupee per month salary. But he refuses', 0, 0, 0, 1790967401473) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e1dbbedad5146ed9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'In the absence of Quaid-e-Azam, who led the Muslims delegation in the third round table conference?', '{"A":"Liaqat Ali Khan","B":"Sir Agha Khan","C":"Syed Suliman Nadvi","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1932 third round table conference held***Sir Agha Khan led the mulim delegation. First round table conference: 19302nd round table conference: 19313rd round table conference:1932All round table conference held in London***The three Round Table Conferences of 1930–32 were a series of conferences to formulate the future constitution of India in the light of suggestions given by the Indian Leaders***Gandhi a leader does not attend the first round table conference AGM-24-12-2022', 0, 0, 0, 1790967401473) ON CONFLICT(id) DO NOTHING;
