INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e53f6f2b57b7dea7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who established the Muslim League in Balochistan on the instructions of Quaid-e-Azam in 1939?', '{"A":"Fazal Ahmed Ghazi","B":"Mir Jafar Khan Jamali","C":"Qazi Muhammad Isa","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Qazi Muhammad Isa established the Muslim League in Balochistan in 1939 on the instructions of Quaid-e-Azam Muhammad Ali Jinnah.He served as the President of All-India Muslim League''s Balochistan branch.', 0, 0, 0, 1790967401546) ON CONFLICT(id) DO NOTHING;
