INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_91f63e44a1566fda', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The Quaid-e-Azam stayed during his last illness in 1948 in ________ ?', '{"A":"Ziarat","B":"Sibi","C":"Quetta","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Quaid-e-Azam stayed in during his last illness in 1948 in Ziarat.Quaid-e-Azam Residency, also known as Ziarat Residency.It is located in Ziarat, Balochistan, Pakistan. He spent the last two months and ten days of his life.Additional information:He was Born on December 25, 1876, in Karachi.He died on September 11, 1948, in Karachi.He was the founder and first governor-general (1947–48) of Pakistan.', 0, 0, 0, 1790967401738) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_390f58895661fc80', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Pakistan Resolution 1940, was seconded from Sindh by?', '{"A":"Syed Zakir Ali","B":"Sir Abdullah Haroon","C":"I.I Chudrigar","D":"Sir Zafar Ali Khan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Lahore Resolution is commonly known as the Pakistan Resolution.It was moved in the general session by A. K. Fazlul Huq, the Chief Minister of undivided Bengal.It was seconded by:Chaudhry Khaliquzzaman from the United ProvincesZafar Ali Khan from PunjabSardar Aurangzeb Khan from the North-West Frontier ProvinceSir Abdullah Haroon from Sindh', 0, 0, 0, 1790967401738) ON CONFLICT(id) DO NOTHING;
