INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fd71ce9af4d83c4d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who was the penultimate viceroy of India?', '{"A":"Warren Hasting","B":"Lord Wavell","C":"Lord Canning","D":"Lord Minto"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wavell served as the penultimate viceroy under two prime ministers, Churchill and Attlee. He came to India as the successor to Lord Linlithgow.', 0, 0, 0, 1790967401873) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4bfe66e1ca1faf18', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'What is the mother name of Allama Iqbal?', '{"A":"Imam Bibi","B":"Kareem Bibi","C":"Zainab  Bibi","D":"Npne of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allama Iqbal Mother name is Imam BibiShe died on 9 November 1914 in Sialkot.Allama Iqbal Father was Sheikh Noor Muhammad. Additional InformationAllama Iqbal Born: November 9, 1877 (Sialkot)He was Died: 21 April 1938His Burial: Badshahi Mosque in LahoreThey Received PhD: in GermanyHis Title: Poet of the EastPunjab was a political area of Allama IqbalHe was elected to the Punjab Legislative Council in 1927', 0, 0, 0, 1790967401873) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_65e9a6c842f31d5f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Mohanlal Karamchand Gandhi renounced his formal membership of the Congress in which year?', '{"A":"1934","B":"1940","C":"1946","D":"1949"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mahatma Gandhi renounce ترک کرنا Congress membership in 1934 because he angry with Nehru''s arbitrariness من مانی', 0, 0, 0, 1790967401873) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f56a7d717e456347', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'In the year 1613, where was the English East India Company given permission to set up a factory (trading post)?', '{"A":"Madras","B":"Bangalore","C":"Surat","D":"Masulipattam","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1612 Sir Thomas Roe visited to Mughal Emperor Jahangir to arrange for a commercial treaty that would give the company exclusive rights to reside and build factories in Surat and other areas. Jahangir accepted the proposal and the company created trading posts in Surat (where a factory was built in 1613), Madras (1639), Bombay (1668), and Calcutta (1690).MUG 10-12-2022', 0, 0, 0, 1790967401914) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e8be9e89c0687c3f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'British East India Company annexed which part of India after the battle of Plassey?', '{"A":"Punjab","B":"Bengal","C":"Hyderabad Deccan","D":"Sindh"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The British East India Company annexed Bengal after the Battle of Plassey in 1757.The battle was a decisive victory for the British East India Company, under the leadership of Robert Clive, over the Nawab of Bengal and his French allies on June 23, 1757.The victory marked the beginning of nearly two centuries of British rule in India.', 0, 0, 0, 1790967401914) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6e4841c6e2660ab9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Aurangzeb died in ______?', '{"A":"1689","B":"1701","C":"1707","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Aurangzeb Died on March 3, 1707, Bhingar, Ahmednagar, IndiaHe is buried in a humble tomb in grave in KhulabadHe was the sixth Mughal emperor Aurangzeb ruled the Mughal Empire from 1658 to 1707He Born on November 3, 1618, Dahod, India', 0, 0, 0, 1790967401914) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_de25a5f26fbf0e42', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who among the following remained viceroy of India from 1943 to 1947?', '{"A":"Lord Mountbatten","B":"Lord Hardinge","C":"Lord Rippon","D":"Lord Wavell"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lord Wavell remained viceroy of India from 1943 to 1947', 0, 0, 0, 1790967401914) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e0eb8a945d89bbbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The Khilafat Movement was related to ______?', '{"A":"Mughal Empire","B":"Umar Bin Abdul Aziz","C":"Abbasi Khilafat","D":"Ottoman Empire"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Khilafat Movement came to an end in 1924 when Mustafa Kemal Atatürk abolished the Ottoman Caliphate.The movement started in 1919.It was led by Indian Muslim leaders like Maulana Muhammad Ali Jauhar and Maulana Shaukat Ali to protect the Caliphate.', 0, 0, 0, 1790967401914) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3f5dbf2dabdfc919', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'What is the purpose of the formation of all India National Congress?', '{"A":"For Indian to take part in parties","B":"To return India Governess","C":"A platform for the civic and political dialogue among educated Indian","D":"All of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indian National Congress was formed in 1885 with the primary purpose of providing a platform for civic and political dialogue among educated Indians.The Congress was established by Allan Octavian Hume, a retired British Indian Civil Service officer, with the goal of creating a space where Indians could discuss and address political and social issues.The Congress also aimed to promote Indian participation in the governance of their own country and to advocate for Indian rights and interests.', 0, 0, 0, 1790967401914) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a123bbe00cea7564', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was Lucknow recaptured by British Forces?', '{"A":"1859","B":"1761","C":"1857","D":"1858"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lucknow was recaptured by British forces in 1858, during the Indian Rebellion of 1857, also known as the Sepoy Mutiny.The rebellion began in May 1857, and Lucknow, the capital of the Awadh region.It was a key center of resistance against British rule.The British forces, led by General Sir Colin Campbell, recaptured Lucknow in March 1858, after a prolonged siege and fierce fighting.', 0, 0, 0, 1790967401914) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a6aae9525330a3ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Dogra dynasty bought Kashmir from the British in the year?', '{"A":"1844","B":"1845","C":"1848","D":"1846","E":"1847"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Dogra dynasty was a dynasty of Hindu Rajputs who ruled Jammu & Kashmir from 1846 to 1947.After the First Anglo-Sikh War in 1846, the British gave Kashmir and the title of ''Maharaja'' to Gulab SinghAGM 30.4.23', 0, 0, 0, 1790967401914) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_67797012bcc61787', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Partition of Bangal was annulled under British Monarch?', '{"A":"King George IV","B":"King George V","C":"King George VII","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ø On the visiting His Majesty King George V to Indo-Pakistan and holding of Darbar at Delhi on 12th December 1911 the partition of Bengal was cancelled. **** Ø Partition of Bengal Announced on 19 July 1905 by Lord Curzon for Administrative requirements Ø Congress protest against Partition of Bengal', 0, 0, 0, 1790967401945) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a1e718454f165a55', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'All India Muslim League was established in which city?', '{"A":"Calcuta","B":"Karachi","C":"Dhaka","D":"Lucknow","E":"Aligarh"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All India Muslim League Founded on 30 December 1906 at Dhaka, Bangladesh It was Founder by Nawab Khwaja SalimullahIts Headquarters is located in LucknowThey were Dissolved on 14 August 19471st President of All India Muslim League is Sir Agha Khanجب 1947 میں مسلم لیگ ختم ہوئی تو یہ تین پارٹیاں بن گئی1- Muslim League in Pakistan2- Awami League in Bangladesh3- Indian Union Muslim League in India', 0, 0, 0, 1790967401945) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3ad8dfdfed6873c4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who wrote Myth of Independence?', '{"A":"Gen Zia Ul Haq","B":"Zulfikar Ali Bhutto","C":"Ashfaq Kyani","D":"Parvez Musharaf","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Myth of Independence was written by Zulfiqar Ali Bhutto.Myth of Independence was published in 1969.AGM25.01.23ND23-4-2023', 0, 0, 0, 1790967401945) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8addb24c5cd72de4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'When was the Partition of Bengal cancelled?', '{"A":"1905","B":"1906","C":"1911","D":"1919"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Partition of Bengal was cancelled in 1911, reunifying the province of Bengal.This decision was a response to the growing nationalist movement and Swadeshi movement, which advocated for Indian independence and economic self-reliance.', 0, 0, 0, 1790967401945) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a4601a4f242b18bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The Lahore Resolution was supported by Qazi Muhammad Isa from the provice of ___?', '{"A":"Punjab","B":"Sindh","C":"Balochistan","D":"None of the above"}', 'C', NULL, 0, 0, 0, 1790967401945) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a2825860175f775a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Quaid e Azam resigned from the Indian National congress as a protest against _____?', '{"A":"Styagraha movement","B":"Nehru report","C":"Mopala revolt","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1919 he resigned from the legislative council in protest against the Rowlatt Acts.In 1920 he broke with Congress and resigned from the Home Rule League because he disagreed with the increasingly popular Gandhi''s policy of non-cooperation with the British and aim of complete swaraj or self-rule.', 0, 0, 0, 1790967401945) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_409fde8c5eed3969', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'After Independence the first Radio Station was established in?', '{"A":"Karachi","B":"Lahore","C":"Dhaka","D":"Rawalpindi"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan’s first radio station was set up in Karachi.Karachi radio station was inaugurated by Liaqat Ali Khan on 14 August 1948Additional Information:Pakistan''s independence was announced first through Lahore Radio station.Three radio stations existed at the time of independence of Pakistan on 14 August 1947.1. Peshawar Radio Station was established in 19352. Lahore radio station established in 19373. Dhaka radio station established in 1939******', 0, 0, 0, 1790967401945) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_aaa951e1b76fc7db', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'In 1927 Jinnah called a Conference of All Muslim leaders. The conference resulted in several demands known as?', '{"A":"Lucknow Pact","B":"Nehru Report","C":"Fourteen Points","D":"Delhi Proposals"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 1927 meeting refers to the Delhi Muslim ProposalsHeld in Delhi on 20th March 1927Muhammad Ali Jinnah proposed terms to the Indian National Congress to Demands secure Muslim political rightsthe separation of Sindh, reforms in NWFP and Balochistan1/3 representation in the Central Legislature.', 0, 0, 0, 1790967401945) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_74bd0ea92b1e5252', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'In 1930, Allama Iqbal Two-Nations theory in ___?', '{"A":"Delhi","B":"Allahabad","C":"Dhaka","D":"Lahore"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Allahabad Address was a notable speech by Sir Muhammad Iqbal.He delivered during the 25th annual session of the All-India Muslim League on 29 December 1930, in Allahabad, British India.Dr. Sir Muhammad Iqbal presided over this session.', 0, 0, 0, 1790967401977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f2609a95b7c7c83f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Khilafat movement was a political campaign launched by _____?', '{"A":"Muslims","B":"Hindus","C":"All Indians","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Khilafat movement (1919–22) was a political campaign launched by Indian Muslims.The ''Khilafat Movement Day'' was observed on 17th October 1919. This campaign was launched in Defence of the Caliphate, led in India by the two Brothers Muḥammad and Shaukat Ali and by Abul Kalam Azad.', 0, 0, 0, 1790967401977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e663958089ca101f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Sir Dinsha was the _____ of Ratna (the wife of Jinnah).', '{"A":"Brother","B":"Father","C":"Uncle","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sir Dinsha was the father of Ratna, who was later became known as the wife of Muhammad Ali Jinnah.He was a prominent Parsi community leader and philanthropist.', 0, 0, 0, 1790967401977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0a15abd3cd268cd9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'The Lahore Resolution was moved on 23 March 1940 by _____?', '{"A":"A.K Fazlul-Haq","B":"Allama Iqbal","C":"Quaid e Azam Muhammad ALi Jinnah","D":"Liaquat Ali Khan"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Lahore Resolution''s English to Urdu translation was done by Maulana Zafar Ali Khan.The resolution was presented by A.K. Fazlul Haq.Leaders participating from various regions included:Punjab: Zafar Ali KhanSindh: Sir Abdullah HaroonBalochistan: Qazi Faiz IsaKPK: Sardar Aurangzeb KhanThe Chief Minister of Bengal was A.K. Fazlul Haq.The representative for the United Provinces was Khalid Zaman.', 0, 0, 0, 1790967401977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6f5d39cd7abda12a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Akbar Nama was a _____ volume history of Akbar''s reign, written by Abul Fazl.', '{"A":"Two","B":"First","C":"Three","D":"Four"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Akbar Nama was a three-volume history of Akbar''s reign, written by Abul Fazl.It details the events of Akbar''s empire and his administration.Akbar Nama was written in Persian language.Abu al Fazal was killed by Bir Singh Deva Bundela.', 0, 0, 0, 1790967401977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8af10a984f1dd737', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Jinnah Gandhi talks were held in?', '{"A":"Bombay","B":"Delhi","C":"Lahore","D":"Lucknow"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jinnah Gandhi talks were made in Bombay India, in 1944.Talk failed because Gandhi simply refused to accept the Lahore Resolution as interpreted by Jinnah.', 0, 0, 0, 1790967401977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0c5f8cf0ba862fc3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who was second secretary general of all India Muslim League?', '{"A":"Maulana Muhammad Ali Johar","B":"Liaquat Ali Khan","C":"Adamjee Peerbhoy","D":"Sir Muhammad Shafi"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation List of Secretaries-General of the All-India Muslim LeagueSir Agha Khan (1906-1913)Sir Muhammad Shafi (1913-1916)Maulana Mohammad Ali Jauhar (1916-1918)Maulana Shaukat Ali (1918-1920)Nawab Viqar-ul-Mulk (1920-1921)Muhammad Ali Jinnah (1920-1921)Muhammad Shafi (1921-1923)Liaquat Ali Khan (1923-1928)Sir Sikandar Hayat Khan (1928-1931)Raja Sahib of Mahmudabad (1931-1936)Sir Abdullah Haroon (1936-1941)Khawaja Nazimuddin (1941-1947)', 0, 0, 0, 1790967401977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f78b286f1a34f63f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Khilafat Conference at Larkana was held from?', '{"A":"6-8 June 1920","B":"7-9 July 1921","C":"2-4 October 1922","D":"3-5 May 1919"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Khilafat Conference: Held in Bombay (now Mumbai) in July 1919.Second Khilafat Conference: Held in Delhi in November 1919.Third Khilafat Conference: Held in Amritsar in December 1919.Fourth Khilafat Conference: Held in Allahabad in July 1920.Fifth Khilafat Conference: Held in Calcutta (now Kolkata) in November 1920.Sixth Khilafat Conference: Held in Nagpur in December 1920.Seventh Khilafat Conference: Held in Karachi in February 1921.Eighth Khilafat Conference: Held in Delhi in November 1921.', 0, 0, 0, 1790967401977) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_412e159daef461e5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Who established the Mughal Empire?', '{"A":"Sher Shah Suri","B":"Humayun","C":"Akbar","D":"Aurangzaib","E":"Babur"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Babur was the founder and first Emperor of the great Mughal dynasty in India.Babar invaded the kingdom of the Lodi Afghans in northern India in 1526 Mughal Empire lasted from 1526 to 1857.There are 17 Mughal families who rule in IndiaFirst Mughal Emperor: BabarLast Mughal Emperor: Behadur Shah Zafar', 0, 0, 0, 1790967402013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b345e38f2e736dfb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Quaid-e-Azam visited _________ times to Islamia College Peshawar.', '{"A":"Two","B":"Four","C":"One","D":"Three"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam visited 3 times to Islamia College Peshawar in:1936, 1945 1948. Quaid-e-Azam who became a lifelong honorary member of the Khyber Union ICP in 1936 made the College one of the heirs of his property in 1939.***Founded by Abdul Qayoom Khan in 1913.AGM 25-12-2022ND17-7-2023', 0, 0, 0, 1790967402013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4d1a85e48a3fe777', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Sher Shah Suri ruled India from 1540 till which year?', '{"A":"1542","B":"1556","C":"1548","D":"1545","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sher Shah Sur''s real name is Farīd Khān.Sher Shah Suri is well-known for his Land Revenue SystemSher Shah Suri Ruled India for 5 years from 1540 to 1545.Born: 1486, Sasaram, IndiaSher Shah Suri died: on 22 May 1545Sher Shah Suri introduced: Rupee CurrencySher Shah Suri built: GT RoadSher Shah took control of the Mughal Empire in 1540.Sher Shah Suri buried in Sasaram', 0, 0, 0, 1790967402013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f154ea5939cfacb2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_history', 'Which city of Pakistan is laid out on the shape of British flag?', '{"A":"Lahore","B":"Multan","C":"Quetta","D":"Faisalabad","E":"Karachi"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Faisalabad Clock Tower is famous all over the world and is one of the oldest monuments. It was constructed in a special way by placing the clock at the center of the eight markets which, from the top it looks like the Union Jack of the United Kingdom''s flag.', 0, 0, 0, 1790967402013) ON CONFLICT(id) DO NOTHING;
