INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b39542eede69606a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who became the Governor General Of Pakistan after the death of Quiad-e-Azam Muhammad Ali Jinnah?', '{"A":"Liaqat Ali Khan","B":"Khawaja Nazim ud Din","C":"Ghulam Mohammad","D":"Muhammad Ali Bogar"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1. Muhammad Ali JinnahOffice: 14 Aug 1947 – 11 Sep 1948Duration: ~1 year 28 daysMonarch: George VI2. Sir Khawaja NazimuddinOffice: 14 Sep 1948 – 17 Oct 1951Duration: ~3 years 33 daysMonarch: George VI3. Sir Ghulam MuhammadOffice: 17 Oct 1951 – 7 Aug 1955Duration: ~3 years 294 daysMonarch: George VI / Elizabeth II4. Iskander MirzaOffice: 7 Aug 1955 – 23 Mar 1956Duration: ~299 daysMonarch: Elizabeth IILast verified on 23-06-2026', 0, 0, 0, 1790967402434) ON CONFLICT(id) DO NOTHING;
