INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3f5b4bea8a557e40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'When Pervez Musharraf resigned as the President of Pakistan?', '{"A":"14 July 2008","B":"18 August 2008","C":"12 September 2008","D":"7 October 2005"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Presidency period: 20 June 2001 – 18 August 2008Took power: 12 October 1999 (military coup)Position before presidency: Chief of Army Staff (1998–2007)Party formed later: All Pakistan Muslim League (APML, 2010)Preceded by: Muhammad Rafiq TararLast verified on 21-06-2026', 0, 0, 0, 1790967402465) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c1fc8a2110c03ae2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the first Finance Minister of Pakistan?', '{"A":"I.I Chandigarh","B":"Malik Ghulam Muhammad","C":"Liaquat Ali Khan","D":"Muhammad Ali"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Malik Ghulam Muhammad was the first Finance Minister of Pakistan (15 August 1947 – 19 October 1951).He was appointed by Quaid-e-Azam Muhammad Ali Jinnah.He served during the governments of Liaquat Ali Khan and Khawaja Nazimuddin.Succeeded as Finance Minister by: Muhammad AliLater, he became the 3rd Governor-General of Pakistan (1951–1955).Additional information:Born: 29 August 1895, LahoreDied: 29 August 1956, LahoreResting Place: Fauji Qabrastan, KarachiLast verified on 15-06-2026', 0, 0, 0, 1790967402465) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_68036539bd0fd6a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the first Pakistani Prime Minister/Leader who visited China?', '{"A":"Nawabzada Liaqat Ali","B":"Khwaja Nazimudin","C":"Hussain Shaheed Suhrawardy","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Leader: Hussain Shaheed SuhrawardyVisit Year: 1956Chinese Counterpart: Premier Zhou EnlaiEvent: Signing of Treaty of Friendship Between China and Pakistan in BeijingSignificance: Laid the foundation for long-term Pakistan-China relationsLast verified on 16-01-2026', 0, 0, 0, 1790967402465) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_257eb7ae80db597e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The office/designation of Governor-General abolished and changed to President on?', '{"A":"23rd March 1956","B":"05 July 1955","C":"16 October 1951","D":"15 August 1947"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The office of Governor-General of Pakistan was abolished on 23 March 1956.On this date, Pakistan became the first Islamic Republic.The new post of President was introduced.Iskander Mirza became the first President.This change was made under the 1956 Constitution of Pakistan.Muhammad Ali Jinnah was the first Governor-General.Last verified on 30-04-2026', 0, 0, 0, 1790967402465) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bcbae4caee205004', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Which of the following forts was built by Mughal Emperor Zaheer-ud-din Babar in the 16th century A.D?', '{"A":"Rohtas","B":"Bala Hisar","C":"Ranikot","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bala Hisar Fort was first built by Zaheer-ud-din Babar in 1526 AD after capturing Peshawar.Used as: Royal residence by the Durrani Empire (from 1747)Captured by Marathas: 1758Reconstructed by Sikhs: 1823Last verified on 01-03-2026', 0, 0, 0, 1790967402465) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b6fceb67d19f789e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Hyderabad was a ______ majority state under a Muslim ruler.', '{"A":"Hindu","B":"Muslim","C":"Sikh","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hyderabad was a Hindu-majority state ruled by a Muslim Nizam.The state was governed by the Nizams of Hyderabad (1724–1948).Religion distribution:Hinduism: ~81%Islam: ~13%Christianity: ~6%Rule: Nizams (Asaf Jahi dynasty)Founder: Mir Qamar-ud-din KhanCapital:Aurangabad (1724–1763)Hyderabad (1763–1948)Languages: Persian (earlier), later UrduLast verified on 11-06-2026', 0, 0, 0, 1790967402500) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0fa9f5757855084d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the First woman Governor of State Bank of Pakistan?', '{"A":"Dr. Farzana Raja","B":"Dr. Shama Khalid","C":"Dr. Shamshad Akhter","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Dr. Shamshad Akhtar was the first female Governor of the State Bank of Pakistan (SBP).She served as Governor from 2006 to 2009.Additional information:Founded: 1 July 1948Founder: Muhammad Ali JinnahHeadquarters: Karachi, SindhFirst Governor: Zahid HussainLast verified on 06-06-2026', 0, 0, 0, 1790967402500) ON CONFLICT(id) DO NOTHING;
