INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4c660576f955b1dc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'How many seats were won by the Awami league in the 1970 election?', '{"A":"160","B":"300","C":"149","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 160 seats was won by awami league in the 1970 election***In the elections of 1970, the Awami League won 167 of 169 East Pakistan seats in the National Assemblybut none of West Pakistan''s 138 seats.It also won 288 of the 300 provincial assembly seats in East Pakistan.', 0, 0, 0, 1790967402625) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_eff1ba5ecc26a242', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who served as the President of Pakistan from 1971 to 1973?', '{"A":"Yahiya Khan","B":"Ayoub Khan","C":"Zulfiqar Ali Bhutto","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zulfiqar Ali Bhutto was a Pakistani barrister and politician who served as the ninth prime minister of Pakistan from 1973 to 1977, and prior to that as the fourth president of Pakistan from 1971 to 1973.****', 0, 0, 0, 1790967402625) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0e941a911b01945a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Which of the following first President of the Constituent Assembly of Pakistan?', '{"A":"Quaid-e-Azam","B":"Moulvi Tameez-ud-Din","C":"Liaquat Ali Khan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 11th August 1947 Quaid-e-Azam Muhammad Ali Jinnah was elected as the President of the Constituent Assembly of Pakistan.The first session of the Constituent Assembly of Pakistan was held on 10th August 1947 at the Sindh Assembly Building in Karachi. Liaquat Ali Khan headed after the death of Jinnah for three years and produced the Objectives Resolution.****', 0, 0, 0, 1790967402625) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d76129abb26e861d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The First Muslim ruler to introduce the System of Price Control in the sub-continent was ______?', '{"A":"Jalal uddin Akbar","B":"Allau ud din Khilji","C":"Muhammad bin Tughluk","D":"Shah Jehan"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The system of market control or price control was introduced by Alauddin Khalji during the Sultanate period.He was the second ruler of the Khilji Dynasty in IndiaAGM 24-12-2022', 0, 0, 0, 1790967402625) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cd6afe59fcfb7f4c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The first Prime Minister of Pakistan was:', '{"A":"Quaid e Azam","B":"Allama Iqbal","C":"Liaqat Ali Khan","D":"Fatima Jinnah","E":"Skindar Mirza"}', 'C', NULL, 0, 0, 0, 1790967402625) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6a2f68b629929f63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'According to SBP Act 2021, the governor of State Bank of Pakistan (SBP) shall be appointed for a term of________?', '{"A":"Two Years","B":"One Year","C":"Four Years","D":"Five Years","E":"Seven Years"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation According to SBP Act 2021, the governor of the State Bank of Pakistan (SBP) shall be appointed for a term of five Years***Mr. Jameel Ahmad assumed the charge of Governor State Bank of Pakistan on August 26, 2022, after his appointment by the President of Pakistan for a period of 5 years.Ms. Kamil is the first woman appointed as Deputy Governor of SBP.Sh1-9-2023', 0, 0, 0, 1790967402625) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1901df3a75657c5c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was UN General Assembly President in 1962-1963?', '{"A":"Sir Zuffarullah Khan","B":"Razali","C":"Ban Ke Moon","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sir Muhammad Zafarullah Khan of Pakistan was the President of the United Nations General Assembly from 1962 to 1963. He was Pakistan''s first foreign minister and led the case for Pakistan''s separate nation in the Radcliffe Commission.He also served as a judge on the International Court of Justice from 1954 to 1958, and as its vice president from 1958 to 1961.In 1970, he became the first and only Pakistani to serve as the President of the International Court of Justice.', 0, 0, 0, 1790967402655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6bcaabe9bfcc5a63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The ____ city was the Birthplace of the Mughal Emperor Akbar was born.', '{"A":"Madras","B":"Kabul","C":"Panipat","D":"Umarkot"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jalal uddin Muhammad Akbar was a Mughal emperor.He was born in Umarkot (Sindh) in 1542.He became Emperor in 1556.He was died in 1605.', 0, 0, 0, 1790967402655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f930a48ed61034ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who became President of Pakistan after Ayub Khan?', '{"A":"Mr. Z.A Bhutto","B":"Mr. Pervez Musharaf","C":"Mr. Fazl Elahi Choudhary","D":"Gen. Yahya Khan","E":"Justice Rafique Tarar"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Gen. Yahya Khan became the third President of Pakistan after Ayub Khan*****Yahya Khan was a Pakistani general who served as the third president of Pakistan from 25 March 1969 until December 1971.****', 0, 0, 0, 1790967402655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e1f0827fda27c06a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the fourth Governor-General of Pakistan?', '{"A":"Muhammad Ali Jinnah","B":"Sir Khawaja Nazimuddin","C":"Sir Ghulam Muhammad","D":"Iskander Mirza"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation List of Governors-General of Pakistan Term Name Birth–Death Monarch Took office Left office Political party Remarks 1 Muhammad Ali Jinnah (1876–1948) George VI (1947–1952) 15-Aug-47 11-Sep-48 Pakistan Muslim League died in office 2 Sir Khawaja Nazimuddin (1894–1964) = 14-Sep-48 17-Oct-51 Pakistan Muslim League became prime minister 3 Sir Ghulam Muhammad (1895–1956) = 17-Oct-51 7-Aug-55 Independent dismissed 4 Iskander Mirza (1899–1969) Elizabeth II (1952–1956) 7-Aug-55 23-Mar-56 Republican Party became president', 0, 0, 0, 1790967402655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_de8cfd6c7341deec', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the first Chief Minister of West Punjab?', '{"A":"Iftikhar Hussain Khan Mamdoot","B":"Mian Mumtaz Ahmad Daultana","C":"Malik Feroz Khan Noon","D":"Abdul Hameed Khan Dasti"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Iftikhar Hussain Khan Mamdoot was the first Chief Minister of West Punjab. He served from 15 Aug 1947 to 25 Jan 1949. He had also served as governor of Sindh. He died in 1969.***', 0, 0, 0, 1790967402655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a22c67905c79a9aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Shahid Khaqan Abbssi was the ______ Prime Minister of Pakistan?', '{"A":"22nd","B":"16th","C":"20th","D":"21st"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shahid Khaqan Abbasi is a Pakistani politician who served as the 21st prime minister of Pakistan from August 2017 to May 2018.', 0, 0, 0, 1790967402655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b0e81a9ab3eabc0d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who among the following was the last ruler of Delhi Sultanate?', '{"A":"Ibrahim Lodi","B":"Qutb al-Din Aibak","C":"Bahadur Shah Zafar","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Lodhi Dynasty was the last dynasty of the Delhi Sultanate.It was ruling from 1451 until the defeat by Babur in 1526, which led to the establishment of the Mughal Empire.The first dynasty of the Delhi Sultanate was the Mamluk Dynasty (also known as the Slave Dynasty), which began with Qutb al-Din Aibak in 1206.', 0, 0, 0, 1790967402655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2bdbd43284c8dda8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Quaid e Azam''s tenure as Governor?', '{"A":"12 months","B":"13 months","C":"14 months","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid e Azam worked as governor-general of Pakistan for 13 months from 14 August 1947 – 11 September 1948He was the 1st Governor-General of Pakistan.Succeeded by: Khawaja NazimuddinAdditional information:Muhammad Ali Jinnah joined the league in 1913.He was 37 years old when he joined Muslim League.He joined the Indian National Congress in 1906 and left in 1920He was Born on December 25, 1876, in KarachiHe died on September 11, 1948, in Karachi', 0, 0, 0, 1790967402655) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1da0f3e647dc3c11', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The British Prime Minister Ramsay Macdonald announced the Communal Award in 1932 at the end of ______?', '{"A":"1st Round Table Conference","B":"2nd Round Table Conference","C":"3rd Round Table Conference","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The British Prime Minister Ramsay MacDonald announced the Communal Award in 1932 at the end of the Second Round Table Conference. The Communal Award was a series of elections for minority groups in society and the economy. It was established on August 16, 1932, as a result of the second round table meeting.', 0, 0, 0, 1790967402684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b70c8d4294e92838', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'British Governor-General who followed the spirited "Forward Policy" towards Afghanistan was ______?', '{"A":"Minto","B":"Dufferin","C":"Elgin","D":"Lytton"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Lord Lytton, who was the Governor-General of India from 1876 to 1880, followed a spirited "Forward" policy towards Afghanistan.He believed that the British should pursue an aggressive policy towards Afghanistan, which led to the Second Anglo-Afghan War.Lytton was appointed by Conservative Prime Minister Benjamin Disraeli and purportedly feared the spread of Russian influence in Central Asia.', 0, 0, 0, 1790967402684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a96150f0a1d45c7d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who took oath from PM Liaqat Ali Khan ?', '{"A":"Sikandar Ali Mirza","B":"Quaid-i-Azam","C":"Justice Mian Abdul Rashid","D":"Lord Mountbatten","E":"Maulvi Tamizuddin"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Liaqat Ali Khan was named Pakistan’s first Prime Minister by the country’s founding fathers after the country gained independence in 1947. Liaqat Ali Khan administered the oath to Quaid-i-Azam Muhammad Ali Jinnah.****', 0, 0, 0, 1790967402684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ceaaf431459d9860', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the second president of Indian National Congress?', '{"A":"Womesh Chunder Bonnerjee","B":"Dadabhai Naroji","C":"Baddrudin Tayyabji","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Founder: Allan Octavian HumeFounded: 28 December 1885 Headquarters: New Delhi', 0, 0, 0, 1790967402684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ea4cc6a4fbeac8ed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The cabinet mission arrived in India in _____?', '{"A":"1943","B":"1944","C":"1945","D":"1946"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cabinet Mission broadcast its plan from New Delhi on May 16, 1946. They arrived in India on March 24, 1946, sent by the British government. The Mission was headed by Lord Pethick Lawrence. The mission had three British cabinet members: Pethick Lawrence Stafford Cripps A.V. Alexander The Cabinet Mission aimed to discuss the transfer of power from British to Indian leadership.', 0, 0, 0, 1790967402684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7f6fcdff99d80138', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the opponent of Ayub Khan in the Presidential election of 1965?', '{"A":"Fatima Jinnah","B":"Yahya Khan","C":"Mrs. Liaqat Ali Khan","D":"Sikandar Mirza"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan''s second Presidential Elections were held on 2 January 1965. There were four candidates: Ayub Khan, Fatima Jinnah and two obscure people with no party affiliation.', 0, 0, 0, 1790967402684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7eab195940f2ba1c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Raja Dahir was the ruler of ______?', '{"A":"Sindh","B":"Depalpur","C":"Punjab","D":"Dehli"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Raja Dahir was the last Hindu ruler of Sindh in present-day Pakistan. In 711 CE his kingdom was invaded by the Umayyad Caliphate led by Muhammad bin Qasim where Dahir died while defending his kingdom.******راجہ داہر موجودہ پاکستان میں سندھ کے آخری ہندو حکمران تھے۔711عیسوی میں اس کی سلطنت پر اموی خلافت نے حملہ کیا جس کی قیادت محمد بن قاسم کر رہے تھے۔جہاں داہر اپنی سلطنت کا دفاع کرتے ہوئے مر گیا۔', 0, 0, 0, 1790967402684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a3e1913464bd921c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Benazir Bhutto first sworn in as Prime Minister of Pakistan on _________?', '{"A":"27 December 1988","B":"2 December 1988","C":"19 November 1989","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790967402684) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_816f4ee0b3f74642', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the second ruler of Lodhi Empire?', '{"A":"Bahlol Lodhi","B":"Sikandar Lodhi","C":"Ibrahim Lodhi","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The list of rulers of the Lodi dynasty:Bahlol Lodhi (1451-1489)Sikandar Lodhi (1489-1517)Ibrahim Lodhi (1517-1526)Bahlul Khan Lodhi was the founder of the Lodhi dynasty of India (1451-1526)Bahlul Khan Lodhi was the founder of the Lodhi dynasty when he replaced the Sayyid dynasty.By the end of the 15th century, Bahlul Lodi firmly established the Lodi dynasty The Lodhi dynasty It was the fifth and final dynasty of the Delhi Sultanate', 0, 0, 0, 1790967402712) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_04c6033fa2e9adca', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'As per Article 62 of the Constitution of Pakistan 1973, what age is specified for members of National Assembly to contest election?', '{"A":"25","B":"27","C":"30","D":"29"}', 'A', NULL, 0, 0, 0, 1790967402712) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_dcdacec7e6f3698d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'In the case of Muhammad Nawaz Sharif vs President of Pakistan (PLD 1993 S.C 473), who was the Chief Justice?', '{"A":"Nasim Hassan Shah","B":"Saad Saud Jan","C":"Ajmal Mian","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the case of Muhammad Nawaz Sharif vs President of Pakistan (PLD 1993 S.C 473), Nasim Hassan Shah was the Chief Justice.He headed the Supreme Court bench that delivered the judgment in this significant constitutional case.', 0, 0, 0, 1790967402712) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_43833d84d4a6066c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'As per Article 203-C (2) of the Constitution of Pakistan 1973, the Federal Shariat Court shall consist of not more than _____ Muslim Judges, including the Chief Justice, to be appointed by the President in accordance with Article 175A.', '{"A":"8","B":"7","C":"10","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 203-C(2) (as amended) specifies that the Federal Shariat Court shall consist of not more than 8 Muslim Judges, including the Chief Justice.These Judges are appointed by the President under Article 175A of the Constitution.', 0, 0, 0, 1790967402712) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_246716d6972b57cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'As per the case Maulvi Tamiz-ud-Din Khan vs Governor General of Pakistan (PLD 1955 F.C 240), the President of the Constituent Assembly Maulvi Tamiz-ud-Din Khan filed a writ petition in the nature of _____ with a view to determining the validity of appellants appointments as members of the Council of Minister.', '{"A":"Certiorari","B":"Mandamus","C":"Mandamus and quo warranto","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Maulvi Tamiz-ud-Din Khan filed the writ petition in the nature of Mandamus and Quo Warranto.The petition sought to compel performance of duty and question the authority of office holders.', 0, 0, 0, 1790967402712) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5ce62be755da93bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Benazir Bhutto became the first female Prime Minister of Pakistan in _____?', '{"A":"1988","B":"1999","C":"1977","D":"2000"}', 'A', NULL, 0, 0, 0, 1790967402712) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e4d5cf541e82f22b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who became the youngest Foreign Minister in the history of Pakistan?', '{"A":"Benazir Bhutto","B":"Bilawal Bhutto Zardari","C":"Shireen Mazari","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bilawal Bhutto Zardari took oath as FM on 27 April 2022.She became a member of the National Assembly: in 2018 Previously, Shah Mehmood Qureshi was the foreign minister of Pakistan from August 2018 to April 2022.******Hinna Rabbani Khar was appointed the youngest FM in 2011 at the age of 34. Hinna Khar belongs to: the Pakistan People''s Party (Muzaffargarh, Punjab)', 0, 0, 0, 1790967402712) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_efc020cc65645fed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Taj Mahal was completed in 1648 by Emperor Shah Jahan in memory of his wife named _____?', '{"A":"Joda Bai","B":"Zaib-un-Nisa","C":"Mumtaz Mahal","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Taj MahalConstruction started1632Construction completed1647Built byMughal Emperor Shah JehanBuilt in the memory ofMumtaz MahalHeight73 MTaj MahalMost visited monument of India as of July 2022ArchitectureUstad Ahmed Lahori', 0, 0, 0, 1790967402712) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5132ea5421df2a84', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The Abbasids Governor ______ came to Sindh in 140 AH. / 757 AD.', '{"A":"Musa","B":"Walid","C":"Hisham","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 140 AH / 757 AD, Hisham ibn Amr al-Taghlibi, the Abbasid governor of Iraq, was sent to Sindh by the Abbasid Caliphate.He is known for consolidating Abbasid control in Sindh after the decline of Umayyad rule.', 0, 0, 0, 1790967402742) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9150af26b7b59b8a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'After the official visit of prime minister Liaquat Ali Khan to Iran. When did Shah of Iran visited Pakistan for the first time?', '{"A":"1947","B":"1948","C":"1951","D":"1950"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Shah of Iran, Mohammad Reza Pahlavi, visited Pakistan for the first time in March 1950.This visit strengthened Pakistan-Iran diplomatic relations, leading to future alliances like RCD (1964) and ECO (1985).', 0, 0, 0, 1790967402742) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_50ea4b607a13424d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'As Prime Minister, Imran Khan first visited officially which country?', '{"A":"Afghanistan","B":"Saudi Arabia","C":"Iran","D":"China"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Inaugural two-day visit to meet King Salman of Saudi Arabia in Jeddah. to discuss matters of regional and bilateral interest. Khan also performed the Umrah in Mecca and visited the Prophet''s Mosque in Medina. Date: 18–19 September 2018', 0, 0, 0, 1790967402742) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c85c82fa0d9e0290', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The ruler of Junagarh at the time of Independence was ____?', '{"A":"Sikh","B":"Muslim","C":"Hindu","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The ruler of Junagarh at the time of independence was Nawab Muhammad Mahabat Khanji III.He was a Muslim ruler.He initially opted to join Pakistan. This decision was made despite the majority Hindu population in the state.', 0, 0, 0, 1790967402742) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_edc3a2113583c966', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who became the President of Pakistan after General Yahya Khan in 1971?', '{"A":"Zulfikar Ali Bhutto","B":"Ayub Khan","C":"Zia-ul-Haq","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zulfikar Ali Bhutto returned to Pakistan on 18 December 1971.On 20 December, he took over as President and Chief Martial Law Administrator from Yahya Khan.Bhutto served as President from December 1971 to August 1973.Bhutto served as Prime Minister from August 1973 to July 1977.', 0, 0, 0, 1790967402742) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2be82cef4030fbed', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'When President Mamnoon Hussain signed the FATA merger bill?', '{"A":"31 March 2018","B":"31 January 2018","C":"31 May 2018","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation President Mamnoon Hussain signed the FATA merger bill on May 31, 2018.The bill was passed by the National Assembly on May 24, 2018, and by the Senate on May 25, 2018.FATA will have 21 seats within the KP Assembly:16 general4 reserved for women1 reserved for non-MuslimsThe incumbent senators for FATA will be allowed to complete their six-year terms.The Khyber Pakhtunkhwa Assembly will have 145 seats115 general26 reserved for women4 reserved for minoritiesFATA was merged with KPK in May 2018 under the 25th Amendment.', 0, 0, 0, 1790967402742) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f5f820c17a141d10', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'General Pervez Musharraf was elected as President through referendum on?', '{"A":"20 June 2001","B":"20 April 2002","C":"20 April 2004","D":"20 April 2003"}', 'A', NULL, 0, 0, 0, 1790967402742) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cf7cdb02d9cf23e1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the third Governor General of Pakistan?', '{"A":"Sir Khawaja Nazimuddin","B":"Muhammad Ali Jinnah","C":"Ghulam Muhammad","D":"Sikandar Ali Mirza"}', 'C', NULL, 0, 0, 0, 1790967402742) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8b9984dc4bb0249f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The Simla Agreement signed by Prime Minister Indira Gandhi and President Zulfikar Ali Bhutto of Pakistan on _____?', '{"A":"2nd July 1971","B":"2nd July 1972","C":"3rd June 1973","D":"2nd July 1974"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Simla Agreement was signed on July 2, 1972, by Indian Prime Minister Indira Gandhi and Pakistani President Zulfikar Ali Bhutto, following the Bangladesh Liberation War in 1971.The agreement established the Line of Control (LoC) in Kashmir and paved the way for the repatriation of prisoners of war and the return of occupied territories.', 0, 0, 0, 1790967402770) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_79473c05a0599158', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who from the following is the first Muslim female prime minister?', '{"A":"Benazir Bhutto","B":"Mafuja Khatun","C":"Massouda Jalal","D":"Sheikh Hasina"}', 'A', NULL, 0, 0, 0, 1790967402770) ON CONFLICT(id) DO NOTHING;
