INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_05b948c5e2ef113e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the first Mughal Emperor to allow Britishers to establish trade links with India?', '{"A":"Jahangir","B":"Akbar","C":"Shah Jahan","D":"Aurangzeb"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jahangir was the first Mughal Emperor to allow Britishers to establish trade links with India.He gave permission for trade to the British East India Company, allowing them to establish a factory at Surat in 1613.This marked the beginning of British trade in India during the Mughal era.', 0, 0, 0, 1790967402770) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_75522caeb161c3a8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The downfall of Muslim rule in India started with the demise of emperor _____?', '{"A":"Aurangzeb","B":"Akbar","C":"Jahangir","D":"Bahadur Shah Zafar"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Muhi al-Din Muhammad, commonly known as AurangzebAurangzeb was the sixth emperor of the Mughal Empire ruling from July 1658 until his death in 1707Aurangzeb was Born on November 3, 1618, in Dahod, IndiaAurangzeb was Died on: March 3, 1707, Bhingar, Ahmednagar, IndiaAurangzeb, one of the highest debated Mughal emperorsUnlike other rulers, Aurangzeb only had one wife.****nd9-2-2023', 0, 0, 0, 1790967402771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c45c35585611b0c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who won the 1965 presidential election in Pakistan?', '{"A":"Ayub Khan","B":"Miss Fatima Jinnah","C":"Mian Mumtaz Daultana","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date of election: March 21, 1965Winner: Ayub KhanResult: Ayub Khan won 62.43% of the Electoral voteFatima Jinnah''s vote share: 35.86%', 0, 0, 0, 1790967402771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6ab9b89cf6a1a520', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Shah Jehan was son of King Jehangir. His real name was _____?', '{"A":"Khurram","B":"Muzafar Shah","C":"Zareef-u-Jehan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shahab-ud-din Muhammad Khurram was the original name of Shah Jahan.He was the fifth Mughal emperor from 1628 to 1658.He was the son of Emperor Jehangir.He is famous for building the Taj Mahal.', 0, 0, 0, 1790967402771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2059c3f883cdd504', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the first Defense Minister of Pakistan?', '{"A":"Muhammad Ali Jinnah","B":"Liaquat Ali Khan","C":"Sardar Abdur Rab Nishtar","D":"None of these"}', 'B', NULL, 0, 0, 0, 1790967402771) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_510111bd642b6b3d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the first federal law minister of Pakistan?', '{"A":"Liaquat Ali Khan","B":"Zafarullah Khan","C":"Ghulam Muhammad","D":"Jogendra Nath Mandal"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Jogendra Nath Mandal was the first federal law minister of Pakistan.He was appointed to the position in 1947.He played a significant role in the early governance of the country.', 0, 0, 0, 1790967402800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_62eebc71b52d7876', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The reign of which Mughal Emperor is said to be the "Golden Era"?', '{"A":"Babar","B":"Aorangzaib","C":"Shah Jahan","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shah Jehan became emperor in 1628.The reign of Shah Jahan is considered the "Golden Era" of the Mughal Empire.It was marked by architectural achievements like the Taj Mahal, and the empire reached its cultural and economic peak.', 0, 0, 0, 1790967402800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_76b14a5cd66a6c3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who had the shortest tenure as Governor General of Pakistan?', '{"A":"Maj-Gen (R) Iskandar Mirza","B":"Ghulam Muhammad","C":"Kh. Nazimmuddin","D":"Muhammad Ali Jinnah"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NamePortraitEntered officeLeft officeDate of Birth and DeathPolitical party1Muhammad Ali Jinnah15 August 194711 September 194825 December 1876 – 11 September 1948Muslim League2Sir Khawaja Nazimuddin14 September 194817 October 195119 July 1894 - 22 October 1964Muslim League3Ghulam Mohammad17 October 19516 October 195520 April 1895 - 12 September 19564Iskander Mirza6 October 195523 March 195613 November 1899 - 12 November 1969Republican Party', 0, 0, 0, 1790967402800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ce86da0df86998aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Tipu Sultan had diplomatic relations with which French ruler?', '{"A":"Nepolean","B":"Akbar","C":"Aurangzeb","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790967402800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d482a30f461eedce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Under which article of the constitution President can dissolved National Assembly?', '{"A":"12(3) c","B":"14 (5) a","C":"58 (2) b","D":"19 (4) a"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 29th May 1988, the Assembly was dissolved by the President by using the power acquired under Article 58(2)(b)whilethe Prime Minister of Pakistan to dissolve the National Assembly under Article 58 (1) read with Article 48(1) of the Constitution of the Islamic Republic of Pakistan.', 0, 0, 0, 1790967402800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0bf2e63ab6ec4813', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'In the presidential election of 1988, who was the supported by PPP and IJI?', '{"A":"General Zia Ul Haq","B":"Muhammad Khan Junejo","C":"Ghulam Ishaq Khan","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In the 1988 presidential election, PPP and IJI supported Ghulam Ishaq Khan.He won the election after the assassination of General Zia-ul-Haq, defeating PPP candidate Nawabzada Nasrullah Khan.In 1993, when Ghulam Ishaq Khan was President, Nawaz Sharif was the Prime Minister of Pakistan.He served as 7th President of PakistanIn office: 17 August 1988 – 18 July 1993On 29th May 1988, General Zia-ul-Haq dismissed the government of Muhammad Khan Junejo to extend military rule.', 0, 0, 0, 1790967402800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ad4113daa7eb1714', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the last ruler of the Mughal Dynasty?', '{"A":"Aurangzaib","B":"Babur","C":"Behadur Shah Zafar","D":"Akbar"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Behadur Shah Zafar was the last Mughal Emperor who was imprisoned by the English in Myanmar.Bahadur Shah Zafar was the last Mughal emperor of India (reigned 1837–57).He was a poet, musician, and calligrapher, more an aesthete than a political leader.Bahadur Shah Zafar was born October 24, 1775, in Delhi, IndiaBahadur Shah Zafar died November 7, 1862, in Rangoon [now Yangon], Myanmar.', 0, 0, 0, 1790967402800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9cbfdd3ce5843784', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', '________ was the founder and first Emperor of the great Mughal dynasty in India.', '{"A":"Babur","B":"Akbar","C":"Shah Jahan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Mughal Emperor: BaburFull Name: Zahir-ud-Din Muhammad BaburReign: 1526–1530Born: 14 February 1483, AndijanOrigin: Fergana, Central AsiaVictory: First Battle of Panipat (1526)Defeated: Ibrahim LodiDied: 26 December 1530, AgraAncestry: Timur & Genghis Khan', 0, 0, 0, 1790967402800) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a580c2751824d629', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Which Mughal king made Lahore his capital for 14 years?', '{"A":"Shah Jahan","B":"Akbar","C":"Aurangzeb","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Mughal emperor Akbar the Great made Lahore his capital for 14 years, from 1584 to 1598. During this time, Akbar also built the Lahore Fort and the city walls which had 13 gates.', 0, 0, 0, 1790967402832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b910ea2926f7aafe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'What is the minimum age specified in the constitution of Pakistan to become President of Pakistan?', '{"A":"35","B":"45","C":"65","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 45 is the minimum age specified in the constitution of Pakistan to become President of Pakistan in 1962.40 years was the age prescribed for president in the 1956 constitution.According to the constitution 1973, the minimum age for the President of Pakistan: are 45 Years.**Minimum age for President of Pakistan: 45 YearsMinimum age for Governor of Pakistan: 35 YearsMinimum age for PM of Pakistan: 35 YearsMinimum age for Senator of Pakistan: 30 YearsMinimum age for National Assembly Member: 25 Years', 0, 0, 0, 1790967402832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_96f05033e0275f2a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'When was Quaid-e-Azam become the president of first constituent assembly?', '{"A":"11 Aug 1947","B":"10 Aug 1947","C":"10 Aug 1946","D":"12 Aug 1947"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 11th August 1947, Quaid-i-Azam Muhammad Ali Jinnah was elected as the President of the Constituent Assembly of Pakistan.The first session of the Constituent Assembly of Pakistan was held on 10th August 1947 at the Sindh Assembly Building in Karachi.Liaquat Ali Khan headed after the death of Jinnah for three years and produced the Objectives Resolution.****', 0, 0, 0, 1790967402832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ab0e377a65b22ddc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The minister for Indian affairs approved the ______ on June, 1905.', '{"A":"Partition of Bengal","B":"Partition of Oudh","C":"Partition of Lucknow","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Partition of Bengal was approved by the British Indian government in June 1905.It was officially implemented on 16 October 1905.The partition was carried out by Lord Curzon.Bengal was divided into:East Bengal and Assam (Muslim-majority)West Bengal (Hindu-majority).Due to widespread opposition, the partition was annulled in 1911.', 0, 0, 0, 1790967402832) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0d2761197b5dac39', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who is the Current Federal Minister of Railways of Pakistan?', '{"A":"Shiekh Rashid Ahmed","B":"Muhammad Hanif Abbasi","C":"Sardar Awais Laghari","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The current Federal Minister of Railways in Pakistan is Muhammad Hanif Abbasi Sworn in on 07 March 2025 He replaced Sardar Awais Laghari Updated on 07 March 2025 Click here for reference', 0, 0, 0, 1790967402832) ON CONFLICT(id) DO NOTHING;
