INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5c83b1235625192f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Muhammad Rafiq Tarar was elected as president of Pakistan in which year___?', '{"A":"1996","B":"1998","C":"1997","D":"2000"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation He belongs to Pakistan Muslim leagueNawaz sharif was PM in 1998.Pervaiz Musharraf was chief executiveRafiaq Tarar tenure 1998-2001.', 0, 0, 0, 1790967403010) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d41e3c1c02128c3e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'The tomb of Mughal Emperor Jahangir is situated in which city?', '{"A":"Lahore","B":"Sialkot","C":"Peshawar","D":"Rawalpindi"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Tomb of Jahangir is a 17th-century mausoleum built for the Mughal Emperor Jahangir. Opened: 1627Burials: JahangirCompletion date: 1637', 0, 0, 0, 1790967403010) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5263caa45fe9accf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'According to 1973 constitution, who elects the president of Pakistan?', '{"A":"National Assembly","B":"Senate","C":"Provincial Assembly","D":"Both A & B","E":"All of the above"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zulifqar Ali Bhutto introduced 1973 constitution in Pakistan on August 14, 1973. According to 1973 constitution, Provincial assembly, National assembly, and senate elect the President. Whereas the prime minister is elect by only national assembly. Bicameral Legislature system was introduced for the first time in Pakistan in the constitution of 1973.', 0, 0, 0, 1790967403010) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9519f63f0963bb99', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Collectively how many Governor Generals ruled over Pakistan?', '{"A":"2","B":"3","C":"4","D":"5"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Governor-General of Pakistan # Name Date of Birth and Death 1 Muhammad Ali Jinnah 25 December 1876 – 11 September 1948 2 Sir Khawaja Nazimuddin 19 July 1894 - 22 October 1964 3 Ghulam Mohammad 20 April 1895 - 12 September 1956 4 Iskander Mirza 13 November 1899 - 12 November 1969', 0, 0, 0, 1790967403010) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3a70bde03fb8d4fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the first Prime Minister of Azad Kashmir?', '{"A":"Sardar Muhammad Ibrahim Khan","B":"Khan Abdul Hameed Khan","C":"Sardar Sikandar Hayat Khan","D":"Moulana Muhammad Yousaf","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Khan Abdul Hamid Khan served as 1st Prime Minister of Azad Kashmir from June 1975 to August 1977. He also served as President of Azad Jammu and Kashmir from 7 August 1964 to 7 October 1969. His brother Abdul Qayyum Khan served as Chief Minister of KPK and Interior Minister of Pakistan.', 0, 0, 0, 1790967403041) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_59ab3f3e68a11d74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'PM Imran Khan inaugurated Mohmand Dam on?', '{"A":"May 2","B":"May 3","C":"May 23","D":"May 3"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mohmand DamInaugurated by: Prime Minister Imran Khan on May 2, 2019Expected Completion: November 2024Type: Multi-purpose concrete-faced rock-filled damLocation: Swat River, Mohmand District, Khyber Pakhtunkhwa, PakistanConstruction Cost: ₨340 billion (US$1.2 billion)', 0, 0, 0, 1790967403041) ON CONFLICT(id) DO NOTHING;
