INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_80ed11a6bcd152fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'British Cabinet Mission visit India, Interim government formed at the Centre:', '{"A":"1945","B":"1946","C":"1947","D":"1944"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A Cabinet Mission came to India in 1946 in order to discuss the transfer of power from the British government to the Indian political leadership, with the aim of preserving India''s unity and granting its independence.', 0, 0, 0, 1790967403100) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c4659b69a5223c61', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Who was the Governor-General of India during the Sepoy Mutiny?', '{"A":"Lord Canning,","B":"Lord willing,","C":"Charles John Canning,Earl Canning,","D":"John canning,"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Indian Mutiny, also called Sepoy Mutiny or First War of IndependenceIndian Mutiny was a widespread but unsuccessful rebellion against British rule in India in 1857–59.Location: Agra Delhi India Kanpur LucknowParticipants: Mughal dynasty United KingdomCharles John Canning, Earl Canning was the governor-general of India during the Indian Mutiny of 1857.', 0, 0, 0, 1790967403100) ON CONFLICT(id) DO NOTHING;
