INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c690d099bd3a99a3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_leadership', 'Mughal Emperor Zahiruddin Babur was buried in which city?', '{"A":"Kabul","B":"Agra","C":"Delhi","D":"Ajmer Sharif","E":"Ferghana"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Babur died in Agra at the age of 47 on 5 January 1531.He was first buried in Agra but, as per his wishes, his mortal remains were moved to Kabul and reburied in Bagh-e Babur in Kabul sometime between 1539 and 1544.', 0, 0, 0, 1790967403195) ON CONFLICT(id) DO NOTHING;
