INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cd9b68e63d8c6593', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The current seats of senate are:', '{"A":"Ahsan Iqbal","B":"Yousaf Raza Gillani","C":"Raza Rabbani","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The current Chairman of the Senate is Yousaf Raza Gillani.• Party: Pakistan Peoples Party Parliamentarians (PPPP)• Oath Date: April 9, 2024• Tenure: March 2021 to March 2027• Constituency: Federal Capital**اس سوال کو وضاحت کے ساتھ ضرور پڑھیںThe current seats of senate are:', 0, 0, 0, 1790967403353) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9165195c34789b80', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'How many articles are the in 1973 constitution of Pakistan?', '{"A":"330","B":"250","C":"240","D":"280"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 1973 Constitution of Pakistan contains 280 articles.It is the current and permanent constitution of Pakistan.It came into effect on 14 August 1973.It was approved during the government of Zulfiqar Ali Bhutto.It provides the basic legal framework of the state.Additional information:1956 Constitution: 234 articles, 13 parts, 6 schedules1962 Constitution: 250 articles, 12 parts, 3 schedulesLast verified on 11-06-2026', 0, 0, 0, 1790967403353) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_800bde897fbf21af', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'How many seats did the National Assembly have at the time of the 1973 Constitution making?', '{"A":"150","B":"175","C":"210","D":"250"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation At the time of the 1973 Constitution making, the National Assembly had 210 seats (200 for general members and 10 reserved for women).This structure was part of the constitutional framework established in Pakistan.Additional information:The Current National Assembly seats are 336.Last verified on 27-09-2026', 0, 0, 0, 1790967403353) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_21f58483a12dff54', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'What is the Term of National Assembly of Pakistan?', '{"A":"5 Years","B":"3 Years","C":"2 Years","D":"1 Year"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Term: 5 YearsTotal Seats: 336General Seats: 266Reserved Seats for Women: 60Reserved Seats for Non-Muslims (Minorities): 10Last verified on 20-07-2026', 0, 0, 0, 1790967403353) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_18959e752000321d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'How many general seats are there in the National Assembly of Pakistan?', '{"A":"300","B":"266","C":"250","D":"None of the above"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation General Seats: 266Women Seats: 60Non-Muslim Seats: 10Total Seats: 336Old strength: 342 (reduced after KPK seats changed from 61 → 55)Constitution Reference: Article 51 (1) & 3(a)Additional information:Minimum age to contest NA election: 25 yearsSeats increase or decrease based on populationNational Assembly = Lower HouseSenate = Upper HouseLast verified on 18-01-2026', 0, 0, 0, 1790967403353) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_65b238904512626b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When first constitution of Pakistan was enforced?', '{"A":"8th June 1956","B":"23rd March 1956","C":"14th August 1956","D":"25th December 1956"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first constitution of Pakistan was enforced on March 23, 1956Additional informationList of the Constitution of Pakistan 1947 to dateFirst: 1956 ConstitutionAdoption Date: 23rd March 1956Prime Minister: Chaudhry Muhammad AliPresident: Iskander MirzaSecond: 1962 ConstitutionAdoption Date: 8th June 1962Prime Minister: Muhammad Ayub Khan (also President at the time)Third: 1973 ConstitutionAdoption Date: 12th April 1973Prime Minister: Zulfikar Ali BhuttoPresident: Fazal Ilahi ChaudhryLast updated by NA on 25-April-2026', 0, 0, 0, 1790967403353) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_81fb0fa777390b50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The right of separate electorate was given to the Muslims under the Indian Councils Act of _____?', '{"A":"1910","B":"1912","C":"1908","D":"1909"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indian Councils Act 1909, also called the Morley-Minto Reforms, introduced separate electorates for Muslims.Additional information:Date of introduction: 12 March 1909Total members in Central Legislative Council: 60Muslim reserved seats: 527 members were to be elected from different constituencies.Nehru Report (28 August 1928) rejected the demand for separate electorate.Last verified on 01-04-2026', 0, 0, 0, 1790967403353) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3071287aca7cac8e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The chief characteristics of Govt of India Act 1935 was _____?', '{"A":"Provincial Government at the center","B":"Federal  Government at the center","C":"Interim Government at the center","D":"Provincial autonomy"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Government of India Act 1935 was a major constitutional reform introduced by the British Parliament.Its most important implemented feature was provincial autonomy.It abolished dyarchy in the provinces and gave provinces greater authority over their own administration.The proposed federation at the center was never fully implemented.Last verified on 08-09-2026', 0, 0, 0, 1790967403353) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_498f1ac699c5cd59', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'FATA was merged with KPK under which constitutional amendment?', '{"A":"22nd","B":"23rd","C":"24th","D":"25th"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Constitutional Amendment: 25th AmendmentMerger Date: 24th May 2018FATA Stands for: Federally Administered Tribal AreasMerged with: Khyber Pakhtunkhwa (KPK)Main Purpose: Integration of FATA into Pakistan''s provincial and constitutional frameworkLast verified on 06-07-2026', 0, 0, 0, 1790967403400) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2f938fc8b3320921', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which kind of system of government was introduced in 1962 constitution?', '{"A":"Presidential","B":"Autonomous","C":"Confederate","D":"Bicameral"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1962 ConstitutionSystem: Presidential SystemIntroduced by: General Ayub KhanLegislature: National Assembly + Provincial AssembliesElection system: Indirect (Basic Democracies)Additional information:1956 ConstitutionSystem: Parliamentary SystemHead of State: President (ceremonial)Head of Government: Prime Minister1973 ConstitutionHead of Government: Prime Minister (executive authority)System: Parliamentary System (Federal Parliamentary Democracy)Head of State: President (ceremonial role)Last verified on 23-06-2026', 0, 0, 0, 1790967403400) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_271d3760d46d4462', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Concurrent legislative list of the Constitution of Pakistan, 1973 was omitted by ______?', '{"A":"18th amendment","B":"8th amendment","C":"15th amendment","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 18th Constitutional Amendment omitted the Concurrent Legislative List.It was passed by Parliament in April 2010.The amendment transferred many legislative powers from the Federal Government to the Provinces.It strengthened provincial autonomy under the Constitution.President who gave assent: Asif Ali ZardariThe Concurrent Legislative List was removed from the Fourth Schedule of the Constitution.Last verified on 02-08-2026', 0, 0, 0, 1790967403400) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_42a090ea20b26347', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'How many articles were there in the 1962 Constitution?', '{"A":"250","B":"234","C":"280","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1962 Constitution: 250 articles, 12 parts, 3 schedulesIt was introduced by Ayub Khan.It introduced a presidential system of government.Additional information:1956 Constitution: 234 articles, 13 parts, 6 schedules1973 Constitution: 280 articles, 7 schedules + Objective ResolutionLast verified on 01-05-2026', 0, 0, 0, 1790967403400) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cb85eaf146a49589', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', '1st Martial Law imposed by Iskandar Mirza?', '{"A":"1956","B":"1957","C":"1958","D":"1960"}', 'C', NULL, 0, 0, 0, 1790967403400) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5a9e938743356cf9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who abrogated 1956 constitution?', '{"A":"Ayub Khan","B":"Yahya khan","C":"Iskander Mirza","D":"Tikka khan"}', 'C', NULL, 0, 0, 0, 1790967403400) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cabb6bd31f4e1273', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The first Martial Law was imposed on Pakistan under leadership of?', '{"A":"General Yahya Khan","B":"General Ayub Khan","C":"General Pervez Musharraf","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan’s first Martial Law was imposed under the control of General Ayub Khan.Martial Law imposed: 7 October 1958President at the time: Iskandar Ali MirzaPrime Minister: Feroz Khan NoonAdditional information:Sr# Martial Law NumberDate of Martial LawMartial Law Implemented by1First Martial Law7th October 1958Iskandar Mirza22nd Martial Law25th March 1969General Yahya Khan33rd Martial Law25th July 1977General Zia ul Haq44th Martial Law12th October 1999General Pervaiz Musharraf Last verified on 22-06-2026', 0, 0, 0, 1790967403400) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_260f4127fc0bedc2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Urdu was declared Official Language of Pakistan under which article of the constitution 1973?', '{"A":"Article 252","B":"Article 251","C":"Article 253","D":"Article 250"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Urdu was declared Official Language of Pakistan under article 251 of the constitution 1973.The 1973 Constitution contained: 280 articles 07 schedules with Objective Resolution.12 chapters Effective date: 14 August 1973Drafted by the Government of Zulfiqar Ali BhuttoThe Constitution declared Pakistan an Islamic Republic and Islam as the state religion.Last verified on 05-08-2026', 0, 0, 0, 1790967403400) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4e5b79ad5eafcd6b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which act introduced Diarchy in the provinces?', '{"A":"Government of India Act 1919","B":"Rowlett Act","C":"Indian Independence Act 1947","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Introduced by the Government of India Act 1919.Diarchy = system of shared rule in provinces under British India.Meaning: “Double system of government” – two heads responsible for administration.Introduced by Edwin Samuel Montagu and Lord Chelmsford.Ended by Government of India Act 1935, which established provincial autonomy.Last verified on 23-01-2026', 0, 0, 0, 1790967403447) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_61c0e238eda6345f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Iskander Mirza abrogated the 1956 Constitution and dissolved assemblies on?', '{"A":"7th October 1958","B":"7th October 1959","C":"7th October 1960","D":"7th October 1961"}', 'A', NULL, 0, 0, 0, 1790967403447) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d5c11f76cbb5f9f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The Legal Framework Order (LFO) 1970 was issued by ______?', '{"A":"Yahya Khan","B":"Zulifqar Ali Bhutto","C":"Zia ul Haq","D":"Pervez Musharraf"}', 'A', NULL, 0, 0, 0, 1790967403447) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_05c5cf1213496d03', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When was the Constitution of 1973 enforced?', '{"A":"14th August 1973","B":"14th September 1973","C":"14th October 1973","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Enforcement date: 14 August 1973Introduced by: Zulfikar Ali BhuttoLegislature: Bicameral (National Assembly + Senate)President elected by: National Assembly and SenatePrime Minister elected by: National AssemblyAdditional information:1956 Constitution → 23 March 19561962 Constitution → 8 June 1962Last verified on 06-07-2026', 0, 0, 0, 1790967403447) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a8a88c59b49268ad', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'By which Article was the Objectives Resolution made a substantive part of the Constitution of Pakistan?', '{"A":"Article 2A","B":"Article 2","C":"Article 160","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article: Article 2AObjectives Resolution Passed: 12 March 1949Made Part of Constitution: 1985Constitutional Amendment: 8th AmendmentPurpose: Provides the constitutional and ideological foundation of Pakistan.Last verified on 10-07-2026', 0, 0, 0, 1790967403447) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_505c4008e9da8228', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Right to information is provided in Article ____ of the Constitution.', '{"A":"15","B":"19A","C":"12B","D":"11"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 19A of the 1973 Constitution of Pakistan provides the Right to Information (RTI).It allows every citizen to access information on matters of public importance.This right is subject to reasonable restrictions under the law.It was added to strengthen transparency and accountability.Additional information:Article 9 → Right to lifeArticle 14 → Dignity of manArticle 19 → Freedom of speechArticle 25 → Equality of citizensLast verified on 13-05-2026', 0, 0, 0, 1790967403447) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d267f899c92282e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The Legal Framework Order (LFO) 2002 was issued by _____?', '{"A":"Pervaiz Musharraf","B":"Rafique Tarar","C":"Khalid Mirage","D":"None of these"}', 'A', NULL, 0, 0, 0, 1790967403447) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a752345d95725f5f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Bicameral Legislature system was introduced for the first time in Pakistan in which Constitution?', '{"A":"Constitution of 1973","B":"Constitution of 1956","C":"Constitution of 1962","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Bicameral means a two-house legislature.It was introduced in the 1973 Constitution.The Parliament consists of:National Assembly (Lower House)Senate (Upper House)The National Assembly represents the population.The Senate gives equal representation to all provinces.This system strengthens democracy and federalism.Additional information:1956 → Unicameral (Only National Assembly)1962 → UnicameralLast updated 17 july 2026 by NA', 0, 0, 0, 1790967403447) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7bf8feb744acf83f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The "Eighth Amendment" to the Constitution of Pakistan was passed in which year?', '{"A":"1984","B":"1985","C":"1986","D":"1989"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Passed by the National Assembly of Pakistan in 1985.Received Presidential assent: 9 November 1985.Published in the official Gazette: 11 November 1985.Enforced during General Zia-ul-Haq''s rule.Gave the President greater powers.Allowed the President to dissolve the National Assembly under Article 58(2)(b).Allowed dismissal of the Prime Minister and elected government.Repealed in 1997 by the Thirteenth Amendment.Last updated by NA on 16-07-2026', 0, 0, 0, 1790967403481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5c97bf96265a8c6e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Article 19 of constitution of Pakistan 1973 is about _______?', '{"A":"Fundamental Rights","B":"Freedom of Speech and Expression","C":"Right of Education","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 19 of the Constitution of Pakistan (1973) guarantees Freedom of Speech and Expression.It gives every citizen the right to express opinions and ensures freedom of the press.These rights are subject to reasonable restrictions imposed by law.Restrictions may apply for the glory of Islam, national security, public order, decency, morality, and the integrity of Pakistan.Last verified on 10-07-2026', 0, 0, 0, 1790967403481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_080615729da0c33d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which article of the Constitution of Pakistan 1973 deals with the National Economic Council?', '{"A":"Article 155","B":"Article 157","C":"Article 156","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article: 156Constitution: Constitution of Pakistan, 1973Council: National Economic Council (NEC)Chairman: Prime Minister of PakistanMain Function: Formulate economic policies and promote balanced national developmentLast verified on 10-07-2026', 0, 0, 0, 1790967403481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_738bc6be7c59b1fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The 18th Constitutional Amendment Act was passed on _____?', '{"A":"19th April 2010","B":"8th April 2010","C":"10th April 2010","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Signed into law: 19 April 2010National Assembly approval: 8 April 2010Senate approval: 15 April 2010Main change: Removed President’s power to dissolve ParliamentLast verified on 10-05-2026', 0, 0, 0, 1790967403481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1a31ad8b304a0734', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which constitutional article provides for the Fundamental Rights of citizens in Pakistan?', '{"A":"Article 8–28","B":"Article 32–45","C":"Article 40–60","D":"Article 90–120"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fundamental Rights of citizens in Pakistan are guaranteed under Articles 8 to 28 of the 1973 Constitution.These articles protect citizens’ basic freedoms and equality before law.They ensure rights like freedom of speech, religion, and fair trial.They also protect life, dignity, and personal liberty.Last verified on 11-06-2026', 0, 0, 0, 1790967403481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_026e6400052548fe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who was the First female Speaker of National Assembly of Pakistan?', '{"A":"Fahmida Mirza","B":"Ayesha Mirza","C":"Sofia Mirza","D":"Pakeeza Mirza"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Name: Fahmida MirzaTenure: 2008–2013Votes received: 249Opponent votes (Muhammad Israr Tareen): 70Party: Pakistan Peoples Party (PPP)Additional information:The first Speaker of the National Assembly was Quid-e-Azam Muhammad Ali Jinnah.Last verified on 10-06-2026', 0, 0, 0, 1790967403481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bab12712f7d1ea20', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The second constitution (1962) of Pakistan was enforced on?', '{"A":"14th August 1973","B":"8th  June 1962","C":"23rd March 1956","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan''s second Constitution was enforced on 8 June 1962.It was introduced during the rule of Field Marshal Muhammad Ayub Khan.It introduced a presidential system instead of a parliamentary system.Additional information:23 March 1956 – First Constitution enforced.14 August 1973 – Third (current) Constitution enforced.Last verified on 07-07-2026', 0, 0, 0, 1790967403481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2f4b9bf6fde238cc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Total amendments in the 1973 constitution of Pakistan?', '{"A":"20","B":"22","C":"25","D":"27"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Total amendments: 27Constitution adopted: 14 August 1973First Amendment: 1974Major Amendment: 18th Amendment (2010) – strengthened provincial autonomy.Latest Amendment: 27th AmendmentLast verified on 10-06-2026', 0, 0, 0, 1790967403481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1a4f3f3982eff084', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When was the 18th Amendment Bill of the Constitution passed by the National Assembly?', '{"A":"April 8, 2010","B":"April 15, 2010","C":"April 19, 2010","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation National Assembly approval: 8 April 2010Senate approval: 15 April 2010Signed into law: 19 April 2010Main change: Removed President’s power to dissolve ParliamentLast verified on 10-05-2026', 0, 0, 0, 1790967403514) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6ed8980d4724435c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Term and tenure of Senate membership are _____ years in Pakistan.', '{"A":"Four years","B":"Five years","C":"Six years","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Members of the Senate of Pakistan serve a 6-year term.One-half of the Senators retire every 3 years, ensuring continuity in the Senate.Additional information:Details of Seats of Senate of PakistanProvince/TerrotoryGeneralTechnocrat/UlemaWomenNon-MuslimTotalSindh1444123Punjab1444123Balochistan1444123KPK1444123ICT211-4Grand Total581717496Last verified on 02-07-2026', 0, 0, 0, 1790967403514) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2f27185eb818272a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which kind of system of Government was introduced in 1973 constitution?', '{"A":"Presidential","B":"Parliamentary (Bicameral)","C":"Autonomous","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 1973 Constitution introduced a Parliamentary system of government with a Bicameral Legislature in Pakistan.The Constitution of 1973 is the supreme law of Pakistan.It was introduced by Zulfikar Ali Bhutto.It came into effect on 14 August 1973.The system gave executive authority to the Prime Minister and Parliament.Last verified on 02-07-2026', 0, 0, 0, 1790967403514) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8fcf00fcaf27a811', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When First martial law was imposed in Pakistan?', '{"A":"October 7 1958","B":"October 7 1959","C":"October 7 1960","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Martial Law imposed: 7 October 1958Pakistan’s first Martial Law was imposed under the control of General Ayub Khan.President at the time: Iskandar Ali MirzaPrime Minister: Feroz Khan NoonAdditional information:Sr# Martial Law NumberDate of Martial LawMartial Law Implemented by1First Martial Law7th October 1958Iskandar Mirza22nd Martial Law25th March 1969General Yahya Khan33rd Martial Law25th July 1977General Zia ul Haq44th Martial Law12th October 1999General Pervaiz Musharraf Last verified on 22-06-2026', 0, 0, 0, 1790967403514) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b7c4686d9ce63cf0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When National Assembly and Senate are referred together, they are termed as ______?', '{"A":"Majilis-e-Shoora","B":"Parliament","C":"Majlis-e-Shoora (Parliament)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The National Assembly and Senate together are called Majlis-e-Shoora (Parliament) of Pakistan.It is the bicameral (two-house) legislature of Pakistan.The term Majlis-e-Shoora is mentioned in the Constitution of Pakistan, 1973.It makes laws, approves the budget, and represents the people and provinces.The Parliament consists of the President and two Houses.Last verified on 25-06-2026', 0, 0, 0, 1790967403514) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_816f298c1223ca57', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'What is the minimum age of voter required according to the 1973 constitution?', '{"A":"16 years","B":"18 years","C":"11 years","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Voter minimum age: 18 yearsCitizenship: Citizen of Pakistan requiredElectoral requirement: Name included in electoral rollRelevant law: Article 51/51A & Election laws of PakistanAdditional information:MNA (National Assembly member): Minimum 25 yearsSenator: Minimum 30 yearsPresident of Pakistan: Minimum 45 yearsLast verified on 24-06-2026', 0, 0, 0, 1790967403514) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_12a2dc07cd724e49', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'What is the minimum age of Senator under 1973 Constitution?', '{"A":"30 years","B":"25 years","C":"35 years","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Under the 1973 Constitution of Pakistan, the minimum age for a Senator is 30 years.The condition is mentioned in Article 62 of the Constitution.Additional information:Member National Assembly (MNA): 25 yearsPrime Minister: Must be an MNA (minimum 25 years)President of Pakistan: 45 yearsLast verified on 12-01-2026', 0, 0, 0, 1790967403514) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_84d3e45349f8fe6f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'According to the Article _____ of the Constitution of Islamic Republic of Pakistan, Islam shall be the state religion of Pakistan.', '{"A":"Article 2","B":"Article 228","C":"Article 31","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Constitution of Pakistan clearly defines the state religion.Under Article 2, Islam is declared the state religion of Pakistan.This provision was included in the Constitution of 1973.It reflects the Islamic identity of the state.It guides the overall legal and ideological framework of Pakistan.Last verified on 30-04-2026', 0, 0, 0, 1790967403514) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9e74fe410d1454bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Senate of Pakistan consists of how many members?', '{"A":"100","B":"96","C":"104","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation After 18th Amendment Strength: 104 membersProvincial Representation: 23 members per provinceAfter 2024 Elections: 96 membersDetails of Seats of Senate of PakistanProvince/TerrotoryGeneralTechnocrat/UlemaWomenNon-MuslimTotalSindh1444123Punjab1444123Balochistan1444123KPK1444123ICT211-4Grand Total581717496Last verified on 03-05-2026', 0, 0, 0, 1790967403547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8026d751611c6c73', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Islam was declared "State Religion" of Pakistan in which constitution?', '{"A":"1956","B":"1962","C":"1973","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Enforced: 14 August 1973Prime leader: Zulfiqar Ali BhuttoState name: Islamic Republic of PakistanStructure: 280 Articles, 12 ChaptersLast verified on 20-06-2026', 0, 0, 0, 1790967403547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c2e6069d82aa3322', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'In the 1956 constitution, what official name was given to Pakistan?', '{"A":"United States of Pakistan","B":"Republic of Pakistan","C":"Islamic Republic of Pakistan","D":"Islamic Pakistan"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date Promulgated: 23 March 1956Official Name: Islamic Republic of PakistanForm of Government: Parliamentary systemLegislature: UnicameralGovernor-General replaced by: PresidentParliament structure: Federal system with East & West Pakistan parityAdditional information:It has 234 articles, 13 parts, 6 schedules.Urdu and Bengali declared national languages.The constitution remained in force for 2 years, 6 months, and 14 days.It was abrogated by Iskander Mirza in 1958.Last verified on 17-05-2026', 0, 0, 0, 1790967403547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_259a49851e4f9a37', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The National Finance Commission (NFC) Award is constituted under which Article of the 1973 Constitution of Islamic Republic of Pakistan?', '{"A":"Article 167","B":"Article 160","C":"Article 162","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The National Finance Commission (NFC) Award is constituted under Article 160 of the Constitution of Pakistan.Article 160 deals with the distribution of financial resources between the Federation and Provinces.The President constitutes the NFC after intervals as required.Additional information:The first NFC Award was announced in 1974.The 7th NFC Award (2010) is a major milestone.Because it increased the provincial share in divisible pool taxes.Last verified on 14-06-2026', 0, 0, 0, 1790967403547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_016c497bb3df2943', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'According to which article of constitution of 1973, every citizen shall have the right to freedom of speech and expression?', '{"A":"Article 6","B":"Article 19","C":"Article 16","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 19 of the 1973 Constitution of Pakistan guarantees freedom of speech and expression.It gives citizens the right to express opinions and share information.However, this freedom is subject to reasonable restrictions under law.The Constitution of Pakistan was enforced on 14 August 1973.Additional information:The 1973 Constitution was framed under the leadership of Zulfikar Ali Bhutto.Pakistan’s Constitution declares Islam as the state religion under Article 2.Last verified on 13-05-2026', 0, 0, 0, 1790967403547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2debad2e082ae4c1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Indian Independence Act was enforced on?', '{"A":"14th August 1947","B":"13th August 1947","C":"16th August 1947","D":"15th August 1947"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indian Independence Act 1947 was enforced on 15 August 1947.Royal Assent: 17 July 1947Result: Partition of India & creation of PakistanDominions formed: India and PakistanLast verified on 11-06-2026', 0, 0, 0, 1790967403547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8c5be5ec9d352755', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'India revoked article 370 on _______?', '{"A":"5th August 2019","B":"10th June 2019","C":"6th May 2019","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 5th August 2019, India revoked Article 370.This granted special status to Jammu and Kashmir.Result: Split into Jammu & Kashmir and Ladakh (UTs)Last verified on 11-06-2026', 0, 0, 0, 1790967403547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f31c5fea38511e82', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The constitution of 1956 was made under which Act?', '{"A":"Indian Independence Act, 1947","B":"Indian Independence Act, 1935","C":"Indian Independence Act, 1942","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Constitution of Pakistan was enforced on 23 March 1956.It was framed under the Indian Independence Act, 1947, which provided legal authority to Pakistan after independence.It replaced the Government of India Act, 1935 as the interim constitutional framework.Additional information:The 1956 Constitution introduced a parliamentary system in Pakistan.Iskander Mirza was the first President under the 1956 Constitution.Last verified on 12-05-2026', 0, 0, 0, 1790967403547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f0310307a180cefd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which forests act as barriers against cyclones?', '{"A":"Alpine forests","B":"Mangrove forests","C":"Evergreen forests","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mangrove forests act as barriers against cyclones.Mangroves reduce erosion by trapping sediments, stabilizing the coastal zone and thus protecting the coast from storm surges and cyclones.Mangroves in Pakistan are found along the coastline of Sindh and Balochistan.Last verified on 06-06-2026', 0, 0, 0, 1790967403578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9ff2a204a4552b0e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who becomes the first female Judge of the Supreme Court of Pakistan?', '{"A":"Justice Ayesha Malik","B":"Justice Syeda Tahira Safdar","C":"Justice Ashraf Jahan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Justice Ayesha Malik became the first female judge of the Supreme Court of Pakistan.She was sworn in on 24 January 2022 by Chief Justice Gulzar Ahmed.Previously, she served at Lahore High Court (March 2012 – Jan 2022).Additional information:Appointed by: President Arif AlviTenure: Until June 2031Supreme Court judges total: 17Retirement age: Supreme Court – 65, High Court – 62Last verified on 18-03-2026', 0, 0, 0, 1790967403578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c934f93d5c29f1b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The National Assembly of Pakistan has?', '{"A":"270 general seats, 60 women seats and 12 non-Muslim seats.","B":"270 general seats, 62 women seats and 10 non-Muslim seats.","C":"272/266 general seats, 60 women seats and 10 non-Muslim seats.","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Total Seats: 342/336General Seats: 272/266Women Reserved Seats: 60Non-Muslim Reserved Seats: 10National Assembly term = 5 yearsLower House of Parliament = National AssemblyLast verified on 26-05-2026', 0, 0, 0, 1790967403578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3b5568c95c6dd9c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who enforced martial law for the second time in the country?', '{"A":"Gen Yahya","B":"Gen Ayub","C":"Gen Zia","D":"Gen Teka Khan"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Second Martial Law: 25 March 1969Imposed By: General Yahya KhanBefore him: President Ayub Khan resignedSystem Abolished: 1962 ConstitutionAdditional information:1st Martial Law (7th October 1958): Iskandar Mirza / Ayub Khan era3rd Martial Law (5th July 1977): General Zia-ul-Haq4th Martial Law (12th October 1999): General Pervez MusharrafLast verified on 16-05-2026', 0, 0, 0, 1790967403578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1dbe3a7399afcc50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Quaid-e-Azam Muhammad Ali Jinnah started his law practice in _____?', '{"A":"Bombay","B":"Karachi","C":"London","D":"Delhi"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation At age 20, Quaid-e-Azam Muhammad Ali Jinnah began his law practice in 1896 in Bombay (now Mumbai).After completing his legal studies in London.He was the only Muslim barrister in the city at the time.Last verified on 16-05-2026', 0, 0, 0, 1790967403578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_12e6a217f37569fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The British Parliament announced the Independence Act on?', '{"A":"14 July 1947","B":"15 July 1947","C":"16 July 1947","D":"18 July 1947"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Passed: July 1947Royal Assent: 18 July 1947Independence Date: 14–15 August 1947Last Viceroy: Lord MountbattenPakistan’s Governor-General: Muhammad Ali JinnahPakistan’s First Prime Minister: Liaquat Ali KhanIndia’s First Prime Minister: Jawaharlal NehruLast verified on 14-05-2026', 0, 0, 0, 1790967403578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c7fd4b3b43b97af2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Freedom of Trade, Business or Profession is the basic concept of which Article of our Constitution (1973)?', '{"A":"Article 18","B":"Article 16","C":"Article 17","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 18 – Freedom of trade, business or professionAdditional information:Article 17 – Freedom of associationArticle 16 – Freedom of assemblyArticle 19 – Freedom of speechArticle 25 – Equality of citizensLast verified on 11-05-2026', 0, 0, 0, 1790967403578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0980b00d1deafd4b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Article 50 of the Constitution of Pakistan 1973, the Parliament of Pakistan consisting of _____?', '{"A":"Senate of Pakistan","B":"President and Two House","C":"President of Pakistan","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Constitution of 1973 defines the structure of Pakistan’s Parliament.Parliament is the supreme legislative body of the country.It represents the federal system of governance.It includes two houses plus the head of state.Article 50 clearly defines its composition.Last verified on 11-05-2026', 0, 0, 0, 1790967403578) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_276b858b44f2bb1c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Equality before law is guaranteed under which Article of the Constitution of Pakistan?', '{"A":"Article 25(1)","B":"Article 23(1)","C":"Article 24(1)","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 25(1) ensures equality of all citizens before law.It prohibits discrimination on the basis of sex or other grounds.Additional information:Article 10-A – Right to fair trialArticle 9 – Security of personArticle 14 – Dignity of manArticle 4 – Right of individuals to be dealt with in accordance with lawLast verified on 11-05-2026', 0, 0, 0, 1790967403608) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d83370d9b28d7858', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The PECA Act deals with _____?', '{"A":"Environmental Protection","B":"Taxation Laws","C":"Electronic and Cybercrimes","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Full Form: Prevention of Electronic Crimes ActYear: 2016Country: PakistanMain Purpose: Prevent cybercrime and electronic offensesRelated Authority: Federal Investigation Agency (Cyber Crime Wing)Last verified on 11-05-2026', 0, 0, 0, 1790967403608) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7085a28b04986a88', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The Parliament of Pakistan is officially named ______?', '{"A":"Majlis-e-Shoora","B":"Senate","C":"Cabinet","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Majlis-e-Shura is the Parliament of Pakistan.It consists of two houses:National Assembly (Lower House - 336 Seats)Senate (Upper House - 96 Seats)It is the main legislative body that makes laws in Pakistan.Constitutional Article: Article 50 of the Constitution of Pakistan (1973)Last verified on 10-05-2026', 0, 0, 0, 1790967403608) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9a22f9ac7d6ae7f9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which article of the Constitution 1973 of the Pakistan ensures fair trial of due process?', '{"A":"10","B":"10A","C":"110","D":"110A"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Constitution of Pakistan 1973 guarantees fundamental rights to citizens.Article 10-A ensures the right to fair trial and due process.This article was added through the 18th Constitutional Amendment in 2010.It applies to both civil rights and criminal cases.It strengthens justice and protects individuals from unfair treatment.Last verified on 11-05-2026', 0, 0, 0, 1790967403608) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0ab5e4e003981829', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Under what amendment to the constitution of Pakistan, maximums provincial autonomy is ensured?', '{"A":"20th","B":"18th","C":"17th","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 18th Constitutional Amendment passed in April 2010.It removed the President’s power to dissolve Parliament (Article 58(2)(b)).It strengthened the Council of Common Interests (CCI).Last verified on 11-05-2026', 0, 0, 0, 1790967403608) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3c764d95401ad5cf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'In which year the first constitution of Pakistan was enforced?', '{"A":"1951","B":"1956","C":"1962","D":"1973"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first constitution of Pakistan was enforced on March 23, 1956Additional informationList of the Constitution of Pakistan 1947 to dateFirst: 1956 Constitution Adoption Date: 23rd March 1956 Prime Minister: Chaudhry Muhammad Ali President: Iskander Mirza Second: 1962 Constitution Adoption Date: 8th June 1962 Prime Minister: Muhammad Ayub Khan (also President at the time) Third: 1973 Constitution Adoption Date: 12th April 1973 Prime Minister: Zulfikar Ali Bhutto President: Fazal Ilahi ChaudhryLast updated by NA on 25-April-2026', 0, 0, 0, 1790967403608) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3d052a445a5b5c42', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The Prevention of Electronic Crimes Act was passed in Pakistan in the year?', '{"A":"2016","B":"2015","C":"2013","D":"2014"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Prevention of Electronic Crimes Act (PECA) was passed in Pakistan in 2016.It is an Act to prevent cyber crimes in Pakistan.Enacted by: National Assembly of Pakistan.Assented to by: 1 August 2016.Signed by: Mamnoon Hussain.Last verified on 10-05-2026', 0, 0, 0, 1790967403608) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d5433f68ff36c8bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Airports Security Force (ASF) was raised under ASF Act _______?', '{"A":"1974","B":"1975","C":"1976","D":"1977"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Establishment Year: 1976Act Passed: 1975Act Number: LXXVII of 1975Initial Department: Civil Aviation DepartmentCurrent Status: Federal security agencyLast verified on 10-05-2026', 0, 0, 0, 1790967403608) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_78606d1c278d84b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The Constitution of Pakistan 1956 introduced a which legislature/system?', '{"A":"Bicameral","B":"Unicameral","C":"Both A and B","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Constitution of Pakistan 1956 introduced a unicameral legislature.It was called the Parliament of Pakistan.It consisted of only one house (National Assembly).Additional information:1962 Constitution: Presidential system with changes in structure1973 Constitution: Bicameral Parliament (National Assembly + Senate)Last verified on 01-05-2026', 0, 0, 0, 1790967403639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2f2fc66835567f37', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The court language of the Mughals in India was _______?', '{"A":"Urdu","B":"Hindi","C":"Arabic","D":"Persian"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The official court language of the Mughal Empire was Persian.It was used in administration, literature, and royal communication.Mughal rulers adopted Persian from earlier Islamic traditions.It remained dominant until the British period.It influenced the development of Urdu language.Last verified on 01-05-2026', 0, 0, 0, 1790967403639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e0b01755a27b5ba0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The Indian Councils Act (Minto-Morley Reforms) was enacted into law in ____?', '{"A":"1900","B":"1905","C":"1909","D":"1911"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indian Councils Act 1909, also called the Morley-Minto Reforms, introduced separate electorates for Muslims.Additional information:Date of introduction: 12 March 1909Total members in Central Legislative Council: 60Muslim reserved seats: 527 members were to be elected from different constituencies.Nehru Report (28 August 1928) rejected the demand for separate electorate.Last verified on 01-04-2026', 0, 0, 0, 1790967403639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8e95199484e40b4d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Indian Councils Act of 1909 is also known as?', '{"A":"Minto-Warren Reforms","B":"Minto-Cornwallis Reforms","C":"Minto-Morley Reforms","D":"Minto-Hastings Reforms"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indian Councils Act 1909, also called the Morley-Minto Reforms, introduced separate electorates for Muslims.Additional information:Date of introduction: 12 March 1909Total members in Central Legislative Council: 60Muslim reserved seats: 527 members were to be elected from different constituencies.Nehru Report (28 August 1928) rejected the demand for separate electorate.Last verified on 01-04-2026', 0, 0, 0, 1790967403639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2537f65148f1ca9b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Article 35 A was abrogated by Modi Government on 5th August 2019 to indulge in?', '{"A":"Demographic engineering","B":"Conduct of Plebiscite","C":"Ending warfare","D":"Respecting International Law"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Article 35A was revoked on 5 August 2019 by the Government of India.The move was widely viewed as enabling demographic changes in Kashmir.It removed special rights related to residency and property ownership.The decision was linked with revocation of Article 370.It created significant political and regional tensions.Last verified on 29-04-2026', 0, 0, 0, 1790967403639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_87f8baeb2f6f8d27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The 26th amendment was passed by national assembly of Pakistan on 13 May in which year?', '{"A":"2016","B":"2018","C":"2017","D":"2024"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Twenty-Sixth Amendment to the Constitution of Pakistan was passed by the parliament between 20 and 21 October 2024.Passed by the National Assembly of PakistanAssented to by: President Asif Zardari', 0, 0, 0, 1790967403639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6372226357aa1cb1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which of the following resolutions is the preamble of the 1973''s constitution of Pakistan?', '{"A":"Bogra Formula (1953)","B":"Lahore Resolution (1940)","C":"Objective Resolution (1949)","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The preamble of the Constitution of Pakistan is based on the Objectives Resolution.It was passed on 12 March 1949 by the Constituent Assembly of Pakistan.It was presented by Prime Minister Liaquat Ali Khan.It became part of the Constitution through Article 2A (1985).Last verified on 13-04-2026', 0, 0, 0, 1790967403639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2954261f7856795f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Pakistan became Islamic Republic in which constitution _____?', '{"A":"1956","B":"1973","C":"1962","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan became an "Islamic Republic" in its 1956 constitution.This constitution was the first to declare Pakistan as an Islamic Republic.It is reflecting the country''s identity as a democratic state founded on the principles of Islam.Additional information:The constitution was adopted on March 23, 1956.The 1956 Constitution was abrogated in 1958.When President Iskander Mirza imposed martial law and declared himself the Chief Martial Law Administrator.Last verified on 23-03-2026', 0, 0, 0, 1790967403639) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8d510e12e4cfe327', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When Punjab assembly introduced Protection of Women against Violence Act?', '{"A":"29 February 2016","B":"24 February 2016","C":"26 February 2016","D":"22 February 2016"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Protection of Women against Violence Act was passed by the Punjab Assembly on 24 February 2016.It was assented to by the Governor of the Punjab on 26 February 2016.It was published in the Punjab Gazette, dated 29 February 2016.Last verified on 01-04-2026', 0, 0, 0, 1790967403668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_78fd62e911984af6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When was Federal Shariat Court established in Pakistan?', '{"A":"1977","B":"1980","C":"1988","D":"1990"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Federal Shariat Court (FSC)Established: 1980Total Judges: 8Ulema Judges: 3 (mandatory)Tenure of Judges: 3 years (extendable by the President)Founder: General Muhammad Zia-ul-HaqLast verified on 18-01-2026', 0, 0, 0, 1790967403668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_96f4412d61f11402', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'In constitution 1973 what number of seats in Senate was set?', '{"A":"115 Seats","B":"120 Seats","C":"100 Seats","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Initial Senate seats (1973): 100Later changes:Increased to 104 seats (including FATA & minorities)After reforms (25th Amendment), adjusted againCurrent structure: around 96 seats (after FATA merger)Term of Senators: 6 yearsHalf members retire every: 3 yearsOriginally, the membership of Senate was a were 45 that was raised to 63, in 1977 and 87 in 1985.Last verified on 23-03-2026', 0, 0, 0, 1790967403668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_42e1965c04602e3f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'How many seats of Senate (Upper House) are there in Pakistan?', '{"A":"104","B":"96","C":"102","D":"100"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Current Members of Senate: 96 SenatorsPrevious Strength: 100 members (2021)Earlier Strength: 104 members (after 18th Amendment in 2012)The reduction in seats occurred after the merger of FATA into Khyber Pakhtunkhwa.Term of Members: 6 yearsRetirement System: ½ members retire every 3 yearsDetails of Seats of Senate of PakistanProvince/TerritoryGeneralTechnocrat/UlemaWomenNon-MuslimTotalSindh1444123Punjab1444123Balochistan1444123KPK1444123ICT211-4Grand Total581717496Last verified on 14-03-2026', 0, 0, 0, 1790967403668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fa83507eb5d6bf3c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The Quaid-e-Azam passed his Bar-at-law examination from ______?', '{"A":"Oxford","B":"Lincoln’s Inn","C":"Cambridge","D":"Harvard"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Quaid-e-Azam Muhammad Ali Jinnah passed his Bar-at-Law examination on 25 May 1893.He studied law at Lincoln’s Inn in London, one of the four Inns of Court.After completing his legal training, he returned to India in 1896 and started his legal career in Bombay.Last verified on 13-03-2026', 0, 0, 0, 1790967403668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8f32a73afdc1bd9c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who did imposed third Martial Law in Pakistan?', '{"A":"Gen. Ayub Khan","B":"Agha Muhammad Yahya Khan","C":"Gen. Muhammad Zia ul Haq","D":"Sikander Mirza"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Army Chief, General Muhammad Zia-ul-Haq imposed Third Martial Law in Pakistan on 05-07-1977.Additional information:First Martial Law: 7th October 1958 by Iskandar Mirza2nd Martial Law: 25th March 1969 by General Yahya Khan4th Martial Law: 12th October 1999 by General Pervaiz MusharrafLast verified on 07-03-2026', 0, 0, 0, 1790967403668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d4ae8cd5b78395d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Under 1973 Constitution of Pakistan Head of Government is ______?', '{"A":"President","B":"Prime Minister","C":"Parliament","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Under the 1973 Constitution of Pakistan, the Head of Government is the Prime Minister.Additional information:The President serves as the Head of State with a ceremonial role.Last verified on 10-02-2026', 0, 0, 0, 1790967403668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ca6ece9175aa112e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who abrogated 1962 constitution and became CMLA?', '{"A":"Yahiya Khan","B":"Tikka Khan","C":"Ahsan Khan","D":"Pervez Musharraf"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation General Agha Muhammad Yahya Khan abrogated the 1962 Constitution of Pakistan And became the Chief Martial Law Administrator (CMLA) on March 25, 1969.Additional information about the 1962 constitutionsThe presidential system of government was introduced Urdu and Bengali were the official languages declaredAyoub Khan enforced the new constitution on 8th June 1962Iskandar Ali Mirza, the first president of PakistanLast updated 07-02-2026', 0, 0, 0, 1790967403668) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_09782a3f73918f0f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who dissolved the assembly and imposed the First Martial Law in Pakistan?', '{"A":"Iskandar Mirza","B":"General Zia-ul-Haq","C":"General Ayub Khan","D":"General Pervez Musharraf"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation President Iskander Mirza dissolved the assembly and imposed the first martial law in Pakistan on October 7, 1958List of Martial Laws Held in Pakistan from 1947 to 2022Sr# Martial Law NumberDate of Martial LawMartial Law Implemented by1First Martial Law7th October 1958Iskandar Mirza22nd Martial Law25th March 1969General Yahya Khan33rd Martial Law25th July 1977General Zia ul Haq44th Martial Law12th October 1999General Pervaiz Musharraf There are total four martial laws Implemented in Pakistan from 1947 to 2023', 0, 0, 0, 1790967403698) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_dd0c5e2e0d1b8484', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When Transgender Persons (Protection of Rights) Act passed in Pakistan?', '{"A":"2022","B":"2018","C":"2020","D":"2019"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Passed in: May 2018 by the National Assembly of PakistanPurpose:Allows transgender persons to self-identify their gender on official documentsProhibits discrimination in jobs, education, healthcareGrants rights to inheritance and social welfareLast verified on 04-02-2026', 0, 0, 0, 1790967403698) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6a264a122a8fedd8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The 1962 Constitution of Pakistan was passed during the regime of?', '{"A":"Ayub Khan","B":"Sikandar Mirza","C":"Yahya Khan","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 2nd Constitution (1962): 250 articles, 10 parts, imposed by Ayub Khan during his first martial law.Additional information:1st Constitution (1956): 234 articles, 13 parts, adopted during civilian rule.3rd Constitution (1973): 280 articles, 12 parts, introduced in Zulfikar Ali Bhutto’s era.First Martial Law: Imposed by Ayub Khan before the 1962 Constitution.Last verified on 02-02-2026', 0, 0, 0, 1790967403698) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_dd6213721903b714', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The Constitution Commission set up by Ayub Khan in 1962 was headed by ______?', '{"A":"Justice Munir","B":"Justice Shahab-ud-Din","C":"Justice Sharif","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Constitution Commission set up by Ayub Khan in 1960-1961Ayub Khan established the Constitution Commission in 1960 to draft a new constitution. It was headed by Justice Shahab-ud-Din, a former Chief Justice of Pakistan.The commission was appointed on February 17, 1960, and presented its report to President Ayub Khan on May 6, 1961.', 0, 0, 0, 1790967403698) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e725a03ba9289da6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The constitution of Pakistan 1973. can be amended______', '{"A":"With the simple majority vote in the twohouses of parliament","B":"With two-third majority in the National Assembly and a simple majority of the  Senate.","C":"With two-third majority of both the houses of partiament.","D":"With the approval of Provincial Legislatures","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Approval Requirement: The bill must pass with a two-thirds majority of the total membership in both the National Assembly and the Senate.At the age of 21 years, the charter, that changed into adopted in April 1973, Has suffered 34 amendments; 10 times through the Acts of Parliament and 24 times through Presidential Orders.Amendments to Date: As of late 2024, the Constitution has been amended 26 times.', 0, 0, 0, 1790967403698) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_eceb07674da350b0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who is the current leader of the opposition in the Senate of Pakistan?', '{"A":"Shibli Faraz","B":"Raja Nasir Abbas","C":"Yousaf Raza Gillani","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Raja Nasir Abbas is the current leader of the opposition in the Senate of Pakistan since 2026.He is the chief of Majlis Wahdat-i-Muslimeen (MWM).He replaced Shibli Faraz who was disqualified in August 2025.Last Updated on 20-01-2026.', 0, 0, 0, 1790967403698) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7f2363b2a9a6fba7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When is National Constitution Day celebrated?', '{"A":"April 10","B":"April 12","C":"April 14","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Date: 10 AprilYear of Constitution Approval: 1973, April 10Golden Jubilee Declaration: 2023, April 10Significance: Commemorates the country’s supreme law and democratic frameworkLast verified on 16-01-2026', 0, 0, 0, 1790967403698) ON CONFLICT(id) DO NOTHING;
