INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_03c681b230faa1f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Under which amendment military courts were formed in Pakistan?', '{"A":"18","B":"18","C":"21","D":"20"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 2015, National Assembly passed the 21st Amendment and created military courts for the period of 2 years.ND-21-5-2023', 0, 0, 0, 1790967404098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0208f74438c41842', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which Article of 1973 Constitution is related to secret ballot?', '{"A":"226","B":"227","C":"228","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The correct answer is Article 226.This article states that elections, such as those for the Senate, President, Speaker, and Deputy Speaker of the National Assembly, must be held by secret ballot.', 0, 0, 0, 1790967404098) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0d9ae24054aeeb5e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Pakistan Climate Change Act was passed in which year?', '{"A":"2015","B":"2017","C":"2019","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Pakistan Climate Change Act was passed in 2017.It extends to the whole of Pakistan. It shall come into force at once. "Tribunal" means the Environmental Tribunal set up under the Pakistan Environmental Protection Act, 1997.', 0, 0, 0, 1790967404114) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_88729209d1f90e93', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'When was Vernacular Press Act given?', '{"A":"1870","B":"1874","C":"1878","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Vernacular Press Act was passed in 1878 during British rule in India.It aimed to regulate the vernacular press, which published newspapers and pamphlets in various Indian languages.', 0, 0, 0, 1790967404114) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f7854e447edea193', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Chapter 1 of the 1973 constitution deals with _____?', '{"A":"Fundamental Rights","B":"Principle of Policy","C":"President''s powers","D":"Power Minister''s Power"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 1973 Constitution of Pakistan consists of:280 articles12 chaptersa schedule divided into 7 chapters.whileIn the constitution of Pakistan, 1973, ''Chapter 1: Fundamental rights'' consists of Articles 8-28 the 1973 Constitution of Pakistan 4 partsPart I – Introductory Part II – Fundamental Rights and Principles of Policy Part III – The Federation of Pakistan Part IV – ProvincesND26-2-2023', 0, 0, 0, 1790967404114) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d557c1dab155390e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', '18th Amendment was passed by which party reign?', '{"A":"PTA","B":"PPP","C":"Muslim League","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Eighteenth Amendment of the Constitution of Pakistan was passed by the National Assembly of Pakistan on April 8, 2010, removing the power of the President of Pakistan to dissolve the Parliament.', 0, 0, 0, 1790967404114) ON CONFLICT(id) DO NOTHING;
