INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f5c8aa38aadc4bbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'The Simon Commission was a group of how many member of Britisth parliament?', '{"A":"09","B":"07","C":"04","D":"08"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Simon Commission was a group of seven members of the British Parliament Under the chairmanship of John Simon.Indian Statutory Commission, also known as the Simon Commission, Rejected by the Indian National Congress and the Muslim LeagueAppointed in 1928Opposed by both Jinnah & GandhiAdditional information:One of its members was Clement Attlee, who would later become the Prime Minister of the United Kingdom (1945–1951).Last updated by NA on 16-07-2026', 0, 0, 0, 1790967404114) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_630d677b45b791bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Who is the only Civil Martial Law Administrator?', '{"A":"Zulfiqar  Ali Bhutto","B":"Ayub Khan","C":"Skindar Mirza","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Zulfikar Ali Bhutto was served as the ninth Prime Minister of Pakistan from 1973 to 1977.Fourth President of Pakistan from 1971 to 1973. His government drafted the Constitution of Pakistan in 1973, which is the current constitution of the country.RK20-11-22', 0, 0, 0, 1790967404114) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f0eb4174641853b4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which amendment relates with Shariah Bill?', '{"A":"11","B":"8","C":"6","D":"9"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Ninth Amendment to the Constitution of Pakistan would have imposed sharia law as the supreme law. The Senate passed the bill and sent it to the National Assembly on 7 August 1986.', 0, 0, 0, 1790967404129) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_769de3bde82b85f5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Constitution 1956 provided _______ form of government for the country.', '{"A":"Parliamentary","B":"Federal","C":"Presidential","D":"All of these"}', 'A', NULL, 0, 0, 0, 1790967404129) ON CONFLICT(id) DO NOTHING;
