INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a1436d4a4cc96f88', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_constitution', 'Which of the following document was first drafted to give pace to constitution-making process?', '{"A":"Representative Act","B":"Pakistan Act","C":"Objective Resolution","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Objectives Resolution was adopted on March 12, 1949.PM Liaquat Ali Khan, had presented it in the assembly on March 7, 1949.', 0, 0, 0, 1790967404194) ON CONFLICT(id) DO NOTHING;
