INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c2f584e1a9594b09', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Allama Muhammad Iqbal delivered his famous Allahabad Address in?', '{"A":"29 December 1928","B":"29 December 1929","C":"29 December 1930","D":"29 December 1945"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Delivered Presidential Address at 25th All-India Muslim League session, Allahabad, 29 December 1930.Allama Iqbal (1877–1938) is the National Poet of Pakistan.Joined Muslim League: 1908 in London, 1922 in Indian subcontinent.Additional information:Born: 9 November 1877, SialkotDied: 21 April 1938, LahoreBurial: Tomb of Allama Iqbal, LahoreKnown as “Mufakkir-e-Pakistan” (Thinker of Pakistan) and “Shair-e-Mashriq” (Poet of the East).Last verified 09-03-2026', 0, 0, 0, 1790967404312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_339196b42e9e0b74', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Heer Ranjha was written by whom?', '{"A":"Waris Shah","B":"Sultan Bahu","C":"Bullay Shah","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Author: Waris ShahWritten in: 1766Language: PunjabiGenre: Epic poetry / RomanceOrigin Date: Late 15th century (traditionally)Related: Mirza Sahiban, Sohni Mahiwal, Sassui PunnhunLast updated by NS on 06-09-2026​', 0, 0, 0, 1790967404312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_50a5b3de855c423f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Who wrote the book Hayat-e-Muhammad?', '{"A":"Muhammad Husain Haykal","B":"Shibli Nomani","C":"Syed Sulaiman Nadvi","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hayat-e-Muhammad was written by Muhammad Husain Haykal.The book is a famous biography (Seerah) of Prophet Muhammad (ﷺ).It was originally written in Arabic.Additional information:Sirat-un-Nabi → Shibli Nomani (completed by Syed Sulaiman Nadvi)Ar-Raheeq Al-Makhtum (The Sealed Nectar) → Safi-ur-Rahman MubarakpuriMuhammad: His Life Based on the Earliest Sources → Martin LingsThe Life of Muhammad → Ibn Ishaq (preserved and edited by Ibn Hisham)Verified & Updated', 0, 0, 0, 1790967404312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8ebd3073f2e274e0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'The book Hayat-i-Afghani was primarily written about?', '{"A":"The Mughal Empire","B":"The Pashtun tribes and Afghanistan","C":"The Delhi Sultanate","D":"The Ottoman Empire"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hayat-i-Afghani, authored by Muhammad Hayat KhanIt is a historical and genealogical study of Pashtun tribes and the geography of Afghanistan Published in 1867Last question by NA on 09 July 2026', 0, 0, 0, 1790967404312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d1adc94a13eb4bf1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Hayat e javeed is written by?', '{"A":"Mirza ghalib","B":"Sir syed","C":"Altaf Hussain Hali","D":"Iqbal"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Hayate-e-Javed is written by Altaf Hussain Hali about Sir Sayyid Ahmad Khan. He got it published twice- first in 1901 and then in 1903.', 0, 0, 0, 1790967404312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_83e146c4b2b8e039', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'The Nehru Report was published in _____?', '{"A":"August 1928","B":"September 1928","C":"October 1928","D":"November 1928"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Published: 28 August 1928Place: Lucknow ConferenceChairman: Motilal NehruMember: Jawaharlal NehruMain Demand: Dominion status & federal system for IndiaMuslim League Response: Muhammad Ali Jinnah rejected it and presented his 14 Points.Last verified on 10-06-2026', 0, 0, 0, 1790967404312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d699a05e0b4bb927', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Who was the first Punjabi poet?', '{"A":"Shah Hussain","B":"Waris Shah","C":"Bulle Shah","D":"Baba Fareed"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Baba Farid is considered the first Punjabi poet.He was born in 1173 and died on 7 May 1266.His birthplace is Kothewal village near Multan.He spread Sufi teachings through poetry and songs.His shrine is located in Pakpattan, Pakistan.Additional information:Hazrat Hassan ibn Sabit (R.A): First poet of IslamAllama Iqbal: National Poet of Pakistan, called “Poet of the East”Amir Kror Suri: First poet of Pashto languageLast verified on 01-04-2026', 0, 0, 0, 1790967404312) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b8bce12a5c4c7898', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Who is known as the Poet of East?', '{"A":"Allama Iqbal","B":"Hali","C":"Ghalib","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Allama Muhammad Iqbal is known as the Poet of the East (Shair-e-Mashriq).He is regarded as the National Poet of Pakistan.Additional information:Born: 9 November 1877, SialkotFather: Sheikh Noor MuhammadMother: Imam BibiPhD: Ludwig Maximilian University, Munich, Germany (1908)Died: 21 April 1938Burial Place: Badshahi Mosque, LahoreLast verified on 10-07-2026', 0, 0, 0, 1790967404343) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cbc0e39c69b3cb05', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', '“My brother” book was written by?', '{"A":"Gulbadam Bagum","B":"Fatima Jinnah","C":"Hajra Masroor","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "My Brother" was written by Fatima Jinnah.The book is about the life and personality of her brother, Muhammad Ali Jinnah.It provides personal memories and insights into Quaid-e-Azam''s struggle for Pakistan.Language: EnglishPublisher: Quaid-i-Azam AcademyPublication: 1987Additional information:Fatima Jinnah was popularly known as Madar-e-Millat (Mother of the Nation).Last verified on 09-07-2026', 0, 0, 0, 1790967404343) ON CONFLICT(id) DO NOTHING;
