INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f1ab4360f74cda85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Ch Rahmat Ali published a leaflet "Now are Never .We to live or Perish forever issued on January 28,1933; from Cambridge with the objective .', '{"A":"To create a separate and independent Muslim state","B":"To grow the concept of Indianism","C":"To develop amity with the British as a Muslim community","D":"To work with other Indian communities for liberation of India"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The word was first introduced now or never in 1933 by Choudhry Rahmat Ali.The "Pakistan Declaration" titled Now or Never means Are We to Live or Perish Forever?In this pamphlet, the word Pakistan was used for the first time This pamphlet was derived from the two-nation theory of Muslim reformer Syed Ahmed Khanit was a pamphlet, referring to the names of the five northern regions of British India: PunjabAfghanistanKashmirSindhBaluchistan. (Pakistan)***', 0, 0, 0, 1790967404687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2b0960dcbc77ed88', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'Fiaz Ahmad Faiz was', '{"A":"A poet","B":"A journalist","C":"An army personnel","D":"All the above"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Faiz Ahmad Faiz is also the author of Urdu and Punjabi literature.He was the first Asian poet to be awarded the Lenin Peace Prize (1962) by the Soviet Union Born: February 13, 1911, NarowalDied: November 20, 1984, in LahoreAwards: Lenin Peace PrizeNishan-e-ImtiazNigar AwardsAvicenna Prize', 0, 0, 0, 1790967404687) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_71700f35a27b5c72', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_books', 'The poem Iblees Ki Majlis-e-Shura is written by:', '{"A":"Bahadur Shah Zafar","B":"Sir Syed Ahmed Khan","C":"Allama Iqbal","D":"Jinnah","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "Iblees Ki Majlis-e-Shura" is an Urdu poem written by Muhammad Iqbal in 1935The poem is written as a meeting between: Iblees (the first of the Devils, or Satans in Islam) and his five advisers. ND13-5-2023', 0, 0, 0, 1790967404687) ON CONFLICT(id) DO NOTHING;
