INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_dbb8e8d744dc372a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The highest official rank of Pakistan Army is ________?', '{"A":"General","B":"Major General","C":"Lieutenant","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan Army: The highest official rank is Field Marshal, though it is rarely awarded (e.g., General Ayub Khan in 1965). The highest active rank is General.Pakistan Navy: The highest rank is Admiral.Pakistan Air Force: The highest rank is Air Chief Marshal.Police: The highest rank is Inspector General of Police (IGP), overseeing provincial or national law enforcement.', 0, 0, 0, 1790967404879) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8efe10b3f513485e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The first shaheed female pilot of Pakistan Air Force is ______?', '{"A":"Marium Khan","B":"Marium Mukhtiar","C":"Marium Mahmood","D":"Marium Maher"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Flying Officer Marium Mukhtiar, born on May 18, 1992.She was a Pakistani fighter pilot who died on November 24, 2015, when her PAF FT-7PG aircraft crashed near Kundian, Mianwali.She was the first female combat pilot of Pakistan to die in a crash on duty.', 0, 0, 0, 1790967404879) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7d0a57fed7080934', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'When did the second battle of Panipat take place?', '{"A":"21 April 1526","B":"5 November 1556","C":"21 May 1757","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Battle of Panipat: 21 April 1526Fought Between: Babur Vs LodiWon by: BaburSecond Battle of Panipat: November 5, 1556Fought Between: Hemu Vs AkbarWon by: AkbarThird Battle of Panipat: 14 January 1761Fought Between: Abdali Vs MarathasWon by: Abdali', 0, 0, 0, 1790967404879) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e96e7e7eefb276aa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Who was the hero of the Pak-India 1965 war?', '{"A":"Major Tufail","B":"Major Raja Aziz Bhatti","C":"Mulla Faqir","D":"Lalik Jan","E":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Major Aziz Bhatti Shaheed directed his men to answer the fire until an enemy tank shell, which killed him on 12 September 1965, hit him. He was 37 years old.', 0, 0, 0, 1790967404879) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c154578ecfd91950', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Name the Pakistani submarine which was action in 1965 and 1971 wars. It sank in 1971 war while on a mission?', '{"A":"PNS Shamsher","B":"PNS Dwarka","C":"PNS Rangamati","D":"PNS Ghazi"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation PNS Ghazi was a Pakistani submarine that played a significant role in both the 1965 and 1971 wars with India.Unfortunately, it sank on December 3, 1971, while on a mission to attack the Indian aircraft carrier INS Vikrant during the Indo-Pakistani War of 1971.', 0, 0, 0, 1790967404879) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_83f146de1857cd2f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Which regiment of Pakistan Army has received maximum numbers of “Nishan-e-Haider”?', '{"A":"Baluch Regiment","B":"Sindh Regiment","C":"Punjab Regiment","D":"Frontier Force Regiment"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Of the eleven Nishan-e-Haider recipients to date, four have been from the Punjab Regiment.1. Raja Muhammad Sarwar Bhatti2. Major Tufail Mohammad3. Major Raja Aziz Bhatti4. Naik Muhammad Mahfuz', 0, 0, 0, 1790967404879) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1d816094b26ef8a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'When did Rashid Minhas got Nishan-e-Haider?', '{"A":"1982","B":"1971","C":"1978","D":"1969"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rashid Minhas received the Nishan-e-Haider in 1971.He received this honor posthumously for his actions in preventing a traitor from stealing a fighter plane on August 20, 1971.', 0, 0, 0, 1790967404912) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1a14e695af582e5e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Captain Muhammad Sarwar was martyred in the war of _____?', '{"A":"1999","B":"1971","C":"1965","D":"1948"}', 'D', NULL, 0, 0, 0, 1790967404912) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2ed4c21e3fb683ce', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The Supreme Commander of Pakistan Armed Forces is?', '{"A":"Army Chief","B":"Governor","C":"President","D":"Prime Minister"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Supreme Commander of the Pakistan Armed Forces is the President. Article 243 defines the Command of Armed Forces.The President is indirectly elected by the Electoral College for a five-year term. The Constitution requires the President to be a Muslim who is at least 45 years old.', 0, 0, 0, 1790967404912) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_45d0ac54d90e4a99', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Begum Nusrat Bhutto vs Chief of Army Staff (PLD 1977 S.C. 657), when this case was decided who was the Chief Justice?', '{"A":"Yaqoob Ali Khan","B":"Anwar-ul-Haq","C":"Dorab Patel","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The case was decided in 1977 after the imposition of martial law by General Zia-ul-Haq.Chief Justice Sheikh Anwar-ul-Haq presided over the Supreme Court at that time.', 0, 0, 0, 1790967404912) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1891fab5ec58d055', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The Headquarters of Air Force is located in?', '{"A":"Islamabad","B":"Peshawar","C":"Karachi","D":"Rawalpindi"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Air Force HQ Initially, it was established at Peshawar on 15 August 1947. Later it was moved to Karachi on 1 June 1948 and back to Peshawar in 1960. In 1983 construction of the Air headquarters was started in Islamabad after it was decided to have all the armed forces headquarters in the capital city.ND5-07-2023', 0, 0, 0, 1790967404912) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_17ce6bfb58e4e992', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Who is the Current Director-General (DG) of Inter-Services Intelligence (ISI)?', '{"A":"Lt. Gen.  Faiz Hameed","B":"Lt. Gen. Nadeem Anjum","C":"Lt. Gen. Muhammad Asim Malik","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ð Lieutenant General Muhammad Asim Malik is the current and 26th Director-General (DG) of Inter-Services Intelligence (ISI) since 30 Sep 2024.ð He replaced Lt. Gen. Nadeem Anjum.ð DG ISI tenure term: 3 yearsLast update on 01.09.2023 Updated & verified on 28-09-2026 Click here for reference', 0, 0, 0, 1790967404912) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5374d3d91f30bfe2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'When did General Pervez Musharraf assume control of the government by overthrowing Nawaz Sharif?', '{"A":"October 12, 1999","B":"October 10, 1998","C":"November 3, 19999","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In October 1999, General Pervez Musharraf led a military coup to overthrow Prime Minister Nawaz Sharif.The military seized control of the government on October 12, 1999.By October 14, 1999, Musharraf was acting as the Chief Executive of Pakistan.', 0, 0, 0, 1790967404912) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2c9221471ddcfb94', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The general elections were held in ____ provinces of India from February to March 1937.', '{"A":"18","B":"11","C":"15","D":"9"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Elections were held in eleven provinces - Madras, Central Provinces, Bihar, Orissa, United Provinces, Bombay Presidency, Assam, NWFP, Bengal, Punjab and Sindh.Indian National Congress won 8 provinces.', 0, 0, 0, 1790967404912) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c21fb798a56f99b2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'When was the last general census in Pakistan conducted?', '{"A":"2017","B":"2022","C":"2023","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation There have been only 7 nationwide censuses.First Census was held in Pakistan in 1951.The second Census was held in Pakistan in 1961.The third Census was held in Pakistan in 1972.The fourth Census was held in Pakistan in 1981.The fifth Census was held in Pakistan in 1998.The Sixth Census was held in Pakistan in 2017.The seventh census was held in Pakistan in 2023.Additional Information:Census has been undertaken every 10 yearsit was beginning in 1872 under British viceroy Lord Mayoagm.5.3.23na19112023', 0, 0, 0, 1790967404962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a29724eeb386d1e2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Name of Military operation start in 2017?', '{"A":"Radd-ul-Fasaad","B":"Rah-e-Haq","C":"Rah-e-Rast","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Operation Radd-ul-Fasaad Launched on February 22, 2017.The intensive nationwide operation against terror groups, steered by Army Chief General Qamar Javid Bajwa******Operation Zarb-e-Azb started by Army Staff General Raheel Sharif.Operation Zarb-e-Azb start from 15 June 2014 till 22 February 2017.', 0, 0, 0, 1790967404962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_312613e68e9cbc44', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'On which date did General Pervez Musharraf assume the position of Chief Executive of Pakistan through a military coup?', '{"A":"October 12, 1999","B":"November 12, 1999","C":"November 13, 1999","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Military coup: 12 October 1999Chief Executive: General Pervez MusharrafAssumed office as Chief Executive: 14 October 1999He overthrew the government of Prime Minister Nawaz Sharif.', 0, 0, 0, 1790967404962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_53f73b8423b77ebf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'General Zia-ul-Haq ruled Pakistan from ______?', '{"A":"1977 to 1989","B":"1978 to 1984","C":"1977 to 1988","D":"1975 to 1990"}', 'C', NULL, 0, 0, 0, 1790967404962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9c2b53e3a8122368', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'General Muhammad Zia-ul-Haq killed in a plan crash on ______?', '{"A":"17 August 1988","B":"17 August 1987","C":"17 August 1986","D":"17 August 1985"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation All about Zia-ul-HaqZia-Ul-Haq Died on 17-08-1988 by Plane crashed in Bahawalpur.American Ambassador Arnold Raphael with President Zia Ul Haque in a plane crashHe was HI, GCSJ, ร.ม.ภ, was a Pakistani four-star general He became the CMLA of Pakistan in: 1977Born: August 12, 1924, Jalandhar, IndiaHe took oath as President of Pakistan on 23 March 1985.He becomes the 6th President of Pakistan.He ruled Pakistan from 1977 to 1988.', 0, 0, 0, 1790967404962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f0002d9b2e11ad08', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'On which date Captain Karnal Sher Khan was martyred at Kargil?', '{"A":"5th July 1999","B":"5th June 1999","C":"5th October 1999","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Karnal Sher Khan was martyred on 5 July 1999 during Kargil War between India & Pakistan.Karnal Sher Khan was one of only eleven recipients of the Nishan-e-Haider. He was a captain in the 27th Sindh Regiment and later was posted to 12th NLI Regiment during the Kargil Conflict. He was killed in action during the Kargil war 1999.', 0, 0, 0, 1790967404962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4250a5916e476484', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'What was the voter turnout in General Elections 2018?', '{"A":"63%","B":"43%","C":"45%","D":"40%","E":"51%"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Turnout in Pakistani general elections1970: 63%1988: 43%1990: 45%1993: 40%1997:35%2002: 41%2008: 44%2013: 53%2018: 51%', 0, 0, 0, 1790967404962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1cd9674f683c0902', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'In which year Gen. Yahya held General Elections in the country?', '{"A":"1970","B":"1971","C":"1972","D":"1973"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Agha Muhammad Yahya Kha was a Pakistani military officer and politician who served as the third president of Pakistan from 1969 to 1971.born: 4 February 1917 - died: 10 August 1980By 28 July 1969, President Yahya Khan had set a framework for elections that were to be held in December 1970. Finally, the general elections were held all over the country.He also served as the commander-in-chief of the Pakistan Army from 1966 to 1971.ND14-7-2023', 0, 0, 0, 1790967404962) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c728b9b35331ddba', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Who was the second chief of staff of Pakistan army?', '{"A":"Gen. Aslam Baig Mirza","B":"Gen. Jehangir Karamat","C":"Gen. Tikka Khan","D":"Gen. Zia Ul Haq"}', 'D', NULL, 0, 0, 0, 1790967404995) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_686e36e92e2aeb67', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Naval War College is situated in ____?', '{"A":"Karachi","B":"Islamabad","C":"Lahore","D":"Multan"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The genesis of Pakistan Navy War College started with Pakistan Navy Staff School at Manora Island off Karachi in 1968.It was later upgraded to War College in 1971 and shifted to PNS Karsaz.In 1995, the College was shifted to Lahore with a dedicated building on Mall Road, which was inaugurated in August 1996.As of 2014, a new purpose-built campus had been constructed in Walton, where the war college was finally shifted to.', 0, 0, 0, 1790967404995) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ddd94deb141d0080', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Inspector-General of Police is also known as ______?', '{"A":"Provincial Police Office","B":"Provincial Police Officer","C":"Punjab Police Officer","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Inspector General of Police (IGP) is also known as the Provincial Police Officer (PPO).The IGP is the head of the police force in a province.It is appointed by the federal government with the consent of the provincial chief minister. The IGP is a Police Service of Pakistan officer who has administrative and financial powers.', 0, 0, 0, 1790967404995) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_abbc0db7ee61f37e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Third battle of Panipat was fought between ______?', '{"A":"Marathas and Britidhers","B":"Marathas and Rajpoots","C":"Marahatas and Afghans","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Fought on January 14, 1761Location: Panipat, IndiaResult: Durrani victory1st battle of Panipat: 15262nd battle of Panipat: 1556', 0, 0, 0, 1790967404995) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_aeba4a4c89a6e8f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Havaldar Lalak Jan Shaheed was awarded Nishan-e-Haider for his acts of bravery and valour during the _____?', '{"A":"1971 War","B":"1965 War","C":"Operation Zarb-e-Azb","D":"Kargil Operation"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Shaheed Lalak Jan was born on April 1, 1967.He was enlisted in the Army as Havaldar on December 10, 1984.He was given country''s highest award Nishan-E-Haider for the devotion and courage he showed in the Kargil War in 1999.', 0, 0, 0, 1790967404995) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_69b196a395512d49', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Babur defeated________ in the first battle of Panipat.', '{"A":"Akbar","B":"Sher Shah","C":"Ibrahim Lodi","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Battle of Panipat, on 20 April 1526.It took place in North India and marked the beginning of the Mughal Empire and the end of the Delhi Sultanate. *****RY 4-12-2022', 0, 0, 0, 1790967404995) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f2713146bb1aaa28', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'When did an avalanche hit a Pakistan Army base in which 140 soldiers and civilian contractors martyred?', '{"A":"8th April 2012","B":"6th April 2012","C":"7th April 2012","D":"5th April 2012"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 7 April 2012, an avalanche hit a Pakistani military base near the Siachen Glacier region, trapping 140 soldiers and civilian contractors under deep snow.It is the worst avalanche the Pakistani military has ever experienced in the area.', 0, 0, 0, 1790967404995) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f0e4f781a6d60ff2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Ibrahim lodi was defeated by ________in the First Battle of Panipat in 1526?', '{"A":"Jahangir","B":"Babar","C":"Akbar","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The First Battle of Panipat was fought between Babur and the Lodi Empire, which took place on 21 April 1526 in North India.It marked the beginning of the Mughal EmpireIt took place in North India and the end of the Delhi Sultanate.***The Second Battle of Panipat was fought between the forces of Hemu and the army of Akbar, on November 5, 1556.The third battle of Panipat was fought between Marahatas and Afghans on January 14, 1761**', 0, 0, 0, 1790967404995) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3383f2391e60fc98', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'On 29th May 1988 General Zia ul Haque dismissed the Government of _____?', '{"A":"Zafarullah Khan Jamali","B":"Nawaz Sharif","C":"ZA Bhutto","D":"Muhammad Khan Junejo"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On May 30, 1988, Zia ul-Haq dissolved the National Assembly of Pakistan Dismissed Junejo, Zafarullah KhanBy using powers under Article 58(2)b of the ConstitutionThe Junejo government was formed on April 10, 1985, and dissolved on 30 May 1988 Additional informationJamali was later appointed as the caretaker Chief Minister of Balochistan Last updated 18-02-2026', 0, 0, 0, 1790967405013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4f566b0ac85c3c7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'After World War 1 influenza disease occurred in ______?', '{"A":"1918","B":"1919","C":"1920","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The influenza epidemic that swept the world in 1918 killed an estimated 50 million people.One-fifth of the world''s population was attacked by this deadly virus.World War I claimed an estimated 16 million lives.World War I was a global war originating in Europe that lasted from 28 July 1914 to 11 November 1918.Chlorine was First used during World War I at Ypres in April 1915During the First World War, Russia signed the Peace Treaty (1917) with Germany.', 0, 0, 0, 1790967405013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_4d0e7f4ecf1f8a0a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Which band sung Ae Jawan Jeet ka neeshan?', '{"A":"Awaz","B":"Vital Sings","C":"Souch","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Awaz was a Pakistani pop band that formed in Islamabad in 1992. The group was formed by Haroon Rashid, lead vocalist, who was soon joined by keyboardist Faakhir Mehmood and lead guitarist Asad Ahmed.', 0, 0, 0, 1790967405013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_419bf6b1d54b6e8a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Mutiny War occurred in _____?', '{"A":"1857","B":"1867","C":"1877","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Indian Mutiny, also called Sepoy Mutiny or First War of Independence, widespread but unsuccessful rebellion against British rule in India in 1857–59. Begun in Meerut by Indian troops (sepoys) in the service of the British East India Company, it spread to Delhi, Agra, Kanpur, and Lucknow.', 0, 0, 0, 1790967405013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d97da1118d0e94bb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The battle of Balakot was fought between Syed Ahmed Shaheed and the _____?', '{"A":"English","B":"Hindus","C":"Sikhs","D":"Marhattas","E":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Syed Ahmad and his pupil Shah Ismail were martyred in 1831 while fighting against the Sikhs at Mitikot area in Balakot town of Mansehra.The graves of both the martyrs are located at a distance of one kilometer from the place where they were martyred', 0, 0, 0, 1790967405013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ed0b863fa8cbf389', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Who was SAARC General Secretary in 1996-1998 from Pakistan?', '{"A":"Abdul Hassan","B":"Ahmed Saleem","C":"Naeem U Hasan","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The SAARC General Secretary from Pakistan between 1996 and 1998 was Naeem U. Hasan.He served as the ambassador to Sweden until 2001.', 0, 0, 0, 1790967405013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5cb03f2a6cfba354', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The latest anti-militancy military operation in Pakistan is titled?', '{"A":"Zarb-e-Momin","B":"Zarb-e-Islam","C":"Zarb-e-Azb","D":"Radd-ul-Fasaad"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Radd-ul-Fasaad is a military operation.It was start by COAS Qamar Javed Bajwa across all states of Pakistan, on 22 February 2017.', 0, 0, 0, 1790967405013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b6a0fe3ec9b524fb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Major Shabbir Sharif was awarded with Nishan-e-Haider posthumously. Which other medal for bravery was he awarded during his career in the Army?', '{"A":"Sitara-e-Jurat","B":"Hilal-e-Jurat","C":"Nishan-e-Shujaat","D":"Tamgha-e-Basaiat"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Major Shabbir Sharif is the only recipient to have ever received both:Nishan-e-Haider (NH): Awarded posthumously for the 1971 war.Sitara-e-Jurat (SJ): Awarded earlier for actions during the 1965 war.He was commissioned in Pakistan Army on 19 April 1961Born on April 28, 1943 in Kunjah, Gujarat.Shabbir Sharif sacrificed his life on December 6, 1971.', 0, 0, 0, 1790967405013) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6bc6de050d71d310', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Name the only Pakistani who has served as the Secretary General of the OIC?', '{"A":"Syed Sharifuddin Pirzada","B":"Agha Shahi","C":"Abdul Hafiz Pirzada","D":"Sahibzada Yaqub Khan"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Secretaries-General of the OIC since its establishment are:H.R.H. Tunku Abdul Rahman (Malaysia): 1971-1973H.E. Hassan Al-Touhami (Egypt): 1974-1975H.E. Dr. Amadou Karim Gaye (Senegal): 1975-1979H.E. Mr. Habib Chatty (Tunisia): 1979-1984H.E. Syed Sharifuddin Pirzada (Pakistan): 1985-1988', 0, 0, 0, 1790967405032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e602646cba8e98c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Who was the first Muslim Commander-in-Chief of Pakistan Air Force?', '{"A":"Air Marshall Asghar Khan","B":"Air Marshall Abdul Rahim Khan","C":"Air Marshall Noor Khan","D":"Air Marshall Zafar Chaudhry"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Muslim Commander-in-Chief of Pakistan Air Force was Air Marshal Asghar Khan.He held this position from 1957 to 1965.', 0, 0, 0, 1790967405032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_701a5c63ebd5347d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The first Anglo Sikh war was fought between?', '{"A":"British","B":"Portages","C":"East India Company","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Anglo-Sikh war was fought between the Sikh Empire and the British East India Company Fought in 1845 and 1846 around the Ferozepur district of PunjabLord Harding was the Governor General during the First Anglo-Sikh War.Additional information:The second Anglo-Sikh war took place in 1848-1849.The Governor General of the Second Anglo-Sikh War was Lord Dalhousie.', 0, 0, 0, 1790967405032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e7630adf84482d0c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The joint military training exercise ‘Druzhba - III’ has started between following countries?', '{"A":"India and Afghanistan","B":"Russia and Pakistan","C":"United States and Israel","D":"India and Bangladesh"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The two week long Durzbha-V was conducted at Tarbela and NCTC Pabbi.The first-ever joint exercise between Pakistan and the Russian military took place in 2016.', 0, 0, 0, 1790967405032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d892548d0cc0b638', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Pakistan Army on launched ‘Operation Radd-ul-Fasaad’ across the country on __________?', '{"A":"22nd Feb 2017","B":"15th Feb 2017","C":"2nd Feb 2017","D":"13th Jan 2017"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Operation Radd-ul-Fasaad means the Elimination of Strife جھگڑے کا خاتمہOperation Radd ul Fasaad was started on February 22, 2017,Operation Radd ul Fasaad was started by Army Chief Qamar Javed BajwaThe foundational aim and objective of Operation Radd-ul-Fasaad is to ensure enduring peace in the country', 0, 0, 0, 1790967405032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bff75d236aa2217f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Syed Ahmed Shaheed along with Shah Ismail were martyred in a battle with Sikhs at:', '{"A":"Panipat","B":"Pathankot","C":"Balakot","D":"Agra","E":"Lahore"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sayyid Ahmad Shaheed was an Indian Muslim revivalist from Rae Bareli, a part of the historical United Provinces of Agra and Oudh.Sayed Ahmad Shaheed died 06 March 1831 at BalakotHe is considered as a scholarly authority by Ahl-i Hadith and Deobandi movements', 0, 0, 0, 1790967405032) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f36239eac1651898', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'A U-Turn came in the foreign policy of Pakistan after the world launched a war against terrorism in?', '{"A":"2000","B":"1999","C":"2001","D":"2004"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A U-Turn came in the foreign policy of Pakistan after the world launched a war against terrorism in September 11, 2001War on terrorism, a term used to describe the American-led global counterterrorism campaign launched in response to the terrorist attacks of September 11, 2001MUG 10-12-2022ND16-3-2023', 0, 0, 0, 1790967405032) ON CONFLICT(id) DO NOTHING;
