INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3d023c75d0a56096', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'How many prime ministers of Pakistan have completed a full five-year tenure after winning the general elections?', '{"A":"One","B":"Two","C":"Three","D":"None"}', 'D', NULL, 0, 0, 0, 1790967405049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_02a639aea3b11fc4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Name of Army operation in FATA?', '{"A":"Zarb-e-Azb","B":"Rah-e-Nijat","C":"both  A and B","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On June 15, the ongoing Pakistan Army operation "Operation Zarb-e-Azb" (Sharp Strike) completed its first year. The military operation is the first of its kind against the Islamist insurgents based in the North Waziristan district of the Federally Administered Tribal Areas (FATA) of Pakistan. However, there have been previous operations elsewhere in FATA since Pakistan''s first operation against al-Qaeda, Tarik-e-Taliban Pakistan (TTP) and other foreign Islamist militant groups in the area in 2002.', 0, 0, 0, 1790967405049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6822f5af2f1c95ea', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The highest non- operational Military award is?', '{"A":"Tamgha-e- Basalat","B":"Sitar-e-Basalat","C":"Tamgha-e-Imtiaz","D":"Tamgha-e-Khidmat"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Sitara-e-Basalat (Star of Good Conduct) is a non-operational gallantry award of Pakistan Armed Forces given to individuals for distinguished acts of gallantry, valor or courage while performing their duty. It is given by President of Pakistan on the recommendation of service chief. *******VU CBT FIA SI ASI PAPER 13-12-2021', 0, 0, 0, 1790967405049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cf061e7ef769cd8b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'The year 1971 is remembered for', '{"A":"Independence of Pakistan","B":"Disintegration of Pakistan","C":"Pakistan became member of UN","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation 1971 was a dark year in Pakistan''s history and it was squarely our fault, make no mistake about it. During the late hours of March 25, 1971 the Awami League leader, Sheikh Mujibur Rehman, announced the independence of East Pakistan in the form of Bangladesh.', 0, 0, 0, 1790967405049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_93ba4eb2766ccddc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Mahmud of Ghazni Waged war against rebellious India in the year:', '{"A":"900 AD","B":"1000 AD","C":"1100 AD","D":"1200 AD"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation In 1001 Mahmud of Ghazni first invaded modern-day Pakistan and then parts of India.On 28 November 1001, his army fought and defeated the army of Raja Jayapala of the Kabul Shahis at the Battle of PeshawarThe battle of Peshawar was fought on 27 November 1001 between the Ghaznavid army of Mahmud of Ghazni and the Hindu Shahi army of Jayapala, near Peshawar.ND5.3.2023', 0, 0, 0, 1790967405049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c28d55b33ba503f0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'In Rann of Kutch dispute in 1965, Pakistan declared frontier between Pakistan and India is?', '{"A":"24th Parallel Line","B":"34th Parallel Line","C":"49th Parallel Line","D":"None of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indo-Pakistani War of 1965 involved skirmishes between April and September 1965.Pakistan claims the 24th Parallel as the boundary in the Rann of Kutch, but India does not recognize it.The "Treaty of Rann of Kutch" was signed on 30 June 1965, resolving the territorial dispute.', 0, 0, 0, 1790967405049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7eef951916eb592e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Who mediated 1965 war', '{"A":"Aleksey Kosygin","B":"Bush","C":"Ibrahm","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The 1965 war between India and Pakistan was the second conflict between the two countries over the status of the state of Jammu and Kashmir.The agreement was mediated by Soviet premier Aleksey Kosygin, who had invited the parties to Tashkent', 0, 0, 0, 1790967405049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1f6a7d826e72b3b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Who was the second Governer general of Pakistan?', '{"A":"Sir Khawaja Nazimuddin","B":"Muhammad Ali Bogra","C":"Gulam Muhammad","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation NamePortraitEntered officeLeft officeDate of Birth and DeathPolitical party1Muhammad Ali JinnahMuhammad Ali Jinnah15 August 194711 September 194825 December 1876 – 11 September 1948Muslim League2Sir Khawaja Nazimuddin14 September 194817 October 195119 July 1894 - 22 October 1964Muslim League3Ghulam Mohammad17 October 19516 October 195520 April 1895 - 12 September 19564Iskander Mirza6 October 195523 March 195613 November 1899 - 12 November 1969Republican Party', 0, 0, 0, 1790967405049) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7187c1a347b4f9a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_military', 'Russia and Japan fought a war in 1904. Russia was defeated. The war is called:', '{"A":"Battle of Leipzig","B":"Battle of Salamis","C":"Russo-Japanese War","D":"Battle of Yalu"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation CANS:Russo-Japanese War, (1904–05), military strife in which a triumphant Japan constrained Russia to abandon its expansionist approach in East Asia, subsequently getting to be the primary Asian control in cutting edge times to overcome a European control.', 0, 0, 0, 1790967405064) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_pks_economy', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'Economy & Development', 'top_pakistan_study', 57, 1790967405080) ON CONFLICT(id) DO UPDATE SET total_mcqs = 57;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_61d1513d0465e117', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'The Largest export of Pakistan is _____?', '{"A":"Oil","B":"Gold","C":"Taxtile","D":"All above mentioned"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The largest export of Pakistan is textilesKey Products: Garments, knitwear, bedwear, towelsThe United States is Pakistan''s largest export market.Faisalabad is called the Manchester of Pakistan (the country''s largest hub for textile manufacturing)Last updated by NA ON 16-09-2026', 0, 0, 0, 1790967405099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_0f19db0622c06b4e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'The Currency of Pakistan is?', '{"A":"Kina","B":"Dinaar","C":"Pond","D":"Rupee"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Currency: Pakistani Rupee (PKR)First currency note: Rs. 2First coin: Issued on 3 January 1948First coin designer: BrandleyAdditional informationNational Animal: MarkhorNational Tree: DeodarNational Dish: NihariNational Fruit: MangoNational Flower: JasmineNational Vegetable: Lady Finger (Okra)Field hockey is Pakistan''s official national sport.Last updated by NA on 15-09-2026', 0, 0, 0, 1790967405099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ff728fba2bb1b38f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'The headquarters of State Bank of Pakistan is situated in?', '{"A":"Quetta","B":"Peshawar","C":"Karachi","D":"Faisalbad"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Headquarters: Karachi, Sindh Founded: 1-July-1948Founded by: Muhammad Ali JinnahFirst Governor: Zahid HussainFirst Female Governor: Shamshad AkhtarSBP Responsibility: Implement monetary policyLast verified on 13-09-2026', 0, 0, 0, 1790967405099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a9333eada1ce0ee0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Pakistan’s main export item is ______?', '{"A":"Wood and furniture","B":"Cotton and cotton manufactures","C":"Wheat and flour","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan’s economy largely depends on the textile sector, which is based on cotton production.Cotton and cotton manufactured products are the largest share of Pakistan’s exports.The textile industry includes yarn, cloth, garments, and towels exported worldwide.Major export markets include USA, China, UK, Germany, and UAE.Last verified on 08-03-2026', 0, 0, 0, 1790967405099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_90fb0a1a5cec653e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Which is the biggest/largest industry of Pakistan?', '{"A":"Textile","B":"Agriculture","C":"Pottery","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cotton textile production and apparel manufacturing are Pakistan''s largest industries.It accounts for about 65% of the merchandise exportsThe textile industry employs about 45% of the country''s labor force. Pakistan is the fourth largest producer of cotton in the world. Pakistan is the eighth largest exporter of textiles in Asia.Last verified on 01-09-2026', 0, 0, 0, 1790967405099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a1fe34de38a49e41', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Which is the major crop of Pakistan? Rice, Sugarcane, Cotton, Wheat', '{"A":"Rice","B":"Sugarcane","C":"Cotton","D":"Wheat"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Wheat is the major and staple crop of Pakistan.It is the most widely grown food grain in the country.Wheat is mainly grown in Punjab and Sindh provinces.It is used to make flour (atta), a basic food in Pakistan.Wheat season: Rabi crop (winter season).Last verified on 01-06-2026', 0, 0, 0, 1790967405099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_7dc7f72faea0e5ac', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Pakistan''s largest trade partner in imports is?', '{"A":"UK","B":"China","C":"USA","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation China is Pakistan''s largest trade partner in imports.The country imports a wide range of goods from China.Including machinery, electronics, and textiles.This making it a key player in Pakistan''s trade dynamics.Last verified on 26-07-2026', 0, 0, 0, 1790967405099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_39fa4dc379dd5b2a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'When did First Women Bank Limited (FWBL) commence its business?', '{"A":"2 December 1989","B":"21 November 1989","C":"1 January 1990","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation First Women Bank Limited (FWBL) commenced its business on 2 December 1989.FWBL is a commercial bank established to promote women''s financial empowerment in Pakistan.The bank was set up in December 1988 during the government of Prime Minister Benazir Bhutto.Headquarters: Karachi, Pakistan.Last verified on 23-07-2026', 0, 0, 0, 1790967405099) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_41b453a75327f0cd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'The Picture on the back of 10 Rupee Pakistani Note?', '{"A":"Khyber Pass","B":"Attock Pass","C":"Bolan Pass","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rs. 10: Khyber PassRs. 5000: Faisal MosqueRs. 10: Khyber PassRs. 100: Quaid-e-Azam ResidencyRs. 500: Badshahi MosqueRs. 1000: Islamia College PeshawarAdditional information:Pakistani currency notes feature important national landmarks on the back side.The State Bank of Pakistan issued first banknotes on 1 October 1948.Printed by: Thomas De La Rue & Company (UK)Last verified on 01-04-2026', 0, 0, 0, 1790967405119) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a1ad60bf35173368', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Who presented Poor Man''s Budget in 1946?', '{"A":"Ch. Muhammad Ali","B":"Liaquat Ali Khan","C":"Sir Agha Khan","D":"Ch. Rehmat Ali."}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The historic "Poor Man''s Budget" (1947-1948) was presented by Liaquat Ali KhanAt that time Finance Member of the Interim Government of IndiaHe introduced this iconic, pro-poor budget on February 28, 1947Last updated by NA on 16-07-2026', 0, 0, 0, 1790967405119) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_54e81c68c7316c8d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Which is the largest export partner of Pakistan?', '{"A":"Japan","B":"Iran","C":"America","D":"Nepal"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Largest Export Partner: United States (America)Major Exports to the U.S.:TextilesReadymade garmentsLeather productsSports goodsSurgical instrumentsAdditional information:Largest Import Partner: ChinaLast verified on 10-07-2026', 0, 0, 0, 1790967405119) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3fb4264588aa3169', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Which is the major Kharif crop of Pakistan?', '{"A":"Maize","B":"Wheat","C":"Gram","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Major Kharif CropsRiceSugarcaneCottonMaizeBajraJowarAdditional information:Kharif Crop PeriodStart: April – JuneEnd: September – OctoberRabi Crop PeriodSowing: October – DecemberHarvesting: March – MayLast verified on 27-01-2026', 0, 0, 0, 1790967405119) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_b070dfc0344fc219', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Which is a major crop of the Rabi season?', '{"A":"Rice","B":"Wheat","C":"Cotton","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rabi crops are sown in winter (October–December) and harvested in spring (March–April).Wheat is the major Rabi crop, especially in Pakistan and India.Additional information:Kharif crops are sown in summer (April–June) and harvested in autumn (September–October).Rice is the major Kharif crop, grown during the monsoon season.Last verified on 24-05-2026', 0, 0, 0, 1790967405119) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1fa12496b31d5689', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'What is contribution of agriculture to Pakistan''s GDP?', '{"A":"30%","B":"39%","C":"24%","D":"32%"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Agriculture remains a key contributor to Pakistan’s economy.It directly contributes close to 24% of the country’s Gross Domestic Product (GDP).Last verified on 03-02-2026', 0, 0, 0, 1790967405119) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_e5576afdd9974cc6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Pakistani Currency notes are issued by?', '{"A":"National Bank","B":"MCB","C":"HBL","D":"State Bank of Pakistan"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The State Bank of Pakistan (SBP) has the sole authority to issue currency notes in Pakistan.This power is given under Section 24 of the State Bank of Pakistan Act.The first emergency notes were printed by De La Rue & Company between 1948 and 1960 in denominations of:5 Rupees10 Rupees100 RupeesAdditional information:Established: 1 July 1948Headquarters: Karachi, PakistanFounder: Government of PakistanMain Function: Regulate banking system and issue currency notesLast verified on 11-05-2026', 0, 0, 0, 1790967405119) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_08cc16cde4ceb0a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Who introduced firstly the silver coin (rupee) named "Rupia" in the Indian subcontinent?', '{"A":"Sher Shah Suri","B":"Sikandar Azam","C":"Mahmood Ghaznavi","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation During his five-year rule from 1540 to 1546.Sher Shah Suri set up a new civic and military administration.He issued a coin of silver, weighing 178 grains.It was also termed the Rupiya.The silver coin remained in use during the Mughal period, the Maratha era (1674–1818) and in British India, as well.Last verified on 30-04-2026', 0, 0, 0, 1790967405119) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_bd9c59476353fc25', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'The Picture on the back of the 5000 Rupee Pakistani Note?', '{"A":"Jatoi Mosque","B":"Bashahi Mosque","C":"Faisal Mosque","D":"Masjid Wazir Khan"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Rs. 5000: Faisal MosqueRs. 10: Khyber PassRs. 100: Quaid-e-Azam ResidencyRs. 500: Badshahi MosqueRs. 1000: Islamia College PeshawarAdditional information:Pakistani currency notes feature important national landmarks on the back side.The State Bank of Pakistan issued first banknotes on 1 October 1948.Printed by: Thomas De La Rue & Company (UK)Last verified on 01-04-2026', 0, 0, 0, 1790967405138) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cca33f5122e626c3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Which one is the Kharif Crop among the following?', '{"A":"Wheat","B":"Barley","C":"Gram","D":"Cotton"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Major Kharif CropsRiceSugarcaneCottonMaizeBajraJowarAdditional information:Kharif Crop PeriodStart: April – JuneEnd: September – OctoberRabi Crop PeriodSowing: October – DecemberHarvesting: March – MayLast verified on 25-01-2026', 0, 0, 0, 1790967405138) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_6406b6ac14e14e5f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'The economy of Pakistan is based on ______?', '{"A":"Industry","B":"Forest","C":"Agriculture","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Agriculture contributes a major share to GDP (around one-fifth).Provides raw material to textile and sugar industries.Employs a large portion of the rural population.Major crops: Wheat, Cotton, Rice, Sugarcane, Maize.Irrigation mainly comes from the Indus River system.Last verified on 05-02-2026', 0, 0, 0, 1790967405138) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_81696f2c0a94334b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'What is Pakistan''s biggest export commodity?', '{"A":"Handmade Carpets","B":"Textiles","C":"Sports Goods","D":"Leather and Leather Products"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Textiles are Pakistan’s largest export commodity.The textile sector plays a key role in Pakistan’s economy and foreign exchange earnings.Additional information:Major textile export items:Cotton yarnReadymade garmentsBed wearTowelsKnitwearLast verified on 19-01-2026', 0, 0, 0, 1790967405138) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a2d5f7286431628d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Which sector is the largest contributor to Pakistan''s GDP?', '{"A":"Services","B":"Agriculture","C":"Manufacturing","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The services sector is the largest contributor to Pakistan’s GDP.It accounting for around 58% of the total GDP.Agriculture contributes about 23%.Industry/manufacturing contributes around 20%.Additional information:Services include finance, transport, education, health, and IT.Growth in services reflects urbanization and modernization of the economy.Last verified on 19-01-2026', 0, 0, 0, 1790967405138) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8ba0986333ceb4a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Pakistan’s major export earnings come from ______?', '{"A":"Wheat","B":"Sugarcane","C":"Barley","D":"Cotton"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Cotton is Pakistan’s major export commodity.It contributing significantly to foreign exchange earnings.It is used in the textile industry for making fabrics, garments, and yarn.Last verified on 19-01-2026', 0, 0, 0, 1790967405138) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_478d41afdcd76bb6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'Which of the following is a Rabi Crop?', '{"A":"Cotton","B":"Mustard","C":"Maize","D":"Rice"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Mustard is a Rabi crop.Rabi crop is grown in autumn or early winterThey harvested in spring or early summerThey are grown in October or November. major rabi crop in India and Pakistan is: wheat, barley, mustard, sesame, peas.Rabi crops are known as winter crops. ND23-4-2023', 0, 0, 0, 1790967405138) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_cde8c75026e0667b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'When National Bank of Pakistan established?', '{"A":"1948","B":"1947","C":"1949","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation National Bank was created on November 9, 1949, under National Bank of Pakistan Ordinance, 1949 for the purpose.The NBP has over 1,500 branches in Pakistan and more than 18 locations overseas.', 0, 0, 0, 1790967405138) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1a2cff544947c180', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_economy', 'When State Bank of Pakistan (SBP) was inaugurated?', '{"A":"1st July 1947","B":"1st August 1947","C":"1st July 1948","D":"1st August 1948"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The State Bank of Pakistan was inaugurated on 1st July 1948.The headquarters of the State Bank of Pakistan in Karachi Sindh.History of State BankZahid Husain was the founder and the first governor of the SBP from June 1948 to July 1953.Dr. Shamshad Akhtar was the first female Governor of the SBP in 2006.Quaid-e-Azam Muhammad Ali Jinnah inaugurated the State Bank of Pakistan.The Governor is appointed by the President of Pakistan.Term of five years.', 0, 0, 0, 1790967405156) ON CONFLICT(id) DO NOTHING;
