INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_db5770e390a9b90e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Who under the treaty of Amritsar in March 1846 Purchased Kashmir?', '{"A":"Gulab Singh","B":"Chum Sing","C":"Lan Singh","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Treaty of Amritsar, executed by the British East India Company and Raja Gulab Singh of Jammu.First Anglo-Sikh War, established the princely state of Jammu and Kashmir under the suzerainty of the British Indian Empire.', 0, 0, 0, 1790967405506) ON CONFLICT(id) DO NOTHING;
