INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a514a717d0932024', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'The Shimla agreement was signed between Zulfiqar Ali Bhutto and _______?', '{"A":"Indira Gandhi","B":"Morarji Desai","C":"Jawaharlal Nehru","D":"Manmohan Singh"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Shimla Agreement was signed on 2 July 1972 Signed between Indian Prime Minister Indira Gandhi and Pakistani President Z. A. Bhutto.Context : Indo-Pakistani War of 1971Location: Barnes Court (Raj Bhavan), Shimla, Himachal Pradesh, IndiaSealed: 7 August 1972Ratified: 15 July 1972 (by Pakistan), 3 August 1972 (by India)Effective: 4 August 1972Last updated by NA on 23-April-2026', 0, 0, 0, 1790967405557) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_c4746ba13e8ec4a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Boundary agreement was signed between Pakistan and China in?', '{"A":"2 March 1963","B":"2 March 1962","C":"2 March 1969","D":"2 March 1947"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation A boundary agreement was signed between Pakistan and China in 2 March 1963.Negotiations between the nations officially began on October 13, 1962.It was signed by:Foreign Minister Chen Yi for the Chinese Zulfikar Ali Bhutto for the Pakistani The eastern tip of the Wakhan Corridor starts the Sino-Pak border between the People''s Republic of China and Pakistan.', 0, 0, 0, 1790967405557) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_fc7a4ed84780e3e7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Who was the Pakistan''s first permanent representative in UNO?', '{"A":"Sir Zaffar Ullah Khan","B":"Liaqat Ali Khan","C":"Sardar Abdur Rab Nishtar","D":"Ahmed Shah Patras Bokhari","E":"None of these"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Syed Patras Bokhari was a diplomat who served as a Permanent Representative of Pakistan to the United Nations from 1951 to 1954.', 0, 0, 0, 1790967405557) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_8323d34e9fce8868', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Who gave suggestion for formation of SAARC?', '{"A":"Ziaur Rehman","B":"Shaikh Mujeeb ur Rehman","C":"ZA Bhutto","D":"All of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation President Ziaur Rahman of Bangladesh proposed the idea of SAARC in 1977.His vision for economic cooperation and cultural exchange among South Asian countries led to the establishment of SAARC in 1985.It consists of eight member states: Afghanistan, Bangladesh, Bhutan, India, Maldives, Nepal, Pakistan, and Sri Lanka."', 0, 0, 0, 1790967405557) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_09a7ec5e4ec82fc4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Which agreement Cease Fire Line to Line of Control?', '{"A":"Karachi Agreement","B":"Tashkent agreement","C":"Shimla agreement","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Shimla Agreement (1972) converted the Cease Fire Line (CFL) into the Line of Control (LoC) between India and Pakistan, following the 1971 Indo-Pakistani War.This agreement aimed to establish a lasting peace and normalize relations between the two nations.The cease-fire line was originally established on January 1, 1949, when India and Pakistan declared a ceasefire after fighting over Kashmir.', 0, 0, 0, 1790967405557) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3db73a8ecc8e2caa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Pakistan and China established diplomatic relations on _____?', '{"A":"21 May 1951","B":"21 May 1950","C":"21 May 1952","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan becomes the third non-communist country, and first Muslim one, to recognize the People''s Republic of China. In 1951 Beijing and Karachi establish diplomatic relations.Pakistan and China established diplomatic relations on May 21, 1951.This marked the beginning of a strong bilateral relationship.The partnership has grown in various sectors, including trade, defense, and cultural exchange.', 0, 0, 0, 1790967405557) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_33577b9043836813', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'The country which opened its first embassy in Pakistan?', '{"A":"Iran","B":"Afghanistan","C":"Egypt","D":"Turkey"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan opened its first embassy in Iran on 14 August 1947Iran and Pakistan established relations on 14 August 1947, the day of the independence of Pakistan Iran became the first country to recognize Pakistan.Ambassador Riffat Masood became Pakistan’s first woman envoy to the Islamic Republic of IranNA22-9-2023', 0, 0, 0, 1790967405577) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2797e2a20807659e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'China Pakistan Economic Corridor will be fully operational by _____?', '{"A":"2030","B":"2020","C":"2028","D":"2025"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The China-Pakistan Economic Corridor (CPEC) is expected to be fully operational by 2030.The China-Pakistan Economic Corridor (CPEC) is a series of energy and infrastructure projects, some of which connect China’s Xinjiang to Gwadar.Initiated in mid-2013 and formally launched in April 20, 2015.CPEC is generally described as a $46 billion package of Chinese aid.', 0, 0, 0, 1790967405577) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a903bb42d202a0da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'First Pakistani writer who represented Pakistan in UNO?', '{"A":"Deputy Nazir Anmed","B":"Moulana Hali","C":"Moulana Zafar Ali Khan","D":"Ahmed Shah Bukhari Patras"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The first Pakistani writer who represented Pakistan in the UNO is Ahmed Shah Bukhari Patras.Pakistan joined the United Nations on September 30, 1947, shortly after its independence on August 14, 1947.The Permanent Representative of Pakistan to the United Nations is Pakistan''s diplomatic representative to the United Nations.', 0, 0, 0, 1790967405577) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2542d7593442ec96', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Name the water-related treaty between Pakistan and India?', '{"A":"Treaty of Water","B":"Indo Pak-Water Treaty","C":"Indus Water Treaty","D":"None of these"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The Indus Water Treaty allocates the Western Rivers (Indus, Jhelum, Chenab) to Pakistanwhileand the Eastern Rivers (Ravi, Beas, Sutlej) to India**Indus Waters Treaty, treaty, signed on September 19, 1960, between India and PakistanIndus Water Treaty between India and Pakistan was brokered by World Bank***The Treaty was signed at Karachi by Field Marshal Mohammad Ayub Khan,the then President of Pakistan, Jawaharlal Nehru the then Indian Prime Minister, and Mr. W.A.B. Illif The Treaty is effective from 1st April 1960 ***************', 0, 0, 0, 1790967405577) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_ad5a6f81c97667c9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Pakistan joined SCO as a full member at a summit 9 June 2017 in?', '{"A":"Astana","B":"Moscow","C":"Shanghai","D":"none of the above"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation On 9 June 2017, at a summit in Astana, India and Pakistan officially joined SCO as full members.On 9 June, 2017 India and Pakistan became full members of the Shanghai Cooperation Organisation (SCO).The SCO Headquarters: Beijing, ChinaThe SCO Founded: June 15, 2001The SCO currently comprises of nine Members States (China, India, Kazakhstan, Kyrgyzstan, Russia, Pakistan, Tajikistan, Iran and Uzbekistan), four Observer StatesOn 9 July 2023, Iran became 9th member of SCO.', 0, 0, 0, 1790967405577) ON CONFLICT(id) DO NOTHING;
