INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a40e5ddc93985e2e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Shimla agreement was signed in :', '{"A":"1971","B":"1972","C":"1973","D":"1974"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Signed July 2, 1972, at Shimla, IndiaBy Indira Gandhi and Zulfikar Ali BhuttoAfter the 1971 India-Pakistan War (creation of Bangladesh)Aim: settle disputes through peaceful bilateral talks1971 ceasefire line → Line of Control (LoC)Presided over by Lord Wavell35 Muslim members took part', 0, 0, 0, 1790967405591) ON CONFLICT(id) DO NOTHING;
