INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_580651909636f856', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Pakistan opened its first embassy in which country?', '{"A":"Iraq","B":"USA","C":"Iran","D":"China"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan opened its first embassy in Iran.Iran was the first to recognize Pakistan. Iran was the first to open its embassy in Pakistan.Iran and Pakistan established relations on 14 August 1947, the day of the independence of Pakistan', 0, 0, 0, 1790967405591) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_14c1c2872d522dbe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Pakistan''s position on the Fissile Material Cut-off Treaty (FMCT) is that', '{"A":"Pre-existing stockpiles should be included in the draft of the FMCT before negotiations","B":"Ban on nuclear testing be lifted before signing of the draft","C":"A criteria-based approach be applied to the NSG before finalizing the FMCT","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan has long advocated for the inclusion of pre-existing fissile material stockpiles in the scope of the Fissile Material Cut-off Treaty (FMCT).', 0, 0, 0, 1790967405591) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3211848ec5bd0d4a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Fourth Summit of SAARC was held in 1988 in:', '{"A":"Dhaka (Bangladesh)","B":"Islamabad (Pakistan)","C":"Colombo (Sri Lanka)","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Islamabad Pakistan. The fourth summit became held in Islamabad, Pakistan on 29–31 December 1988 and become attended by means of the presidents of Bangladesh, the Maldives and Sri Lanka, the prime ministers of India and Pakistan, and the kings of Bhutan and Nepal.', 0, 0, 0, 1790967405591) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_f94421e49e6a57e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_intl', 'Who came to Pakistan after the earthquake as a special representative of UNO''s earthquake relief?', '{"A":"Bill Clinton","B":"War of Roses","C":"Kofi Annan","D":"George W. Bush","E":"George Bush Sr"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Former U.S. President George H. W. Bush was appointed by UN Secretary-General Kofi Annan as the Special Envoy for the South Asian Earthquake Disaster after the devastating 2005 quake in PakistanArrived in Pakistan on January 16, 2006, Additional information:The significant earthquake that prompted major UNO relief efforts, particularly in 2005 in Pakistan/KashmiMagnitude: 7.6.Date: October 8, 2005.Occurred at 08:50:39 Pakistan Standard Time More than 80,000 people perished as a result of the quake,Cuba dispatched a large medical contingent,', 0, 0, 0, 1790967405591) ON CONFLICT(id) DO NOTHING;
INSERT INTO subject (id, user_id, name, parent_id, total_mcqs, created_at) VALUES ('top_pks_symbols', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'National Symbols & Facts', 'top_pakistan_study', 55, 1790967405602) ON CONFLICT(id) DO UPDATE SET total_mcqs = 55;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_2b76e7d9a613f3b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'Which is the national bird of Pakistan?', '{"A":"Parrot","B":"Chakor","C":"Pigeon","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation The national bird of Pakistan is the Chukar Partridge (Alectoris chukar).It was officially designated in 1985.The Shaheen Falcon is the symbolic bird of the Pakistan Air Force.Additional information:National Animal: MarkhorNational Tree: DeodarNational Dish: NihariNational Fruit: MangoNational Flower: JasmineNational Vegetable: Lady Finger (Okra)Last verified on 08-03-2026', 0, 0, 0, 1790967405615) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_543c5c61c3838b30', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'Which animal is the national animal of Pakistan?', '{"A":"Tiger","B":"Lion","C":"Arabian horse","D":"Markhor"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Markhor is the national animal of Pakistan.“Markhor” means “snake eater.”It is known as a symbol of bravery and sharp intelligence.It is large wild goat (Capra species).It is found in Central Asia, the Karakoram, and the Himalayan regions.Additional information:National Bird: ChukarNational Tree: DeodarNational Dish: NihariNational Fruit: MangoNational Flower: JasmineNational Vegetable: Lady Finger (Okra)Last verified on 10-06-2026', 0, 0, 0, 1790967405615) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_a257d88c8b89ab63', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'The National Anthem of Pakistan is written by?', '{"A":"Allama Iqbal","B":"Quaid-e-Azam","C":"Chaudry Rehmat Ali","D":"Hafiz Jalandhri"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Writer: Hafeez Jullundhri in 1952Composer: Ahmed G. Chagla in 1949.Duration: Approximately 80 secondsStructure: Three stanzas with no repeated versesFirst Recorded: 1954 by Ahmed Rushdi.Officially adopted on 13 August 1954.15 lines 48 WordsPlayed for the first time in front of Raza Shah Rahalvi of Iran."Jan-i-Istaqbal" stands for the Symbol of ambitions.اس کے متعلق سوالات پڑھیںNational SymbolsLast verified on 28-06-2026', 0, 0, 0, 1790967405615) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_3e5c462788411978', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'Which is the National game of Pakistan?', '{"A":"Hockey","B":"Cricket","C":"Badminton","D":"Boxing"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan InformationNational Game HockeyNational AnimalMarkhorNational Language UrduNational DressShalwar KamizNational PoetAllama IqbalLast verified on 26-09-2026', 0, 0, 0, 1790967405615) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_d8a784d5f4550751', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'Defence day is celebrated in Pakistan on which date?', '{"A":"6th September","B":"23rd March","C":"11th September","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Defence Day is celebrated as the sacrifices made by Pakistani soldiers in defending its borders.Defence Day is celebrated in Pakistan on September 6The event Length of Day is 1 DayThe day was first celebrated in 1965Defence Day is Also called: Youm-e-Difa****', 0, 0, 0, 1790967405615) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_9dedc9ef0e164328', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'Which is the National language of Pakistan?', '{"A":"English","B":"Punjabi","C":"Urdu","D":"Bengali"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Urdu is the national language of Pakistan. Article 251: The 1973 Constitution of Pakistan formally declares Urdu as the national languageAdditional informationNational Animal: MarkhorNational Tree: DeodarNational Dish: NihariNational Fruit: MangoNational Flower: JasmineNational Vegetable: Lady Finger (Okra)Field hockey is Pakistan''s official national sport.Last updated by NA on 09-09-2026', 0, 0, 0, 1790967405615) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_1c365a1cd6e29008', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'Which is the National Tree of Pakistan?', '{"A":"Deodar","B":"Neem","C":"Peepul","D":"None of these"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Deodar is the National tree of Pakistan.It is also known as Himalayan Cedar (Cedrus Deodara).Its name is derived from ''Sanskrit'' and means "Wood of the God".It is amongst the tallest trees in the country.Its heights of around 40-50 meters.Additional information:National Bird: ChukarNational Animal: MarkhorNational Dish: NihariNational Fruit: MangoNational Flower: JasmineNational Vegetable: Lady Finger (Okra)Last verified on 08-03-2026', 0, 0, 0, 1790967405615) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tp_5ad27a5ec1fd3a06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_pks_symbols', 'How many times Pakistan won the hockey World Cup?', '{"A":"2","B":"4","C":"6","D":"None of these"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Pakistan has won the Hockey World Cup 4 times.1971 – Barcelona, Spain1978 – Buenos Aires, Argentina1982 – Mumbai, India1994 – Sydney, AustraliaLast verified on 25-06-2026', 0, 0, 0, 1790967405615) ON CONFLICT(id) DO NOTHING;
